window.ANSWER_TERMS = {"ribosoom":{"title":"Ribosoom","short":"Moleculaire machine die met behulp van mRNA aminozuren aaneenrijgt tot een eiwit (translatie).","definition":"<p>Het <b>ribosoom</b> is opgebouwd uit ribosomaal RNA en eiwitten. Het leest de codons van het mRNA af en koppelt de bijbehorende aminozuren aan elkaar.</p><p>Ribosomen komen vrij in het cytoplasma voor of gebonden aan het ruw endoplasmatisch reticulum.</p>","image_url":"","wiki_title":"Ribosome","match":"ribosoom|ribosomen"},"keratine":{"title":"Keratine","short":"Vezelig structuureiwit (intermediair filament) dat opperhuid, haren en nagels stevigheid en waterbestendigheid geeft.","definition":"<p><b>Keratine</b> is een taai, onoplosbaar structuureiwit uit de groep intermediaire filamenten. Keratinocyten maken het aan terwijl ze naar de oppervlakte schuiven.</p><p>In het stratum corneum vormen dode, met keratine gevulde cellen een waterafstotende barrière. Keratine is ook het hoofdbestanddeel van haar en nagels.</p>","image_url":"","wiki_title":"Keratin","match":"keratine"},"endocriene signalering":{"title":"Endocriene signalering","short":"Klieren geven hormonen af aan het bloed, dat ze naar verre doelorganen vervoert.","definition":"<p>Bij <b>endocriene signalering</b> scheiden endocriene klieren hormonen rechtstreeks in de bloedbaan uit.</p><p>Via het bloed bereiken de hormonen doelcellen elders in het lichaam die de bijbehorende receptor dragen. Het effect is trager maar wijdverbreid.</p>","image_url":"","wiki_title":"Endocrine system","match":"endocriene signalering|endocrien|endocriene secretie|endocriene celsignalering"},"glycolipide":{"title":"Glycolipide","short":"Lipide met een suikergroep aan de buitenkant van de celmembraan; betrokken bij herkenning en bescherming.","definition":"<p>Een <b>glycolipide</b> is een membraanlipide waaraan aan de buitenzijde een suikerketen hangt.</p><p>Samen met glycoproteïnen vormt het de glycocalyx, die een rol speelt bij celherkenning en bescherming van het celoppervlak.</p>","image_url":"","wiki_title":"Glycolipid","match":"glycolipide|glycolipiden"},"glycoproteine":{"title":"Glycoproteïne","short":"Eiwit met aangehechte suikerketens; veel membraan- en secretie-eiwitten zijn geglycosyleerd.","definition":"<p>Een <b>glycoproteïne</b> is een eiwit waaraan tijdens de rijping in ER en Golgi suikerketens zijn gekoppeld (glycosylering).</p><p>Ze zitten veel in de celmembraan en in secreten en spelen een rol bij herkenning, adhesie en bescherming.</p>","image_url":"","wiki_title":"Glycoprotein","match":"glycoproteïne|glycoproteine|glycoproteïnen|glycoproteinen|glycoproteinen"},"cholesterol":{"title":"Cholesterol","short":"Vetachtige stof die de celmembraan stevigheid en de juiste vloeibaarheid geeft en grondstof is voor steroïden.","definition":"<p><b>Cholesterol</b> is een steroïd dat tussen de fosfolipiden van de celmembraan zit en de membraanvloeibaarheid stabiliseert.</p><p>Het is bovendien de grondstof voor steroïdhormonen, vitamine D en galzouten.</p>","image_url":"","wiki_title":"Cholesterol","match":"cholesterol"},"fagocytose":{"title":"Fagocytose","short":"Het 'opeten' van grote deeltjes of hele cellen (zoals bacteriën) door een cel via insluiting in een fagosoom.","definition":"<p><b>Fagocytose</b> is een vorm van endocytose waarbij een cel grote deeltjes omsluit, zoals bacteriën, celresten of stofdeeltjes.</p><p>Het gevormde fagosoom versmelt met een lysosoom, waarna de inhoud wordt verteerd. Neutrofielen en macrofagen zijn de belangrijkste fagocyten.</p>","image_url":"","wiki_title":"Phagocytosis","match":"fagocytose"},"necrose":{"title":"Necrose","short":"Ongecontroleerde celdood door schade, waarbij de cel opzwelt, openbarst en een ontstekingsreactie uitlokt.","definition":"<p><b>Necrose</b> is celdood door acute schade (zuurstoftekort, toxinen, trauma). De cel zwelt op en de membraan scheurt.</p><p>De vrijkomende celinhoud lokt een ontstekingsreactie uit — anders dan bij de 'nette' apoptose.</p>","image_url":"","wiki_title":"Necrosis","match":"necrose"},"stratum corneum":{"title":"Stratum corneum","short":"De buitenste hoornlaag van dode, met keratine gevulde cellen; de eigenlijke huidbarrière.","definition":"<p>Het <b>stratum corneum</b> is de buitenste laag van de epidermis: platte, dode cellen (corneocyten) vol keratine, ingebed in een lipidenlaag.</p><p>Deze 'bakstenen-en-cement'-structuur vormt de belangrijkste barrière tegen uitdroging en indringers. De cellen schilferen geleidelijk af.</p>","image_url":"","wiki_title":"Stratum corneum","match":"stratum corneum"},"epidermis":{"title":"Epidermis","short":"De opperhuid: het bovenste, uit meerlagig verhoornend plaveiselepitheel opgebouwde deel van de huid.","definition":"<p>De <b>epidermis</b> (opperhuid) is de buitenste huidlaag, opgebouwd uit meerlagig verhoornend plaveiselepitheel zonder bloedvaten.</p><p>Ze bestaat vooral uit keratinocyten in opeenvolgende lagen (basale → hoornlaag) en levert de beschermende barrière.</p>","image_url":"","wiki_title":"Epidermis","match":"epidermis|de epidermis"},"dermis":{"title":"Dermis","short":"De lederhuid onder de epidermis: bindweefsel met collageen, bloedvaten, zenuwen, klieren en haarfollikels.","definition":"<p>De <b>dermis</b> (lederhuid) ligt onder de epidermis en bestaat uit bindweefsel met collageen en elastine.</p><p>Ze bevat bloedvaten, zenuwuiteinden, zweet- en talgklieren en haarfollikels en geeft de huid stevigheid en elasticiteit. Men onderscheidt een papillaire en een reticulaire dermis.</p>","image_url":"","wiki_title":"Dermis","match":"dermis|de dermis|papillaire dermis|reticulaire dermis"},"subcutis":{"title":"Subcutis","short":"Het onderhuidse vetweefsel dat isoleert, energie opslaat en als stootkussen dient.","definition":"<p>De <b>subcutis</b> (onderhuids bindweefsel, hypodermis) is de diepste laag en bestaat vooral uit vetweefsel.</p><p>Ze isoleert tegen kou, slaat energie op, dempt stoten en verbindt de huid met onderliggende structuren.</p>","image_url":"","wiki_title":"Subcutaneous tissue","match":"subcutis|de subcutis|hypodermis"},"keratinocyt":{"title":"Keratinocyt","short":"De hoofdcel van de epidermis; produceert keratine en bouwt al opschuivend de huidbarrière op.","definition":"<p>De <b>keratinocyt</b> maakt ongeveer 90% van de epidermiscellen uit. Vanuit het stratum basale schuift hij omhoog terwijl hij steeds meer keratine vormt.</p><p>Bovenaan aangekomen is hij een dode, verhoornde cel die de barrière vormt en uiteindelijk afschilfert.</p>","image_url":"","wiki_title":"Keratinocyte","match":"keratinocyt|keratinocyten"},"Langerhanscel":{"title":"Langerhanscel","short":"Dendritische immuuncel in de epidermis die antigenen opvangt en aan T-cellen presenteert.","definition":"<p>De <b>Langerhanscel</b> is een dendritische cel, vooral in het stratum spinosum. Hij vangt binnendringende antigenen op.</p><p>Vervolgens migreert hij naar de lymfeklier en presenteert het antigeen aan T-lymfocyten — de schakel tussen huid en afweer.</p>","image_url":"","wiki_title":"Langerhans cell","match":"langerhanscel|langerhanscellen|langerhans cel|langerhans cellen|cellen van langerhans"},"mestcel":{"title":"Mestcel","short":"Weefselcel vol histaminekorrels die bij allergie en ontsteking degranuleert.","definition":"<p>De <b>mestcel</b> (mastcel) zit in de dermis en andere weefsels en is volgepakt met korrels vol histamine en andere ontstekingsmediatoren.</p><p>Bij binding van allergenen aan IgE op zijn oppervlak stort hij zijn korrels uit (degranulatie), wat jeuk, roodheid en zwelling geeft.</p>","image_url":"","wiki_title":"Mast cell","match":"mestcel|mestcellen|mastcel"},"neutrofiele granulocyt":{"title":"Neutrofiele granulocyt","short":"Meest voorkomende witte bloedcel en eerste verdedigingslinie tegen bacteriën via fagocytose.","definition":"<p>De <b>neutrofiele granulocyt</b> is de talrijkste leukocyt, met een gelobde kern, en als eerste ter plaatse bij een bacteriële infectie.</p><p>Hij ruimt bacteriën op door fagocytose en enzymen; dode neutrofielen vormen samen met bacterieresten de pus.</p>","image_url":"","wiki_title":"Neutrophil","match":"neutrofiele granulocyt|neutrofiele granulocyten"},"eosinofiele granulocyt":{"title":"Eosinofiele granulocyt","short":"Witte bloedcel met rood-kleurende korrels, actief bij afweer tegen parasieten en bij allergie.","definition":"<p>De <b>eosinofiele granulocyt</b> heeft korrels die met eosine roodroze aankleuren en meestal een tweelobbige kern.</p><p>Hij is betrokken bij de afweer tegen wormparasieten en bij allergische processen zoals astma en eczeem; het aantal is dan vaak verhoogd.</p>","image_url":"","wiki_title":"Eosinophil","match":"eosinofiele granulocyt|eosinofiele granulocyten"},"monocyt":{"title":"Monocyt","short":"Grootste witte bloedcel; verlaat het bloed en rijpt in de weefsels uit tot macrofaag of dendritische cel.","definition":"<p>De <b>monocyt</b> is de grootste circulerende leukocyt, met een niervormige kern. Hij circuleert enkele dagen en migreert dan de weefsels in.</p><p>Daar differentieert hij tot macrofaag of dendritische cel, die pathogenen fagocyteren en antigenen presenteren.</p>","image_url":"","wiki_title":"Monocyte","match":"monocyt|monocyten"},"macrofaag":{"title":"Macrofaag","short":"Grote fagocyt in de weefsels die pathogenen en celresten opruimt en antigenen presenteert.","definition":"<p>De <b>macrofaag</b> ontstaat uit een monocyt die het weefsel is binnengegaan. Hij fagocyteert bacteriën, dode cellen en afval.</p><p>Als antigeenpresenterende cel activeert hij ook T-cellen en scheidt hij ontstekingsmediatoren uit. In de huid heten verwante cellen histiocyten.</p>","image_url":"","wiki_title":"Macrophage","match":"macrofaag|macrofagen"},"lymfocyt":{"title":"Lymfocyt","short":"Witte bloedcel van de specifieke afweer; omvat de B-cellen (antistoffen) en T-cellen.","definition":"<p>De <b>lymfocyt</b> is de sleutelcel van het adaptieve (specifieke) immuunsysteem. B-lymfocyten maken antistoffen; T-lymfocyten doden geïnfecteerde cellen of sturen de afweer aan.</p><p>Lymfocyten circuleren tussen bloed, lymfe en lymfoïde organen.</p>","image_url":"","wiki_title":"Lymphocyte","match":"lymfocyt|lymfocyten"},"thymus":{"title":"Thymus","short":"Lymfoïd orgaan achter het borstbeen waar T-lymfocyten uitrijpen en geselecteerd worden.","definition":"<p>De <b>thymus</b> (zwezerik) ligt achter het borstbeen. Hier rijpen T-lymfocyten uit en worden ze getest op nut en veiligheid (positieve en negatieve selectie).</p><p>De thymus is het actiefst in de jeugd en neemt daarna geleidelijk af.</p>","image_url":"","wiki_title":"Thymus","match":"thymus"},"milt":{"title":"Milt","short":"Lymfoïd orgaan dat oude bloedcellen afbreekt en bloedgedragen ziekteverwekkers filtert.","definition":"<p>De <b>milt</b> filtert het bloed: de rode pulpa ruimt versleten erytrocyten op, de witte pulpa herbergt lymfocyten voor de afweer tegen bloedgedragen pathogenen.</p><p>Ook dient de milt als bloedreservoir.</p>","image_url":"","wiki_title":"Spleen","match":"milt"},"beenmerg":{"title":"Beenmerg","short":"Weefsel in de holten van botten waar alle bloedcellen worden gevormd (hematopoëse).","definition":"<p>Het <b>beenmerg</b> vult de holten van botten. In het rode beenmerg vindt de hematopoëse plaats: de vorming van rode en witte bloedcellen en bloedplaatjes uit stamcellen.</p><p>Het is tevens de plaats waar B-lymfocyten uitrijpen.</p>","image_url":"","wiki_title":"Bone marrow","match":"beenmerg|het beenmerg"},"lymfeklier":{"title":"Lymfeklier","short":"Filterstation in de lymfebaan waar antigenen worden gepresenteerd en de afweerreactie op gang komt.","definition":"<p>De <b>lymfeklier</b> filtert de lymfe en is een ontmoetingsplaats voor antigeenpresenterende cellen en lymfocyten.</p><p>Hier worden T- en B-cellen geactiveerd; bij infectie zwellen lymfeklieren op doordat de lymfocyten zich vermenigvuldigen.</p>","image_url":"","wiki_title":"Lymph node","match":"lymfeklier|lymfeklieren|lymfklier|lymfklieren"},"macula":{"title":"Macula","short":"Vlakke, niet-voelbare huidverandering die alleen in kleur verschilt (een 'vlek').","definition":"<p>Een <b>macula</b> is een plat, met de vinger niet-voelbaar plekje dat zich alleen door kleur onderscheidt van de omgeving.</p><p>Voorbeelden zijn een sproet of een café-au-lait-vlek. Wordt hij groter dan ~1 cm, dan spreekt men van een patch.</p>","image_url":"","wiki_title":"Skin condition","match":"macula|maculae"},"papula":{"title":"Papula","short":"Klein, vast, verheven en voelbaar huidknobbeltje (< ~1 cm).","definition":"<p>Een <b>papula</b> (papel) is een klein, stevig, verheven bultje kleiner dan ongeveer 1 cm dat je kunt voelen.</p><p>Voorbeelden zijn een insectenbeet-reactie of de bultjes bij acne. Meerdere versmolten papels vormen een plaque.</p>","image_url":"","wiki_title":"Papule","match":"papula|papel|papels|papula's|papula’s|papels"},"plaque":{"title":"Plaque","short":"Verheven, plateauvormige huidafwijking groter dan ~1 cm, vaak door samenvloeien van papels.","definition":"<p>Een <b>plaque</b> is een verheven, afgeplatte laesie groter dan ongeveer 1 cm — breder dan hoog.</p><p>Ze ontstaat vaak door het samenvloeien van papels en is typisch voor psoriasis.</p>","image_url":"","wiki_title":"Skin condition","match":"plaque|plaques"},"nodulus":{"title":"Nodulus","short":"Vaste, verheven en voelbare knobbel die dieper in de huid reikt dan een papel (> ~1 cm).","definition":"<p>Een <b>nodulus</b> (nodus, knobbel) is een stevige, verheven laesie die groter is dan een papel en dieper in de dermis of subcutis reikt.</p><p>Voorbeelden zijn een dermatofibroom of sommige huidtumoren.</p>","image_url":"","wiki_title":"Nodule (medicine)","match":"nodulus|nodus|noduli|nodi"},"vesikel":{"title":"Vesikel","short":"Klein, met helder vocht gevuld blaasje in de huid (< ~1 cm).","definition":"<p>Een <b>vesikel</b> (vesicula) is een klein blaasje gevuld met helder vocht, kleiner dan ongeveer 1 cm.</p><p>Vesikels komen voor bij o.a. herpes, waterpokken en acuut eczeem. Een groter blaasje heet een bulla.</p>","image_url":"","wiki_title":"Blister","match":"vesikel|vesikels|vesicula|vesiculae"},"bulla":{"title":"Bulla","short":"Groot, met vocht gevuld blaar in de huid (> ~1 cm).","definition":"<p>Een <b>bulla</b> is een blaar gevuld met vocht die groter is dan ongeveer 1 cm.</p><p>Bullae komen voor bij brandwonden, bulleus pemfigoïd en pemphigus. Een kleiner exemplaar heet een vesikel.</p>","image_url":"","wiki_title":"Blister","match":"bulla|bullae"},"pustula":{"title":"Pustula","short":"Met pus gevuld blaasje in de huid (een 'puistje').","definition":"<p>Een <b>pustula</b> (pustel) is een verheven blaasje gevuld met pus (dode neutrofielen).</p><p>Pustels kunnen steriel zijn (psoriasis pustulosa) of door bacteriën ontstaan; ze zijn kenmerkend voor acne.</p>","image_url":"","wiki_title":"Pustule","match":"pustula|pustel|pustels|pustula|pustulae"},"urtica":{"title":"Urtica","short":"Vluchtige, jeukende, verheven zwelling van de huid — een 'galbult' of kwaddel.","definition":"<p>Een <b>urtica</b> (kwaddel, galbult) is een verheven, bleekroze zwelling door vochtophoping in de dermis, meestal sterk jeukend.</p><p>Ze ontstaat door histamine-afgifte (netelroos/urticaria) en verdwijnt doorgaans binnen 24 uur weer.</p>","image_url":"","wiki_title":"Hives","match":"urtica|urticae"},"crusta":{"title":"Crusta","short":"Korstje van ingedroogd wondvocht, bloed of pus op het huidoppervlak.","definition":"<p>Een <b>crusta</b> (korst) is opgedroogd exsudaat — wondvocht, bloed of pus — op de huid.</p><p>Het is een secundaire efflorescentie die ontstaat nadat een blaasje of wondje is opengegaan.</p>","image_url":"","wiki_title":"Crust (dermatology)","match":"crusta|crustae|korst"},"squama":{"title":"Squama","short":"Zichtbare hoornschilfer door versnelde of gestoorde verhoorning van de opperhuid.","definition":"<p>Een <b>squama</b> (schilfer) is een loskomend plaatje hoorncellen van het stratum corneum.</p><p>Overmatige schilfering is typerend voor psoriasis en ichthyosis.</p>","image_url":"","wiki_title":"Desquamation","match":"squama|squamae|schilfer|schilfering"},"erosie":{"title":"Erosie","short":"Oppervlakkig huiddefect beperkt tot de epidermis, dat zonder litteken geneest.","definition":"<p>Een <b>erosie</b> is een oppervlakkig verlies van epidermis, bijvoorbeeld nadat een blaasje is opengegaan.</p><p>Omdat de dermis intact blijft, geneest een erosie zonder litteken.</p>","image_url":"","wiki_title":"Erosion (dermatology)","match":"erosie|erosies"},"ulcus":{"title":"Ulcus","short":"Diep huiddefect tot in de dermis of dieper, dat met een litteken geneest (een 'zweer').","definition":"<p>Een <b>ulcus</b> (zweer) is een dieper weefselverlies dat tot in de dermis of subcutis reikt.</p><p>Doordat de dermis is aangetast, geneest het met littekenvorming. Een ulcus cruris (open been) is een bekend voorbeeld.</p>","image_url":"","wiki_title":"Ulcer (dermatology)","match":"ulcus|ulcera"},"excoriatie":{"title":"Excoriatie","short":"Oppervlakkig krab- of schaafdefect van de huid, vaak door krabben.","definition":"<p>Een <b>excoriatie</b> is een oppervlakkige beschadiging van de huid door mechanische kracht, meestal krabben.</p><p>Ze reikt tot in de bovenste dermis en gaat vaak gepaard met korstjes; typisch bij jeukende aandoeningen zoals eczeem.</p>","image_url":"","wiki_title":"Excoriation","match":"excoriatie|excoriaties"},"fissuur":{"title":"Fissuur","short":"Pijnlijke, spleetvormige scheur in de huid, vaak op handen of hielen (kloof/rhagade).","definition":"<p>Een <b>fissuur</b> (rhagade, kloof) is een smalle, spleetvormige scheur in de huid die tot in de dermis kan reiken.</p><p>Ze ontstaat vooral in droge, verdikte huid op belaste plaatsen zoals vingers, handen en hielen, en kan pijnlijk zijn.</p>","image_url":"","wiki_title":"Fissure","match":"fissuur|rhagade|rhagaden|kloof"},"lichenificatie":{"title":"Lichenificatie","short":"Verdikking van de huid met versterkte huidlijnen door langdurig krabben of wrijven.","definition":"<p><b>Lichenificatie</b> is een leerachtige verdikking van de huid waarbij het normale huidreliëf grof geaccentueerd is.</p><p>Ze ontstaat door chronisch krabben of wrijven, zoals bij langdurig eczeem (lichen simplex chronicus).</p>","image_url":"","wiki_title":"Lichenification","match":"lichenificatie"},"comedo":{"title":"Comedo","short":"Verstopte talgklierporie: een mee-eter, open (zwart) of gesloten (wit).","definition":"<p>Een <b>comedo</b> (mee-eter) is een met talg en hoorncellen verstopte haarfollikel-opening.</p><p>Bij een open comedo oxideert het talg en wordt het zwart (blackhead); een gesloten comedo blijft wit (whitehead). Comedonen zijn de basislaesie van acne.</p>","image_url":"","wiki_title":"Comedo","match":"comedo|comedonen|comedo's"},"hyperkeratose":{"title":"Hyperkeratose","short":"Verdikking van de hoornlaag (stratum corneum) door overmatige verhoorning.","definition":"<p><b>Hyperkeratose</b> is een verdikte hoornlaag door versterkte aanmaak of vertraagde afstoting van hoorncellen.</p><p>Het komt voor bij eelt, wratten, psoriasis en ichthyosis.</p>","image_url":"","wiki_title":"Hyperkeratosis","match":"hyperkeratose"},"seborroische keratose":{"title":"Seborroïsche keratose","short":"Veelvoorkomende goedaardige, wratachtige 'ouderdomswrat' die opgeplakt lijkt te zitten.","definition":"<p>Een <b>seborroïsche keratose</b> is een goedaardige, wratachtige huidwoekering die er 'opgeplakt' uitziet.</p><p>Ze komt vaak voor op oudere leeftijd (ouderdomswrat) en is onschuldig; wel belangrijk om te onderscheiden van een melanoom.</p>","image_url":"","wiki_title":"Seborrheic keratosis","match":"seborroïsche keratose|seborrhoïsche keratose|seborroische keratose|seborrhoisch|seborroisch"},"lichen simplex chronicus":{"title":"Lichen simplex chronicus","short":"Verdikte, gelichenificeerde huidplek door een vicieuze cirkel van jeuk en krabben.","definition":"<p><b>Lichen simplex chronicus</b> is een sterk gelichenificeerde (leerachtig verdikte) plek die ontstaat door chronisch krabben en wrijven.</p><p>Jeuk lokt krabben uit, wat de huid verdikt en de jeuk versterkt: een jeuk-krab-cyclus.</p>","image_url":"","wiki_title":"Lichen simplex chronicus","match":"lichen simplex chronicus"},"constitutioneel eczeem":{"title":"Constitutioneel eczeem","short":"Chronisch, jeukend, atopisch eczeem met een gestoorde huidbarrière; begint meestal op de kinderleeftijd.","definition":"<p><b>Constitutioneel eczeem</b> (atopische dermatitis) is een chronische, jeukende huidontsteking die vaak al bij baby's begint.</p><p>Een gestoorde huidbarrière (o.a. door filaggrine-defect) en atopische aanleg spelen een rol. Bij kinderen zit het typisch in de elleboog- en knieplooien.</p>","image_url":"","wiki_title":"Atopic dermatitis","match":"constitutioneel eczeem|atopisch eczeem|atopische dermatitis"},"allergisch contacteczeem":{"title":"Allergisch contacteczeem","short":"Vertraagde (type IV) allergische huidreactie op een stof waarvoor men gevoelig is geworden, zoals nikkel.","definition":"<p><b>Allergisch contacteczeem</b> is een type IV (vertraagde) allergische reactie: na eerdere sensibilisatie geven T-cellen bij hernieuwd contact een eczeemreactie.</p><p>Bekende allergenen zijn nikkel, parfums en conserveermiddelen. Het eczeem verschijnt 1–3 dagen na contact op de blootgestelde plek.</p>","image_url":"","wiki_title":"Contact dermatitis","match":"allergisch contacteczeem"},"teleangiectasie":{"title":"Teleangiëctasie","short":"Blijvend verwijde, met het blote oog zichtbare kleine bloedvaatjes in de huid.","definition":"<p>Een <b>teleangiëctasie</b> is een permanent verwijd klein bloedvaatje dat als een fijn rood lijntje zichtbaar is en met een glaasje weg te drukken is.</p><p>Ze komen voor bij rosacea, na langdurig corticosteroïdgebruik, bij zonschade en als kenmerk van het basaalcelcarcinoom.</p>","image_url":"","wiki_title":"Telangiectasia","match":"teleangiectasie|teleangiëctasie|telangiëctasie|telangiectasie"},"puntmutatie":{"title":"Puntmutatie","short":"Verandering van één enkele DNA-base.","definition":"<p>Een <b>puntmutatie</b> is de vervanging, invoeging of verwijdering van één enkele base in het DNA.</p><p>Afhankelijk van het effect op het codon spreekt men van een stille, missense of nonsense mutatie.</p>","image_url":"","wiki_title":"Point mutation","match":"puntmutatie"},"mrna":{"title":"mRNA","short":"Boodschapper-RNA dat de genetische code van het DNA naar de ribosomen brengt voor eiwitsynthese.","definition":"<p><b>mRNA</b> (messenger RNA) is de kopie van een gen die tijdens transcriptie in de kern wordt gemaakt.</p><p>Het reist naar het cytoplasma, waar ribosomen de codons aflezen om er een eiwit van te maken (translatie).</p>","image_url":"","wiki_title":"Messenger RNA","match":"mrna|messenger rna|boodschapper-rna"},"trna":{"title":"tRNA","short":"Transport-RNA dat aminozuren aanvoert en via zijn anticodon aan het juiste mRNA-codon koppelt.","definition":"<p><b>tRNA</b> (transfer RNA) is een klein RNA-molecuul dat aan de ene kant een specifiek aminozuur draagt en aan de andere kant een anticodon.</p><p>Op het ribosoom paart het anticodon met het mRNA-codon, zodat de aminozuren in de juiste volgorde worden ingebouwd.</p>","image_url":"","wiki_title":"Transfer RNA","match":"trna|transfer rna"},"pneumonie":{"title":"Pneumonie","short":"Een pneumonie is een infectie van het longweefsel (alveoli), meestal door bacteriën of virussen, met koorts, hoesten en kortademigheid.","definition":"<p>Bij een <strong>pneumonie</strong> (longontsteking) raken de alveoli ontstoken en vullen ze zich met ontstekingsvocht en cellen. Daardoor is minder longoppervlak beschikbaar voor gaswisseling.</p><p>Typische klachten zijn koorts, hoesten (vaak met sputum), kortademigheid en soms pijn bij het ademen. Bij lichamelijk onderzoek kunnen crepitaties of een gedempte percussie optreden; een X-thorax toont een infiltraat. De meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie is <em>Streptococcus pneumoniae</em>.</p>","image_url":"","wiki_title":"Pneumonia","match":"pneumonie|longontsteking","option_only":true},"escherichia coli":{"title":"Escherichia coli","short":"E. coli is een gramnegatieve staafbacterie die normaal in de darm leeft en de belangrijkste verwekker is van urineweginfecties.","definition":"<p><strong><em>Escherichia coli</em></strong> is een gramnegatieve, facultatief anaerobe staaf uit de familie van de <em>Enterobacteriaceae</em>. Het is een normaal onderdeel van de darmflora.</p><p>Buiten de darm is E. coli de belangrijkste verwekker van urineweginfecties (cystitis, pyelonefritis) en een belangrijke oorzaak van sepsis en neonatale meningitis. Sommige stammen (zoals EHEC en ETEC) veroorzaken diarree; EHEC kan via shigatoxine het hemolytisch-uremisch syndroom veroorzaken.</p>","image_url":"","wiki_title":"Escherichia coli","match":"escherichia coli|e. coli|e.coli","option_only":true},"streptococcus pneumoniae":{"title":"Streptococcus pneumoniae","short":"De pneumokok is een grampositieve diplokok met een kapsel; de belangrijkste verwekker van pneumonie, otitis media en bacteriële meningitis.","definition":"<p><strong><em>Streptococcus pneumoniae</em></strong> (pneumokok) is een grampositieve, lancetvormige diplokok die α-hemolyse geeft op bloedagar. Het polysacharidekapsel is de belangrijkste virulentiefactor: het beschermt tegen fagocytose.</p><p>De pneumokok koloniseert de nasofarynx en is de meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie, otitis media, sinusitis en bacteriële meningitis bij volwassenen. Kinderen en ouderen worden ertegen gevaccineerd.</p>","image_url":"","wiki_title":"Streptococcus pneumoniae","match":"streptococcus pneumoniae|s. pneumoniae|pneumokok|pneumokokken|streptococcus pneumoniae (pneumokok)","option_only":true},"staphylococcus aureus":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"staphylococcus aureus|s. aureus|stafylococcus aureus","option_only":true},"staphylococcus epidermidis":{"title":"Staphylococcus epidermidis","short":"S. epidermidis is een coagulasenegatieve stafylokok van de normale huidflora; berucht om infecties van lijnen en prothesen.","definition":"<p><strong><em>Staphylococcus epidermidis</em></strong> is een grampositieve, <em>coagulase-negatieve</em> stafylokok die normaal op de huid leeft.</p><p>Hij is weinig virulent, maar kan een <em>biofilm</em> vormen op kunstmateriaal. Daardoor is hij een belangrijke verwekker van infecties van intravasculaire katheters, kunstkleppen en gewrichtsprothesen. In een bloedkweek is hij ook vaak een verontreiniging vanuit de huid.</p>","image_url":"","wiki_title":"Staphylococcus epidermidis","match":"staphylococcus epidermidis|s. epidermidis","option_only":true},"pseudomonas aeruginosa":{"title":"Pseudomonas aeruginosa","short":"P. aeruginosa is een gramnegatieve, aerobe staaf die van vochtige omgevingen houdt en vooral bij verzwakte patiënten ziekenhuisinfecties veroorzaakt.","definition":"<p><strong><em>Pseudomonas aeruginosa</em></strong> is een gramnegatieve, strikt aerobe staaf die leeft in water en vochtige omgevingen. Hij is van nature resistent tegen veel antibiotica.</p><p>Hij veroorzaakt vooral opportunistische infecties: ziekenhuispneumonie (o.a. bij beademing), infecties van brandwonden, urineweginfecties bij katheters, otitis externa en chronische luchtweginfecties bij cystische fibrose. Kolonies hebben vaak een groenblauw pigment en een zoete geur.</p>","image_url":"","wiki_title":"Pseudomonas aeruginosa","match":"pseudomonas aeruginosa|p. aeruginosa|pseudomonas","option_only":true},"klebsiella pneumoniae":{"title":"Klebsiella pneumoniae","short":"K. pneumoniae is een gramnegatieve staaf met een dik kapsel die urineweginfecties en (ziekenhuis)pneumonie veroorzaakt.","definition":"<p><strong><em>Klebsiella pneumoniae</em></strong> is een gramnegatieve staaf uit de <em>Enterobacteriaceae</em> met een dik polysacharidekapsel, waardoor kolonies slijmerig zijn.</p><p>Hij veroorzaakt urineweginfecties, sepsis en pneumonie, vooral bij ouderen, alcoholisten en patiënten met diabetes of in het ziekenhuis. Klebsiella is berucht om antibioticaresistentie (ESBL- en carbapenemaseproducerende stammen).</p>","image_url":"","wiki_title":"Klebsiella pneumoniae","match":"klebsiella pneumoniae|k. pneumoniae|klebsiella","option_only":true},"haemophilus influenzae":{"title":"Haemophilus influenzae","short":"H. influenzae is een kleine gramnegatieve staaf die luchtweginfecties, otitis en (vroeger vaak) meningitis en epiglottitis bij kinderen veroorzaakt.","definition":"<p><strong><em>Haemophilus influenzae</em></strong> is een kleine, gramnegatieve coccobacil. Ondanks de naam veroorzaakt hij geen influenza (dat is een virus).</p><p>Onomkapselde stammen veroorzaken otitis media, sinusitis en exacerbaties van COPD. Het omkapselde type b (Hib) veroorzaakte vroeger veel meningitis en epiglottitis bij jonge kinderen; sinds de Hib-vaccinatie is dat zeldzaam.</p>","image_url":"","wiki_title":"Haemophilus influenzae","match":"haemophilus influenzae|h. influenzae|haemophilus|haemofilus influenzae type b|haemophilus influenzae type b|hib","option_only":true},"mycobacterium tuberculosis":{"title":"Mycobacterium tuberculosis","short":"M. tuberculosis is de zuurvaste, langzaam groeiende staafbacterie die tuberculose veroorzaakt.","definition":"<p><strong><em>Mycobacterium tuberculosis</em></strong> is een aerobe staafbacterie met een wasachtige, mycolzuurrijke celwand. Daardoor kleurt hij niet goed met de gramkleuring maar wel met de Ziehl-Neelsenkleuring (<em>zuurvast</em>).</p><p>Hij wordt aerogeen overgedragen, groeit zeer langzaam (weken in kweek) en overleeft in macrofagen. De afweer is vooral cellulair (T-cellen) en leidt tot granulomen met centrale verkazing. Hij veroorzaakt tuberculose.</p>","image_url":"","wiki_title":"Mycobacterium tuberculosis","match":"mycobacterium tuberculosis|m. tuberculosis|tuberkelbacil","option_only":true},"candida albicans":{"title":"Candida albicans","short":"Candida albicans is een gist die normaal op slijmvliezen voorkomt en bij verminderde weerstand spruw, vaginale schimmelinfectie of invasieve infecties geeft.","definition":"<p><strong><em>Candida albicans</em></strong> is een gist (schimmel) die bij veel mensen in mond, darm en vagina voorkomt. Hij kan zowel als ronde gistcel als met (pseudo)hyfen groeien.</p><p>Bij een verstoorde flora (antibiotica) of verminderde afweer veroorzaakt hij oppervlakkige infecties zoals spruw (orale candidiasis), vaginale candidiasis en intertrigo. Bij ernstig immuungecompromitteerden of patiënten met lijnen kan een invasieve candidemie ontstaan.</p>","image_url":"","wiki_title":"Candida albicans","match":"candida albicans|c. albicans|candida","option_only":true},"adenovirus":{"title":"Adenovirus","short":"Adenovirussen zijn niet-omhulde DNA-virussen die verkoudheid, keelontsteking, conjunctivitis en gastro-enteritis veroorzaken.","definition":"<p><strong>Adenovirussen</strong> zijn niet-omhulde, dubbelstrengs DNA-virussen. Omdat ze geen envelop hebben, zijn ze stabiel in de omgeving en lastig te inactiveren.</p><p>Ze veroorzaken vooral bij kinderen infecties van de bovenste luchtwegen (faryngitis), conjunctivitis (o.a. faryngoconjunctivale koorts), gastro-enteritis en soms pneumonie. Ze worden ook gebruikt als vector in vaccins en gentherapie.</p>","image_url":"","wiki_title":"Adenoviridae","match":"adenovirus|adenovirussen","option_only":true},"mazelenvirus":{"title":"Mazelen(virus)","short":"Mazelen is een zeer besmettelijke virale kinderziekte met hoge koorts, hoesten, conjunctivitis en een vlekkerige huiduitslag; het virus is een omhuld RNA-virus.","definition":"<p><strong>Mazelen</strong> (morbilli) wordt veroorzaakt door het mazelenvirus, een omhuld enkelstrengs RNA-virus (paramyxovirus). Het is een van de meest besmettelijke ziekten en verspreidt zich via aerosolen.</p><p>Na een prodromale fase met koorts, hoesten, rhinitis en conjunctivitis verschijnen <em>Koplikvlekjes</em> op het wangslijmvlies en daarna een grofvlekkige rode huiduitslag die achter de oren begint. Complicaties zijn otitis, pneumonie en zeldzaam encefalitis (ook SSPE jaren later). Mazelen onderdrukt tijdelijk het immuunsysteem. Er is een vaccin (BMR).</p>","image_url":"","wiki_title":"Measles","match":"mazelenvirus|mazelen|morbilli|morbillivirus","option_only":true},"influenzavirus":{"title":"Influenza(virus)","short":"Influenza (griep) wordt veroorzaakt door het influenzavirus, een omhuld RNA-virus met hoge koorts, spierpijn en hoesten; jaarlijks seizoensgebonden.","definition":"<p><strong>Influenza</strong> wordt veroorzaakt door influenzavirussen (type A, B en C), omhulde RNA-virussen met een gesegmenteerd genoom. Op het oppervlak zitten hemagglutinine (H) en neuraminidase (N).</p><p>Kleine mutaties in H en N (<em>antigene drift</em>) veroorzaken de jaarlijkse griepepidemie; uitwisseling van gensegmenten (<em>antigene shift</em>, alleen type A) kan pandemieën geven. Klachten: plotselinge hoge koorts, spierpijn, hoofdpijn, droge hoest. Complicatie is o.a. een secundaire bacteriële pneumonie. Jaarlijks vaccin voor risicogroepen.</p>","image_url":"","wiki_title":"Influenza","match":"influenzavirus|influenza|griep|influenza a|influenzavirussen","option_only":true},"kinkhoest":{"title":"Kinkhoest (pertussis)","short":"Kinkhoest is een luchtweginfectie door Bordetella pertussis met langdurige hoestbuien en een gierende inademing; gevaarlijk voor zuigelingen.","definition":"<p><strong>Kinkhoest</strong> (pertussis) wordt veroorzaakt door de gramnegatieve bacterie <em>Bordetella pertussis</em>, die zich hecht aan het trilhaarepitheel en toxines produceert.</p><p>Na een verkoudheidsfase volgen weken met heftige hoestbuien, vaak eindigend in een gierende inademing (‘kink’) of braken. Bij jonge zuigelingen kan kinkhoest apneus en overlijden veroorzaken; daarom wordt gevaccineerd (ook zwangeren, om de baby te beschermen).</p>","image_url":"","wiki_title":"Whooping cough","match":"kinkhoest|pertussis|bordetella pertussis","option_only":true},"difterie":{"title":"Difterie","short":"Difterie is een infectie door Corynebacterium diphtheriae waarbij een toxine een grijs pseudomembraan in de keel en schade aan hart en zenuwen veroorzaakt.","definition":"<p><strong>Difterie</strong> wordt veroorzaakt door toxineproducerende stammen van <em>Corynebacterium diphtheriae</em>, een grampositieve staaf. Het difterietoxine remt de eiwitsynthese van gastheercellen.</p><p>Lokaal ontstaat een grijswit, vastzittend <em>pseudomembraan</em> in keel en neus, met risico op luchtwegobstructie. Het toxine kan systemisch myocarditis en neuropathie geven. Door vaccinatie (DKTP) is het in Nederland zeldzaam.</p>","image_url":"","wiki_title":"Diphtheria","match":"difterie|corynebacterium diphtheriae","option_only":true},"tetanus":{"title":"Tetanus","short":"Tetanus is een vergiftiging door het toxine van Clostridium tetani uit een wond, met pijnlijke spierkrampen en kaakklem.","definition":"<p><strong>Tetanus</strong> wordt veroorzaakt door <em>Clostridium tetani</em>, een anaerobe, sporenvormende grampositieve staaf die in de bodem voorkomt en via wonden binnenkomt.</p><p>Het toxine tetanospasmine blokkeert in het ruggenmerg de afgifte van remmende neurotransmitters (glycine, GABA). Daardoor ontstaan aanhoudende spiercontracties: kaakklem (trismus), risus sardonicus, opisthotonus en ademhalingsproblemen. Preventie: vaccinatie en wondverzorging.</p>","image_url":"","wiki_title":"Tetanus","match":"tetanus|clostridium tetani","option_only":true},"rode hond":{"title":"Rode hond (rubella)","short":"Rode hond is een milde virale ziekte met huiduitslag en zwollen klieren, maar bij infectie in de vroege zwangerschap ontstaat het congenitaal rubellasyndroom.","definition":"<p><strong>Rode hond</strong> (rubella) wordt veroorzaakt door het rubellavirus, een omhuld RNA-virus. Bij kinderen verloopt het mild: lichte koorts, kleinvlekkige huiduitslag en gezwollen lymfeklieren (o.a. achter de oren en in de nek).</p><p>Gevaarlijk is infectie van een zwangere in het eerste trimester: het virus kan de foetus besmetten en het <em>congenitaal rubellasyndroom</em> veroorzaken (doofheid, cataract, hartafwijkingen). Vaccinatie gebeurt met het BMR-vaccin.</p>","image_url":"","wiki_title":"Rubella","match":"rode hond|rubella|rubellavirus","option_only":true},"herpes zoster":{"title":"Herpes zoster (gordelroos)","short":"Herpes zoster is de reactivatie van het varicella-zostervirus uit een sensibel ganglion, met pijnlijke blaasjes in één dermatoom.","definition":"<p>Na waterpokken blijft het <strong>varicella-zostervirus</strong> latent aanwezig in sensibele ganglia (spinale ganglia of hersenzenuwganglia). Bij afnemende cellulaire afweer (ouderdom, immuunsuppressie) kan het reactiveren.</p><p>Dan ontstaan pijnlijke, gegroepeerde blaasjes op een rode ondergrond in één <em>dermatoom</em>, meestal eenzijdig. Complicaties zijn postherpetische neuralgie en, bij de n. ophthalmicus, oogbetrokkenheid (zoster ophthalmicus).</p>","image_url":"","wiki_title":"Shingles","match":"herpes zoster|gordelroos|zoster","option_only":true},"cytomegalovirus":{"title":"Cytomegalovirus (CMV)","short":"CMV is een herpesvirus dat bij gezonden mild verloopt, maar gevaarlijk is bij immuungecompromitteerden en de belangrijkste congenitale virale infectie is.","definition":"<p>Het <strong>cytomegalovirus</strong> is een herpesvirus (HHV-5) dat na infectie levenslang latent aanwezig blijft. Geïnfecteerde cellen worden groot met kenmerkende ‘uilenoog’-inclusies.</p><p>Bij gezonde mensen verloopt infectie meestal ongemerkt of als een mononucleosebeeld. Bij transplantatie- en hiv-patiënten kan CMV retinitis, pneumonie en colitis veroorzaken. Congenitale CMV is de belangrijkste infectieuze oorzaak van aangeboren doofheid en ontwikkelingsachterstand.</p>","image_url":"","wiki_title":"Cytomegalovirus","match":"cytomegalovirus|cmv","option_only":true},"norovirus":{"title":"Norovirus","short":"Norovirus is een zeer besmettelijk RNA-virus dat acute gastro-enteritis veroorzaakt met plotseling braken en diarree, vaak in uitbraken.","definition":"<p>Het <strong>norovirus</strong> is een niet-omhuld RNA-virus (calicivirus). Er zijn maar weinig deeltjes nodig voor infectie en het overleeft lang in de omgeving.</p><p>Het veroorzaakt acute gastro-enteritis met plotseling braken, waterige diarree en buikkrampen, die 1 à 3 dagen duurt. Uitbraken komen vooral voor in verpleeghuizen, ziekenhuizen en op cruiseschepen; handhygiëne is de belangrijkste maatregel.</p>","image_url":"","wiki_title":"Norovirus","match":"norovirus|noro","option_only":true},"hepatitis b":{"title":"Hepatitis B","short":"Hepatitis B is een via bloed en seks overgedragen DNA-virus dat acute en chronische leverontsteking geeft, met risico op cirrose en levercelcarcinoom.","definition":"<p><strong>Hepatitis B</strong> wordt veroorzaakt door het hepatitis B-virus, een omhuld (gedeeltelijk dubbelstrengs) DNA-virus. Overdracht via bloed, seksueel contact en van moeder op kind rond de geboorte.</p><p>Bij volwassenen geneest de meeste acute infectie; bij pasgeborenen wordt de infectie meestal <em>chronisch</em>. Chronische hepatitis B kan leiden tot levercirrose en hepatocellulair carcinoom. Diagnostiek via serologie (HBsAg, anti-HBc, anti-HBs). Er is een effectief vaccin.</p>","image_url":"","wiki_title":"Hepatitis B","match":"hepatitis b|hbv|hepatitis b-virus","option_only":true},"covid-19":{"title":"COVID-19","short":"COVID-19 is de ziekte veroorzaakt door het coronavirus SARS-CoV-2, met klachten van verkoudheid tot ernstige pneumonie.","definition":"<p><strong>COVID-19</strong> wordt veroorzaakt door <em>SARS-CoV-2</em>, een omhuld RNA-coronavirus dat via het spike-eiwit aan de ACE2-receptor bindt. Overdracht via druppels en aerosolen.</p><p>Het klinisch beeld varieert van geen klachten of verkoudheid tot een virale pneumonie met ARDS. Verlies van reuk en smaak was een opvallend symptoom. Risicofactoren voor een ernstig beloop zijn hoge leeftijd, obesitas en comorbiditeit.</p>","image_url":"","wiki_title":"COVID-19","match":"covid-19|covid|sars-cov-2|corona","option_only":true},"malaria":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"malaria|plasmodium|plasmodium falciparum","option_only":true},"meningitis":{"title":"Meningitis","short":"Meningitis is een ontsteking van de hersenvliezen, met hoofdpijn, koorts, nekstijfheid en verminderd bewustzijn; bacteriële meningitis is een spoedgeval.","definition":"<p><strong>Meningitis</strong> is een ontsteking van de leptomeningen (pia en arachnoidea) en de liquor. Oorzaken zijn bacteriën (bij volwassenen vooral pneumokok en meningokok), virussen (vaak milder) en zelden schimmels.</p><p>Klassieke symptomen: hoofdpijn, koorts, nekstijfheid en een verlaagd bewustzijn; bij meningokokken soms petechiën. Diagnose via lumbaalpunctie (liquoronderzoek). Bacteriële meningitis vereist direct antibiotica en dexamethason.</p>","image_url":"","wiki_title":"Meningitis","match":"meningitis|hersenvliesontsteking|bacteriële meningitis","option_only":true},"endocarditis":{"title":"Endocarditis","short":"Endocarditis is een infectie van het endocard, meestal van de hartkleppen, met vegetaties, koorts en een nieuw hartgeruis.","definition":"<p>Bij <strong>infectieuze endocarditis</strong> nestelen bacteriën (vaak <em>S. aureus</em>, streptokokken of enterokokken) zich op de hartkleppen en vormen vegetaties van bloedplaatjes, fibrine en micro-organismen.</p><p>Risicofactoren zijn klepafwijkingen, kunstkleppen en intraveneus drugsgebruik. Symptomen: koorts, een nieuw souffle en embolische verschijnselen (splinterbloedingen, Janewaylaesies, Oslernoduli, Rothvlekken). Diagnose via herhaalde bloedkweken en echocardiografie (Duke-criteria).</p>","image_url":"","wiki_title":"Infective endocarditis","match":"endocarditis|infectieuze endocarditis|bacteriële endocarditis","option_only":true},"pyelonefritis":{"title":"Pyelonefritis","short":"Pyelonefritis is een bacteriële infectie van het nierbekken en de nier, met koorts, flankpijn en vaak klachten van een blaasontsteking.","definition":"<p><strong>Pyelonefritis</strong> is een opstijgende urineweginfectie die de nier en het nierbekken bereikt, meestal door <em>E. coli</em>.</p><p>Kenmerkend zijn koorts, koude rillingen, flankpijn en slagpijn in de nierloge, eventueel met mictieklachten. Het is een gecompliceerde urineweginfectie die behandeld wordt met antibiotica met goede weefselpenetratie (niet nitrofurantoïne).</p>","image_url":"","wiki_title":"Pyelonephritis","match":"pyelonefritis|nierbekkenontsteking","option_only":true},"bètahemolytische streptokokken groep b":{"title":"Groep B-streptokok (GBS)","short":"De groep B-streptokok (Streptococcus agalactiae) komt voor in darm en vagina en is een belangrijke verwekker van sepsis en meningitis bij pasgeborenen.","definition":"<p><strong>Groep B-streptokokken</strong> (<em>Streptococcus agalactiae</em>) zijn grampositieve, bètahemolytische ketenkokken. Ze komen bij een deel van de vrouwen voor in darm en vagina zonder klachten.</p><p>Tijdens de bevalling kan de baby besmet raken, met risico op neonatale sepsis, pneumonie en meningitis (vooral in de eerste levensdagen). Bij risicofactoren krijgt de moeder antibiotica tijdens de bevalling.</p>","image_url":"","wiki_title":"Group B streptococcal infection","match":"bètahemolytische streptokokken groep b|groep b streptokokken|groep b-streptokokken|gbs|streptococcus agalactiae","option_only":true},"teichoïnezuur":{"title":"Teichoïnezuur","short":"Teichoïnezuren zijn polymeren in de dikke peptidoglycaanlaag van grampositieve bacteriën; ze dragen bij aan hechting en ontstekingsactivatie.","definition":"<p><strong>Teichoïnezuren</strong> zijn polymeren van glycerol- of ribitolfosfaat die verankerd zijn in de peptidoglycaanlaag (wandteichoïnezuur) of in de celmembraan (lipoteichoïnezuur) van <em>grampositieve</em> bacteriën.</p><p>Ze geven de celwand een negatieve lading, helpen bij hechting aan gastheercellen en worden door Toll-like receptoren (TLR2) herkend, waardoor ze een ontstekingsreactie uitlokken. Gramnegatieve bacteriën hebben ze niet.</p>","image_url":"","wiki_title":"Teichoic acid","match":"teichoïnezuur|teichoinezuur|lipoteichoïnezuur|teichoïnezuren","option_only":true},"recombinatie":{"title":"Recombinatie","short":"Recombinatie is het uitwisselen en opnieuw combineren van stukken DNA tussen twee DNA-moleculen, zoals bij crossing-over of na opname van vreemd DNA.","definition":"<p>Bij <strong>(genetische) recombinatie</strong> worden stukken DNA tussen twee DNA-moleculen uitgewisseld, waardoor nieuwe combinaties van genen ontstaan. Bij homologe recombinatie gebeurt dit tussen sterk gelijkende sequenties.</p><p>Bij eukaryoten treedt recombinatie op tijdens de meiose (crossing-over). Bij bacteriën is recombinatie de stap waarmee via transformatie, transductie of conjugatie binnengekomen DNA in het eigen chromosoom wordt ingebouwd.</p>","image_url":"","wiki_title":"","match":"recombinatie|genetische recombinatie|homologe recombinatie","option_only":true},"penicilline":{"title":"Penicilline","short":"Penicilline is een bètalactamantibioticum dat de celwandsynthese van vooral grampositieve bacteriën remt.","definition":"<p><strong>Penicilline</strong> (benzylpenicilline) is het oudste <em>bètalactamantibioticum</em>. Het bindt aan penicillinebindende eiwitten (transpeptidasen) en verhindert zo de verknoping van peptidoglycaan; de bacterie lyseert (bactericide).</p><p>Het werkt vooral tegen streptokokken, pneumokokken, meningokokken en <em>Treponema pallidum</em>. Bacteriën die bètalactamase produceren (zoals de meeste <em>S. aureus</em>) zijn resistent. De belangrijkste bijwerking is een allergische reactie, tot anafylaxie toe.</p>","image_url":"","wiki_title":"Penicillin","match":"penicilline|benzylpenicilline|penicilline g|feneticilline","option_only":true},"amoxicilline":{"title":"Amoxicilline","short":"Amoxicilline is een breedspectrum-penicilline die ook een deel van de gramnegatieve bacteriën dekt; veel gebruikt bij luchtweginfecties.","definition":"<p><strong>Amoxicilline</strong> is een aminopenicilline: een bètalactamantibioticum dat de celwandsynthese remt. Het spectrum is breder dan penicilline en omvat ook o.a. <em>H. influenzae</em> en <em>E. coli</em> (mits geen bètalactamase).</p><p>Het is in de huisartsenpraktijk eerste keus bij pneumonie en wordt ook gebruikt bij otitis en sinusitis. Met clavulaanzuur (amoxicilline-clavulaanzuur) is het ook werkzaam tegen bètalactamasevormers.</p>","image_url":"","wiki_title":"Amoxicillin","match":"amoxicilline|amoxicillin","option_only":true},"doxycycline":{"title":"Doxycycline","short":"Doxycycline is een tetracycline: een bacteriostatisch antibioticum dat de eiwitsynthese remt via het 30S-ribosoom.","definition":"<p><strong>Doxycycline</strong> behoort tot de <em>tetracyclines</em>. Het bindt aan de 30S-subeenheid van het bacteriële ribosoom en remt zo de eiwitsynthese (bacteriostatisch).</p><p>Het is werkzaam tegen veel luchtwegpathogenen en tegen intracellulaire verwekkers zoals <em>Chlamydia</em>, <em>Mycoplasma</em>, <em>Rickettsia</em> en <em>Borrelia</em> (ziekte van Lyme). Niet geven aan zwangeren en jonge kinderen (verkleuring van tanden en botten); kan fotosensibiliteit geven.</p>","image_url":"","wiki_title":"Doxycycline","match":"doxycycline","option_only":true},"meropenem":{"title":"Meropenem","short":"Meropenem is een carbapenem: een zeer breedspectrum-bètalactamantibioticum, gereserveerd voor ernstige of resistente infecties.","definition":"<p><strong>Meropenem</strong> is een <em>carbapenem</em>, een bètalactamantibioticum dat de celwandsynthese remt en stabiel is tegen de meeste bètalactamasen, inclusief ESBL.</p><p>Het heeft een zeer breed spectrum (grampositief, gramnegatief inclusief <em>Pseudomonas</em>, en anaeroben) en wordt intraveneus gegeven bij ernstige ziekenhuisinfecties. Om resistentie te voorkomen wordt het terughoudend gebruikt.</p>","image_url":"","wiki_title":"Meropenem","match":"meropenem|carbapenem|carbapenems","option_only":true},"paracetamol":{"title":"Paracetamol","short":"Paracetamol is een pijnstiller en koortsverlager zonder relevante ontstekingsremmende werking; bij overdosering levertoxisch.","definition":"<p><strong>Paracetamol</strong> werkt pijnstillend en koortsverlagend, vermoedelijk via remming van prostaglandinesynthese in het centrale zenuwstelsel. Perifeer is het nauwelijks ontstekingsremmend en het remt de bloedplaatjes niet.</p><p>Het is bij gewone dosering veilig en daarom eerste stap van de pijnladder. Bij overdosering raakt glutathion in de lever uitgeput en hoopt de toxische metaboliet NAPQI zich op, met levernecrose; het antidotum is acetylcysteïne.</p>","image_url":"","wiki_title":"Paracetamol","match":"paracetamol|acetaminofen","option_only":true},"prednison":{"title":"Prednison / prednisolon","short":"Prednison(olon) is een synthetisch glucocorticoïd met sterke ontstekingsremmende en immunosuppressieve werking.","definition":"<p><strong>Prednison</strong> is een prodrug die in de lever wordt omgezet in het actieve <strong>prednisolon</strong>. Beide zijn synthetische <em>glucocorticoïden</em>: ze binden aan de intracellulaire glucocorticoïdreceptor en veranderen de gentranscriptie.</p><p>Daardoor remmen ze de vorming van allerlei ontstekingsmediatoren en de activatie van ontstekingscellen. Gebruikt bij astma/COPD-exacerbaties, auto-immuunziekten en allergieën. Bijwerkingen bij langdurig gebruik: osteoporose, hyperglykemie, gewichtstoename, huidatrofie, infectierisico en bijnierschorsremming.</p>","image_url":"","wiki_title":"Prednisolone","match":"prednison|prednisolon|prednisone|prednisolone","option_only":true},"alcohol":{"title":"Alcohol (ethanol)","short":"Ethanol wordt in de lever afgebroken via acetaldehyde tot azijnzuur; overmatig gebruik schaadt lever, brein, hart en pancreas.","definition":"<p><strong>Ethanol</strong> wordt vooral in de lever geoxideerd door <em>alcoholdehydrogenase</em> tot acetaldehyde en daarna door aldehydedehydrogenase tot acetaat. Hierbij ontstaat veel NADH, wat de gluconeogenese remt (hypoglykemie) en vetstapeling in de lever bevordert.</p><p>Chronisch overmatig gebruik geeft leververvetting, alcoholische hepatitis en cirrose, pancreatitis, cardiomyopathie, hypertensie, neuropathie, thiaminetekort (Wernicke-Korsakov) en een verhoogd risico op verschillende kankers.</p>","image_url":"","wiki_title":"Alcohol (drug)","match":"alcohol|ethanol|alcoholgebruik|overmatig alcoholgebruik|alcoholmisbruik","option_only":true},"roken":{"title":"Roken","short":"Roken is de belangrijkste vermijdbare oorzaak van ziekte en sterfte: het veroorzaakt o.a. longkanker, COPD en hart- en vaatziekten.","definition":"<p>Tabaksrook bevat nicotine (verslavend), koolmonoxide, teer en tientallen kankerverwekkende stoffen. <strong>Roken</strong> beschadigt het luchtwegepitheel en het endotheel en bevordert ontsteking en trombose.</p><p>Het is een hoofdoorzaak van longkanker en andere kankers (o.a. mond, slokdarm, blaas), COPD, atherosclerose (myocardinfarct, CVA, perifeer arterieel vaatlijden) en complicaties in de zwangerschap. Stoppen loont op elke leeftijd.</p>","image_url":"","wiki_title":"Tobacco smoking","match":"roken|tabaksgebruik|tabak","option_only":true},"complement factoren":{"title":"Complement","short":"Het complementsysteem is een cascade van plasma-eiwitten die micro-organismen opsoneert, ontsteking aanjaagt en via het membraanaanvalscomplex cellen lyseert.","definition":"<p>Het <strong>complementsysteem</strong> bestaat uit plasma-eiwitten (C1–C9 en regulatoren) die in een cascade worden geactiveerd via de klassieke (antilichamen), de lectine- en de alternatieve route.</p><p>Belangrijke functies: <em>opsonisatie</em> (C3b), aantrekken van ontstekingscellen en mestcelactivatie (anafylatoxinen C3a en C5a) en lysis van micro-organismen door het <em>membraanaanvalscomplex</em> (C5b–C9). Tekort aan late complementfactoren geeft een verhoogd risico op <em>Neisseria</em>-infecties.</p>","image_url":"","wiki_title":"Complement system","match":"complement factoren|complementfactoren|complement|complementsysteem","option_only":true},"myocardinfarct":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"myocardinfarct|hartinfarct|acuut myocardinfarct|ami","option_only":true},"diabetes mellitus":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes mellitus|diabetes|suikerziekte|diabetes mellitus type 2|diabetes mellitus type 1|diabetes mellitus 2","option_only":true},"obesitas":{"title":"Obesitas","short":"Obesitas is ernstig overgewicht (BMI ≥30 kg/m²) met verhoogd risico op diabetes type 2, hart- en vaatziekten, artrose en bepaalde kankers.","definition":"<p>Bij <strong>obesitas</strong> is er een overmaat aan lichaamsvet, gedefinieerd als een <em>BMI ≥30 kg/m²</em>. Vooral vet in de buik (grote middelomtrek, visceraal vet) is metabool ongunstig.</p><p>Obesitas verhoogt het risico op insulineresistentie en diabetes type 2, hypertensie, dyslipidemie, hart- en vaatziekten, slaapapneu, leververvetting, artrose en verschillende vormen van kanker. Oorzaken zijn een combinatie van leefstijl, omgeving, genetische aanleg en soms medicatie of hormonale ziekten.</p>","image_url":"","wiki_title":"Obesity","match":"obesitas|ernstig overgewicht|adipositas","option_only":true},"systemische lupus erythematosus":{"title":"Systemische lupus erythematosus (SLE)","short":"SLE is een systemische auto-immuunziekte met antinucleaire antistoffen en immuuncomplexen; gewrichten, huid, nieren en bloed kunnen aangedaan zijn.","definition":"<p><strong>Systemische lupus erythematosus</strong> is een chronische auto-immuunziekte die vooral jonge vrouwen treft. Er worden antistoffen gevormd tegen kerncomponenten (ANA, anti-dsDNA, anti-Sm), die met antigenen <em>immuuncomplexen</em> vormen die neerslaan in weefsels (type III-reactie) en complement verbruiken.</p><p>Kenmerken: artralgie/artritis, vlindervormig erytheem in het gezicht, fotosensitiviteit, serositis, nefritis, cytopenieën en neurologische verschijnselen. Behandeling met o.a. hydroxychloroquine, corticosteroïden en immunosuppressiva.</p>","image_url":"","wiki_title":"Systemic lupus erythematosus","match":"systemische lupus erythematosus|sle|lupus|systemic lupus erythematosus","option_only":true},"sclerodermie (systemic sclerosis)":{"title":"Systemische sclerose (sclerodermie)","short":"Systemische sclerose is een auto-immuunziekte met fibrose van huid en organen en vaatafwijkingen; typisch zijn Raynaud, strakke huid en anti-Scl-70/anticentromeer.","definition":"<p>Bij <strong>systemische sclerose</strong> (sclerodermie) leiden auto-immuniteit en schade aan kleine bloedvaten tot overmatige collageenvorming en <em>fibrose</em> van huid en inwendige organen.</p><p>Bijna alle patiënten hebben het fenomeen van Raynaud. De huid wordt strak en verdikt (sclerodactylie), en er kunnen slikklachten (oesofagus), longfibrose, pulmonale hypertensie en een renale crisis ontstaan. Bij de beperkte vorm (CREST) zijn vaak anticentromeer-antistoffen aanwezig, bij de diffuse vorm anti-Scl-70 (topo-isomerase I).</p>","image_url":"","wiki_title":"Systemic scleroderma","match":"sclerodermie (systemic sclerosis)|sclerodermie|systemische sclerose|systemic sclerosis","option_only":true},"m. bechterew (ankylosing spondylitis)":{"title":"Ziekte van Bechterew (spondylitis ankylopoetica)","short":"De ziekte van Bechterew is een chronische ontsteking van de wervelkolom en SI-gewrichten, vaak bij jonge mannen met HLA-B27, met ochtendstijfheid en lage rugpijn.","definition":"<p>De <strong>ziekte van Bechterew</strong> is een axiale spondyloartritis: een chronische ontsteking van de <em>sacro-iliacale gewrichten</em> en de wervelkolom, met name de aanhechtingen van banden en pezen (enthesitis).</p><p>Ze begint meestal voor het 40e jaar met inflammatoire lage rugpijn: ochtendstijfheid, verbetering bij bewegen, ’s nachts pijn. Er is een sterke associatie met <em>HLA-B27</em>. Op termijn kan verbening de wervelkolom verstijven (‘bamboo spine’). Extra-articulair: uveïtis anterior, IBD en psoriasis.</p>","image_url":"","wiki_title":"Ankylosing spondylitis","match":"m. bechterew (ankylosing spondylitis)|m. bechterew|ziekte van bechterew|ankylosing spondylitis|spondylitis ankylopoetica|axiale spondyloartritis","option_only":true},"artrose (osteoarthritis)":{"title":"Artrose","short":"Artrose is degeneratie van gewrichtskraakbeen met botreactie; het geeft startpijn en pijn bij belasting, vooral in knieën, heupen en handen bij ouderen.","definition":"<p>Bij <strong>artrose</strong> slijt en verdwijnt het gewrichtskraakbeen, met reactieve veranderingen van het bot: <em>osteofyten</em>, subchondrale sclerose en cysten, en versmalling van de gewrichtsspleet op de röntgenfoto.</p><p>Risicofactoren: leeftijd, overgewicht, eerder letsel en aanleg. Klachten: pijn bij belasting, startpijn en korte ochtendstijfheid (&lt;30 minuten), soms crepitaties en verminderde beweeglijkheid. Typische plaatsen: knie, heup, DIP- en PIP-gewrichten (Heberden- en Bouchardknobbels) en het CMC-1-gewricht.</p>","image_url":"","wiki_title":"Osteoarthritis","match":"artrose (osteoarthritis)|artrose|osteoarthritis|osteoartrose","option_only":true},"septische artritis":{"title":"Septische artritis","short":"Septische artritis is een bacteriële infectie van een gewricht (vaak S. aureus): acuut, pijnlijk, gezwollen, warm gewricht met koorts; een spoedgeval.","definition":"<p>Bij <strong>septische artritis</strong> raakt een gewricht geïnfecteerd, meestal via de bloedbaan, soms na een punctie of operatie. De meest voorkomende verwekker is <em>Staphylococcus aureus</em>; bij seksueel actieve jongvolwassenen ook <em>Neisseria gonorrhoeae</em>.</p><p>Het geeft een acuut rood, warm, gezwollen en zeer pijnlijk gewricht (vaak de knie) met bewegingsbeperking en meestal koorts. Diagnose door punctie (troebel synoviaal vocht met veel leukocyten, kweek). Snel draineren en antibiotica zijn nodig om kraakbeenvernietiging te voorkomen.</p>","image_url":"","wiki_title":"Septic arthritis","match":"septische artritis|bacteriële artritis|septische arthritis","option_only":true},"reactieve artritis":{"title":"Reactieve artritis","short":"Reactieve artritis is een steriele gewrichtsontsteking enkele weken na een darm- of urogenitale infectie, vaak bij HLA-B27-dragers.","definition":"<p><strong>Reactieve artritis</strong> ontstaat 1–4 weken na een infectie van de darm (<em>Salmonella</em>, <em>Shigella</em>, <em>Campylobacter</em>, <em>Yersinia</em>) of de urogenitale tractus (<em>Chlamydia trachomatis</em>). Het gewricht zelf is niet geïnfecteerd.</p><p>Typisch is een asymmetrische oligoartritis van vooral de benen, eventueel met enthesitis, dactylitis, urethritis en conjunctivitis/uveïtis. Het behoort tot de spondyloartritiden en is geassocieerd met HLA-B27.</p>","image_url":"","wiki_title":"Reactive arthritis","match":"reactieve artritis|reactieve arthritis|ziekte van reiter","option_only":true},"henoch-schönlein vasculitis":{"title":"IgA-vasculitis (Henoch-Schönlein)","short":"IgA-vasculitis is een vasculitis van kleine vaten met IgA-neerslagen, vooral bij kinderen: palpabele purpura op de benen, buikpijn, artritis en nierbetrokkenheid.","definition":"<p><strong>IgA-vasculitis</strong> (vroeger Henoch-Schönlein purpura) is de meest voorkomende vasculitis bij kinderen, vaak na een bovenste luchtweginfectie. IgA-bevattende immuuncomplexen slaan neer in de wand van kleine vaten.</p><p>Kenmerkende tetrade: <em>palpabele purpura</em> op billen en benen (bij normale bloedplaatjes), artralgie/artritis, koliekachtige buikpijn (soms invaginatie) en nierbetrokkenheid (hematurie, IgA-nefropathie-achtig beeld). Meestal zelflimiterend; nierfunctie vervolgen.</p>","image_url":"","wiki_title":"IgA vasculitis","match":"henoch-schönlein vasculitis|henoch-schönlein purpura|henoch schönlein|iga-vasculitis|purpura van henoch-schönlein|de ziekte van henoch schönlein","option_only":true},"psoriasis vulgaris":{"title":"Psoriasis vulgaris","short":"Psoriasis is een chronische ontstekingsziekte van de huid met scherp begrensde rode plaques met zilverwitte schilfers, vaak op ellebogen, knieën en hoofdhuid.","definition":"<p>Bij <strong>psoriasis vulgaris</strong> stimuleert een T-cel-gemedieerde ontsteking (o.a. de IL-23/Th17-as) een sterk versnelde deling en onvolledige verhoorning van keratinocyten.</p><p>Dat geeft scherp begrensde, erythemateuze plaques met <em>zilverwitte schilfering</em>, typisch op de strekzijden (ellebogen, knieën), de hoofdhuid en de bilnaad. Kenmerkend zijn het köbnerfenomeen en nagelafwijkingen (putjes, olievlekken). Een deel van de patiënten ontwikkelt artritis psoriatica.</p>","image_url":"","wiki_title":"Psoriasis","match":"psoriasis vulgaris|psoriasis","option_only":true},"erytheem":{"title":"Erytheem","short":"Erytheem is roodheid van de huid door verwijding van de bloedvaatjes in de dermis; bij druk verbleekt het (wegdrukbaar).","definition":"<p><strong>Erytheem</strong> is een rode verkleuring van de huid door <em>hyperemie</em>: verwijde capillairen in de dermis. Kenmerkend is dat het bij druk (glasspateltest) wegdrukbaar is, in tegenstelling tot een bloeding in de huid (purpura, petechiën).</p><p>Het is een efflorescentie die voorkomt bij ontsteking, infectie (bijv. erysipelas), allergische reacties, zonverbranding en bij veel huidziekten.</p>","image_url":"","wiki_title":"Erythema","match":"erytheem|erythema|roodheid","option_only":true},"orthoergisch contacteczeem":{"title":"Orthoergisch contacteczeem","short":"Orthoergisch (irritatief) contacteczeem ontstaat door herhaald contact met irriterende stoffen zoals water en zeep, zonder allergie.","definition":"<p><strong>Orthoergisch contacteczeem</strong> is een niet-allergische ontsteking van de huid die ontstaat wanneer de huidbarrière herhaaldelijk wordt beschadigd door irriterende stoffen — bijvoorbeeld water, zeep, schoonmaakmiddelen of oplosmiddelen.</p><p>Het treft vooral de handen van mensen in natte beroepen (kappers, schoonmakers, zorgpersoneel). Er is geen sensibilisatie nodig, dus het kan bij iedereen optreden bij voldoende blootstelling. De huid is droog, rood, schilferend en kloverig.</p>","image_url":"","wiki_title":"Irritant contact dermatitis","match":"orthoergisch contacteczeem|irritatief contacteczeem|toxisch contacteczeem","option_only":true},"diarree":{"title":"Diarree","short":"Diarree is het vaker dan normaal (≥3x per dag) produceren van brijige tot waterdunne ontlasting.","definition":"<p><strong>Diarree</strong> betekent een verhoogde frequentie (meestal ≥3 keer per dag) en verminderde consistentie van de ontlasting. Acute diarree (&lt;2 weken) is meestal infectieus (virussen zoals norovirus, bacteriën, parasieten).</p><p>Mechanismen: <em>secretoir</em> (bijv. door toxines zoals choleratoxine), <em>osmotisch</em> (bijv. lactose-intolerantie, laxantia), <em>inflammatoir</em> (bijv. IBD, invasieve bacteriën, met bloed en slijm) en versnelde motiliteit. Het belangrijkste risico is uitdroging en elektrolytverlies.</p>","image_url":"","wiki_title":"Diarrhea","match":"diarree","option_only":true},"koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"koorts|febris|pyrexie|hoge koorts","option_only":true},"lever":{"title":"Lever","short":"De lever is de grootste klier van het lichaam: hij regelt stofwisseling van suikers, vetten en eiwitten, maakt gal en eiwitten (o.a. albumine, stollingsfactoren) en ontgift stoffen.","definition":"<p>De <strong>lever</strong> ligt rechtsboven in de buik en krijgt bloed uit de a. hepatica en (voor ±75%) uit de <em>v. portae</em>, met voedingsstoffen uit de darm.</p><p>Functies: opslag en afgifte van glucose (glycogeen, gluconeogenese), vet- en cholesterolmetabolisme, aanmaak van plasma-eiwitten (albumine, stollingsfactoren), ureumvorming, galproductie, afbraak van bilirubine en ontgifting van geneesmiddelen en alcohol. Functionele eenheden zijn de leverlobjes met hepatocyten rond sinusoïden.</p>","image_url":"","wiki_title":"Liver","match":"lever|hepar","option_only":true},"de milt":{"title":"Milt","short":"De milt filtert het bloed: hij ruimt oude en beschadigde rode bloedcellen op en vormt een afweerorgaan tegen bacteriën in het bloed.","definition":"<p>De <strong>milt</strong> ligt linksboven in de buik onder het diafragma. Ze bestaat uit <em>rode pulpa</em> (sinusoïden waar verouderde of afwijkende erytrocyten worden afgebroken) en <em>witte pulpa</em> (lymfatisch weefsel met B- en T-cellen rond arteriolen).</p><p>De milt is belangrijk voor de afweer tegen <em>gekapselde bacteriën</em> (pneumokok, meningokok, H. influenzae). Na splenectomie is het risico op een ernstige sepsis daardoor verhoogd; deze patiënten worden gevaccineerd.</p>","image_url":"","wiki_title":"Spleen","match":"de milt|milt|lien|splenomegalie","option_only":true},"b-cellen":{"title":"B-cellen","short":"B-cellen zijn lymfocyten die na activatie uitrijpen tot plasmacellen die antilichamen maken; ze rijpen in het beenmerg.","definition":"<p><strong>B-cellen</strong> ontstaan en rijpen in het beenmerg. Elke B-cel draagt een unieke B-celreceptor (membraangebonden antilichaam).</p><p>Na binding van een antigeen en meestal hulp van een T-helpercel (in de kiemcentra van lymfeklieren) prolifereren ze en differentiëren ze tot <em>plasmacellen</em> (antilichaamproductie) en geheugen-B-cellen. Daarbij vinden klasseswitch en affiniteitsrijping plaats. B-cellen kunnen ook antigeen presenteren.</p>","image_url":"","wiki_title":"B cell","match":"b-cellen|b cellen|b-lymfocyten|b-cel|b-lymfocyt|b cel","option_only":true},"t-cellen":{"title":"T-cellen","short":"T-cellen zijn lymfocyten die in de thymus rijpen en antigeen herkennen dat via MHC wordt gepresenteerd; CD4-cellen helpen, CD8-cellen doden geïnfecteerde cellen.","definition":"<p><strong>T-cellen</strong> ontstaan in het beenmerg en rijpen in de <em>thymus</em>, waar positieve en negatieve selectie plaatsvindt. Hun T-celreceptor herkent alleen peptiden die door MHC-moleculen worden gepresenteerd.</p><p><em>CD4⁺ T-helpercellen</em> herkennen MHC-II en sturen de afweer met cytokines (Th1, Th2, Th17, Tfh); <em>CD8⁺ cytotoxische T-cellen</em> herkennen MHC-I en doden geïnfecteerde of tumorcellen; regulatoire T-cellen remmen de afweer. Ze vormen de cellulaire adaptieve immuniteit.</p>","image_url":"","wiki_title":"T cell","match":"t-cellen|t cellen|t-lymfocyten|t-cel|t-lymfocyt|t cel","option_only":true},"neutrofielen":{"title":"Neutrofiele granulocyten","short":"Neutrofielen zijn de meest voorkomende witte bloedcellen; ze zijn als eerste ter plekke bij een acute bacteriële ontsteking en fagocyteren bacteriën.","definition":"<p><strong>Neutrofiele granulocyten</strong> hebben een gesegmenteerde kern en korrels met afbrekende enzymen. Ze leven maar kort (uren tot dagen) en worden in grote aantallen in het beenmerg gemaakt.</p><p>Bij een acute ontsteking verlaten ze als eerste de bloedbaan (marginatie, rollen, adhesie, diapedese) en volgen ze chemotactische signalen (o.a. IL-8, C5a). Ze fagocyteren en doden bacteriën met een oxidatieve burst en enzymen en kunnen ‘NETs’ uitwerpen. Pus bestaat grotendeels uit dode neutrofielen.</p>","image_url":"","wiki_title":"Neutrophil","match":"neutrofielen|neutrofiele granulocyten|neutrofiel|neutrofiele granulocyt","option_only":true},"dendritische cellen":{"title":"Dendritische cellen","short":"Dendritische cellen zijn de belangrijkste antigeenpresenterende cellen: ze nemen antigeen op in weefsels en activeren naïeve T-cellen in de lymfeklier.","definition":"<p><strong>Dendritische cellen</strong> zitten in weefsels die in contact staan met de buitenwereld, zoals huid (Langerhanscellen) en slijmvliezen. Met hun uitlopers nemen ze antigenen op.</p><p>Na activatie (bijv. via Toll-like receptoren) migreren ze naar de lymfeklier, waar ze antigeenfragmenten op MHC-I en MHC-II presenteren, met costimulerende moleculen. Ze zijn de enige cellen die effectief <em>naïeve T-cellen</em> activeren en vormen zo de brug tussen aangeboren en verworven afweer.</p>","image_url":"","wiki_title":"Dendritic cell","match":"dendritische cellen|dendritische cel|langerhanscellen","option_only":true},"crp":{"title":"CRP (C-reactief proteïne)","short":"CRP is een acutefase-eiwit uit de lever dat binnen een dag sterk stijgt bij ontsteking of infectie, vooral bacterieel.","definition":"<p><strong>C-reactief proteïne</strong> wordt door de lever gemaakt onder invloed van vooral <em>IL-6</em>. Het bindt aan fosfocholine op micro-organismen en beschadigde cellen en activeert zo complement (opsonisatie).</p><p>Het CRP stijgt binnen 6–12 uur na het begin van een ontsteking en daalt snel bij herstel, waardoor het een nuttige maat is voor ontstekingsactiviteit. Bacteriële infecties geven vaak een hoger CRP dan virale, maar de waarde is niet specifiek.</p>","image_url":"","wiki_title":"C-reactive protein","match":"crp|c-reactief proteïne|c-reactief proteine","option_only":true},"bof":{"title":"Bof","short":"Bof is een virale infectie (paramyxovirus) met pijnlijke zwelling van de oorspeekselklieren; complicaties zijn orchitis, meningitis en doofheid.","definition":"<p><strong>Bof</strong> (parotitis epidemica) wordt veroorzaakt door het bofvirus, een omhuld RNA-virus. Het wordt via druppels overgedragen.</p><p>Het typische beeld is een pijnlijke zwelling van één of beide <em>glandulae parotideae</em>, met koorts en malaise. Complicaties zijn orchitis (vooral na de puberteit), oöforitis, pancreatitis, meningitis en eenzijdige doofheid. Er wordt tegen gevaccineerd met het BMR-vaccin.</p>","image_url":"","wiki_title":"Mumps","match":"bof|parotitis epidemica|bofvirus","option_only":true},"nier":{"title":"Nier","short":"De nieren filteren het bloed en regelen water-, zout- en zuur-base-evenwicht en bloeddruk; ook maken ze hormonen (renine, EPO, actief vitamine D).","definition":"<p>De <strong>nieren</strong> liggen retroperitoneaal aan weerszijden van de wervelkolom. De functionele eenheid is het <em>nefron</em>: glomerulus, proximale tubulus, lis van Henle, distale tubulus en verzamelbuis. Samen filteren de nieren ongeveer 180 liter per dag, waarvan meer dan 99% wordt teruggeresorbeerd.</p><p>Ze scheiden afvalstoffen (ureum, creatinine) en geneesmiddelen uit, regelen het volume en de samenstelling van de lichaamsvloeistoffen en de pH, en maken <em>renine</em> (bloeddruk), <em>erytropoëtine</em> (aanmaak van rode bloedcellen) en <em>calcitriol</em> (actief vitamine D).</p>","image_url":"","wiki_title":"Kidney","match":"nier|nieren|ren","option_only":true},"epileptische aanval":{"title":"Epileptische aanval","short":"Een epileptische aanval is een kortdurende verandering in gedrag, bewustzijn of waarneming door een abnormale, overmatige ontlading van neuronen.","definition":"<p>Een <strong>epileptische aanval</strong> kan focaal beginnen (in één hersengebied, met of zonder bewustzijnsdaling) of gegeneraliseerd zijn (bijv. tonisch-klonisch of absence). Een aanval kan uitgelokt worden (bijv. door hypoglykemie, alcoholonthouding of koorts bij jonge kinderen) of passen bij epilepsie. Een aanval die langer dan 5 minuten duurt wordt behandeld als status epilepticus.</p>","image_url":"","wiki_title":"Epileptic seizure","match":"epileptische aanval|insult|epileptisch insult","option_only":true},"streptococcus pyogenes":{"title":"Streptococcus pyogenes (groep A-streptokok)","short":"Groep A-streptokok: grampositieve, bètahemolytische kok in ketens die o.a. keelontsteking, impetigo, erysipelas en roodvonk veroorzaakt.","definition":"<p><strong><em>Streptococcus pyogenes</em></strong> koloniseert keel en huid. Het M-eiwit beschermt tegen fagocytose; pyrogene exotoxinen veroorzaken roodvonk en het toxischeshocksyndroom. Invasieve infecties zijn o.a. cellulitis en necrotiserende fasciitis. Na een infectie kunnen immunologische complicaties optreden: acuut reuma en poststreptokokken-glomerulonefritis. Penicilline is eerste keus.</p>","image_url":"","wiki_title":"Streptococcus pyogenes","match":"streptococcus pyogenes|s. pyogenes|groep a-streptokok|groep a streptokok|groep-a-streptokokken","option_only":true},"enterokokken":{"title":"Enterokokken","short":"Enterokokken zijn grampositieve kokken uit de darmflora die van nature resistent zijn tegen cefalosporines.","definition":"<p><strong>Enterokokken</strong> (vooral <em>E. faecalis</em> en <em>E. faecium</em>) zijn grampositieve kokken in paren of korte ketens. Ze veroorzaken urineweginfecties, wondinfecties, intra-abdominale infecties en endocarditis, vaak in het ziekenhuis. Ze zijn intrinsiek ongevoelig voor cefalosporines; amoxicilline werkt meestal tegen <em>E. faecalis</em>. Vancomycineresistente stammen (VRE) zijn een ziekenhuishygiëneprobleem.</p>","image_url":"","wiki_title":"Enterococcus","match":"enterokokken|enterococcus|enterococcus faecalis|enterococcus faecium","option_only":true},"neisseria meningitidis":{"title":"Neisseria meningitidis (meningokok)","short":"De meningokok is een gramnegatieve diplokok die meningitis en een snel fataal verlopende sepsis met petechiën kan veroorzaken.","definition":"<p><strong><em>Neisseria meningitidis</em></strong> koloniseert de nasofarynx en wordt via druppels overgedragen. Het kapsel en endotoxine (LOS) maken hem zeer virulent. Een invasieve infectie geeft meningitis en/of een fulminante sepsis met petechiën en purpura (soms met bijnierbloedingen). Er wordt gevaccineerd tegen serogroepen ACWY en B; contacten krijgen profylaxe.</p>","image_url":"","wiki_title":"Neisseria meningitidis","match":"neisseria meningitidis|meningokok|meningokokken","option_only":true},"listeria monocytogenes":{"title":"Listeria monocytogenes","short":"Listeria is een grampositieve staaf die via voedsel wordt opgelopen en vooral bij zwangeren, pasgeborenen, ouderen en afweergestoorden infecties geeft.","definition":"<p><strong><em>Listeria monocytogenes</em></strong> kan groeien bij koelkasttemperatuur en komt voor in rauwmelkse kaas, paté en gerookte vis. Hij groeit intracellulair en verspreidt zich van cel tot cel via actinestaarten. Infecties: meningitis en sepsis, en bij zwangeren risico op miskraam of neonatale infectie. Cefalosporines werken niet; amoxicilline wel.</p>","image_url":"","wiki_title":"Listeria monocytogenes","match":"listeria monocytogenes|listeria","option_only":true},"legionella pneumophila":{"title":"Legionella pneumophila","short":"Legionella is een gramnegatieve staaf uit warm water die een ernstige (atypische) pneumonie kan veroorzaken: de veteranenziekte.","definition":"<p><strong><em>Legionella pneumophila</em></strong> groeit in warmwatersystemen, koeltorens en bubbelbaden en wordt via aerosolen ingeademd; er is geen overdracht van mens op mens. Risicofactoren zijn hogere leeftijd, roken en immuunsuppressie. Naast pneumonie kunnen diarree, verwardheid en hyponatriëmie optreden. Diagnose met de urine-antigeentest; bètalactamantibiotica werken niet, macroliden en chinolonen wel.</p>","image_url":"","wiki_title":"Legionella pneumophila","match":"legionella pneumophila|legionella|veteranenziekte","option_only":true},"mycoplasma pneumoniae":{"title":"Mycoplasma pneumoniae","short":"Mycoplasma pneumoniae is een bacterie zonder celwand die bij jongeren een ‘atypische’ pneumonie veroorzaakt.","definition":"<p><strong><em>Mycoplasma pneumoniae</em></strong> heeft geen peptidoglycaanwand en is daardoor ongevoelig voor bètalactamantibiotica en niet zichtbaar met een gramkleuring. Het veroorzaakt vooral bij schoolkinderen en jongvolwassenen een geleidelijk beginnende luchtweginfectie met droge hoest. Er kunnen koude agglutininen (hemolyse) en extrapulmonale verschijnselen optreden. Behandeling met macroliden of doxycycline.</p>","image_url":"","wiki_title":"Mycoplasma pneumoniae","match":"mycoplasma pneumoniae|mycoplasma","option_only":true},"chlamydia pneumoniae":{"title":"Chlamydia pneumoniae","short":"Chlamydia pneumoniae is een obligaat intracellulaire bacterie die milde luchtweginfecties en atypische pneumonie veroorzaakt.","definition":"<p><strong><em>Chlamydia pneumoniae</em></strong> wordt via druppels overgedragen en veroorzaakt faryngitis, sinusitis, bronchitis en een meestal milde atypische pneumonie. Omdat de bacterie intracellulair leeft, werken bètalactamantibiotica niet; doxycycline of macroliden wel.</p>","image_url":"","wiki_title":"Chlamydia pneumoniae","match":"chlamydia pneumoniae|chlamydophila pneumoniae","option_only":true},"salmonella enteritidis":{"title":"Salmonella enteritidis","short":"Salmonella enteritidis is een gramnegatieve staaf die via besmette eieren en kip een voedselinfectie met diarree en koorts veroorzaakt.","definition":"<p>Niet-tyfeuze <strong>salmonellae</strong> zoals <em>S. enteritidis</em> komen via onvoldoende verhitte eieren, kip of besmet voedsel binnen. Na 6–72 uur ontstaan koorts, buikkrampen en diarree, meestal zelflimiterend. Bij zuigelingen, ouderen, afweergestoorden en mensen met vaatprothesen kan bacteriëmie optreden. Antibiotica zijn meestal niet nodig.</p>","image_url":"","wiki_title":"Salmonella enterica","match":"salmonella enteritidis|salmonella|salmonellose","option_only":true},"campylobacter jejuni":{"title":"Campylobacter jejuni","short":"Campylobacter jejuni is een gekromde gramnegatieve staaf en een belangrijke oorzaak van bacteriële gastro-enteritis, vaak via kip.","definition":"<p><strong><em>Campylobacter jejuni</em></strong> wordt opgelopen via onvoldoende verhit gevogelte, rauwe melk of besmet water. Het geeft koorts, buikkrampen en (soms bloederige) diarree. Een bekende late complicatie is het syndroom van Guillain-Barré, door kruisreactie van antistoffen met gangliosiden in zenuwen; ook reactieve artritis komt voor.</p>","image_url":"","wiki_title":"Campylobacter jejuni","match":"campylobacter jejuni|campylobacter","option_only":true},"yersinia enterocolitica":{"title":"Yersinia enterocolitica","short":"Yersinia enterocolitica is een gramnegatieve staaf die via varkensvlees een enterocolitis kan veroorzaken die appendicitis kan nabootsen.","definition":"<p><strong><em>Yersinia enterocolitica</em></strong> groeit ook bij lage temperatuur. Infectie geeft koorts, diarree en buikpijn; door ontsteking van het terminale ileum en de mesenteriale lymfeklieren kan het beeld lijken op appendicitis (pseudo-appendicitis). Na infectie kunnen reactieve artritis en erythema nodosum ontstaan, vooral bij HLA-B27-dragers. IJzerstapeling (hemochromatose) is een risicofactor voor ernstige infectie.</p>","image_url":"","wiki_title":"Yersinia enterocolitica","match":"yersinia enterocolitica|yersinia","option_only":true},"enterotoxigene escherichia coli":{"title":"Enterotoxigene E. coli (ETEC)","short":"ETEC is een E. coli-variant die met toxines waterige diarree veroorzaakt; de belangrijkste oorzaak van reizigersdiarree.","definition":"<p><strong>ETEC</strong> hecht zich aan het dunnedarmepitheel en maakt een hitte-labiel toxine (verwant aan choleratoxine, verhoogt cAMP) en/of een hitte-stabiel toxine (verhoogt cGMP). Daardoor worden chloride en water de darm in gepompt: secretoire, waterige diarree zonder bloed of koorts. Besmetting via voedsel en water; behandeling vooral met vocht en zouten.</p>","image_url":"","wiki_title":"Enterotoxigenic Escherichia coli","match":"enterotoxigene escherichia coli|etec|enterotoxigene e. coli","option_only":true},"reizigersdiarree":{"title":"Reizigersdiarree","short":"Reizigersdiarree is diarree die optreedt tijdens of kort na een reis, meestal door besmet voedsel of water.","definition":"<p><strong>Reizigersdiarree</strong> wordt meestal veroorzaakt door bacteriën, met enterotoxigene <em>E. coli</em> als belangrijkste verwekker; daarnaast <em>Campylobacter</em>, <em>Shigella</em>, <em>Salmonella</em>, virussen en parasieten zoals <em>Giardia</em>. Het is meestal zelflimiterend binnen enkele dagen. De basis van de behandeling is het aanvullen van vocht en zouten (ORS).</p>","image_url":"","wiki_title":"Travelers' diarrhea","match":"reizigersdiarree","option_only":true},"clostridium difficile":{"title":"Clostridioides difficile","short":"C. difficile is een sporenvormende anaerobe staaf die na antibioticagebruik een toxine-gemedieerde colitis kan veroorzaken.","definition":"<p><strong><em>Clostridioides difficile</em></strong> kan het colon koloniseren als de normale flora door antibiotica is verstoord. Toxine A en B beschadigen het colonepitheel, met waterige diarree, buikpijn en in ernstige gevallen pseudomembraneuze colitis of toxisch megacolon. De sporen zijn resistent tegen alcohol, dus handen wassen met zeep is nodig. Behandeling: vancomycine of fidaxomicine oraal.</p>","image_url":"","wiki_title":"Clostridioides difficile infection","match":"clostridium difficile|clostridioides difficile|c. difficile","option_only":true},"bacteroides fragilis":{"title":"Bacteroides fragilis","short":"Bacteroides fragilis is een gramnegatieve anaerobe staaf uit de darmflora en een belangrijke verwekker van buikabcessen.","definition":"<p><strong><em>Bacteroides fragilis</em></strong> is een van de talrijkste anaeroben in het colon. Bij perforatie of darmchirurgie kan hij in de buikholte terechtkomen en (met andere bacteriën) abcessen en peritonitis veroorzaken; het kapsel bevordert abcesvorming. Hij maakt vaak bètalactamase; metronidazol, amoxicilline-clavulaanzuur en carbapenems werken wel.</p>","image_url":"","wiki_title":"Bacteroides fragilis","match":"bacteroides fragilis|bacteroides","option_only":true},"lactobacillus spp":{"title":"Lactobacillus","short":"Lactobacillen zijn grampositieve staafjes die melkzuur maken; ze domineren de gezonde vaginale flora en komen voor in darm en gefermenteerd voedsel.","definition":"<p><strong>Lactobacillen</strong> fermenteren suikers tot melkzuur. In de vagina houden ze (onder invloed van oestrogeen en glycogeen) de pH laag, wat beschermt tegen ziekteverwekkers; afname ervan leidt tot bacteriële vaginose. Ze worden ook gebruikt in yoghurt en probiotica en zijn zelden ziekteverwekkend.</p>","image_url":"","wiki_title":"Lactobacillus","match":"lactobacillus spp|lactobacillus|lactobacillen|melkzuurbacteriën","option_only":true},"treponema pallidum":{"title":"Treponema pallidum","short":"Treponema pallidum is de spirocheet die syfilis veroorzaakt.","definition":"<p><strong><em>Treponema pallidum</em></strong> is een dunne, spiraalvormige bacterie die niet te kweken is en niet zichtbaar is met een gramkleuring. Ze wordt seksueel en via de placenta overgedragen. Diagnostiek gebeurt meestal serologisch (treponemale en non-treponemale tests) of met PCR uit een ulcus. Penicilline blijft het middel van keus.</p>","image_url":"","wiki_title":"Treponema pallidum","match":"treponema pallidum|treponema","option_only":true},"leptospira spp":{"title":"Leptospira (ziekte van Weil)","short":"Leptospira zijn spirocheten die via urine van ratten en vee in water terechtkomen en leptospirose veroorzaken.","definition":"<p><strong>Leptospirose</strong> wordt opgelopen via contact met besmet oppervlaktewater of dierenurine, via huidwondjes of slijmvliezen. Het begint met koorts, hoofdpijn en spierpijn (vooral kuiten) en conjunctivale roodheid. Een ernstige vorm (ziekte van Weil) geeft icterus, nierfalen en bloedingen. Behandeling met doxycycline of penicilline.</p>","image_url":"","wiki_title":"Leptospirosis","match":"leptospira spp|leptospira|leptospirose|ziekte van weil","option_only":true},"cryptococcus neoformans":{"title":"Cryptococcus neoformans","short":"Cryptococcus neoformans is een gist met een dik kapsel die vooral bij afweergestoorden (hiv) meningitis veroorzaakt.","definition":"<p><strong><em>Cryptococcus neoformans</em></strong> komt voor in duivenpoep en grond en wordt ingeademd. Bij patiënten met een sterk verminderde cellulaire afweer verspreidt hij zich naar het CZS en veroorzaakt een subacute meningitis met hoofdpijn en verhoogde liquordruk. Diagnose met antigeentest in serum of liquor (vroeger Oost-Indische-inktkleuring); behandeling met amfotericine B en flucytosine.</p>","image_url":"","wiki_title":"Cryptococcus neoformans","match":"cryptococcus neoformans|cryptococcus|cryptococcose","option_only":true},"aspergillus fumigatus":{"title":"Aspergillus fumigatus","short":"Aspergillus fumigatus is een schimmel waarvan de sporen overal in de lucht zijn; bij neutropenie kan hij een invasieve longinfectie geven.","definition":"<p><strong><em>Aspergillus</em></strong> kan verschillende ziektebeelden geven: allergische bronchopulmonale aspergillose (bij astma en CF), een aspergilloom (schimmelbal in een bestaande holte) en invasieve aspergillose bij ernstig afweergestoorde patiënten, met invasie van bloedvaten. Diagnostiek met CT, galactomannan en kweek; behandeling met voriconazol.</p>","image_url":"","wiki_title":"Aspergillus fumigatus","match":"aspergillus fumigatus|aspergillus|aspergillose","option_only":true},"epstein-barrvirus":{"title":"Epstein-Barrvirus (EBV)","short":"EBV is een herpesvirus dat B-cellen infecteert; het veroorzaakt de ziekte van Pfeiffer en is geassocieerd met enkele kankers.","definition":"<p>Het <strong>Epstein-Barrvirus</strong> wordt via speeksel overgedragen. Op jonge leeftijd verloopt infectie vaak ongemerkt; bij adolescenten geeft het vaak mononucleosis infectiosa. Het virus blijft levenslang latent in B-cellen. EBV is geassocieerd met o.a. het Burkittlymfoom, het nasofarynxcarcinoom, sommige Hodgkinlymfomen en posttransplantatie-lymfoproliferatieve ziekte.</p>","image_url":"","wiki_title":"Epstein–Barr virus","match":"epstein-barrvirus|epstein-barrvirus (ebv)|ebv|epstein-barr virus","option_only":true},"varicella-zostervirus":{"title":"Varicella-zostervirus (VZV)","short":"Het varicella-zostervirus veroorzaakt waterpokken en blijft daarna latent in sensibele ganglia, van waaruit het als gordelroos kan reactiveren.","definition":"<p>Het <strong>varicella-zostervirus</strong> (HHV-3) is zeer besmettelijk via aerosolen en blaasjesvocht. De primaire infectie, <em>waterpokken</em>, geeft koorts en jeukende blaasjes in verschillende stadia tegelijk. Het virus nestelt zich in sensibele ganglia; reactivatie geeft <em>herpes zoster</em>. Gevaarlijk is infectie bij zwangeren, pasgeborenen en afweergestoorden (pneumonie, encefalitis).</p>","image_url":"","wiki_title":"Varicella zoster virus","match":"varicella-zostervirus|varicella zoster|varicella zostervirus (vzv)|vzv|waterpokken|varicella","option_only":true},"herpes simplexvirus":{"title":"Herpes simplexvirus (HSV)","short":"Het herpes simplexvirus veroorzaakt blaasjes op huid en slijmvliezen en blijft daarna latent in sensibele ganglia.","definition":"<p>Er zijn twee typen: <strong>HSV-1</strong> (vooral oraal, koortslip, gingivostomatitis) en <strong>HSV-2</strong> (vooral genitaal), al overlappen ze. Na de primaire infectie blijft het virus latent in sensibele ganglia en kan het reactiveren. Ernstige vormen zijn herpesencefalitis, keratitis, eczema herpeticum en neonatale herpes. Behandeling met (val)aciclovir.</p>","image_url":"","wiki_title":"Herpes simplex virus","match":"herpes simplexvirus|herpes simplex|hsv|hsv-1|hsv-2","option_only":true},"herpes genitalis":{"title":"Herpes genitalis","short":"Herpes genitalis is een seksueel overdraagbare infectie met HSV-2 of HSV-1, met pijnlijke blaasjes en zweertjes in het genitale gebied.","definition":"<p>Bij <strong>herpes genitalis</strong> ontstaan na besmetting pijnlijke groepjes blaasjes die openbreken tot oppervlakkige ulcera, vaak met koorts, pijn bij het plassen en vergrote lieslymfeklieren. Het virus blijft latent in de sacrale ganglia en kan recidiveren. Een primaire infectie rond de bevalling geeft een groot risico op neonatale herpes.</p>","image_url":"","wiki_title":"Genital herpes","match":"herpes genitalis|genitale herpes","option_only":true},"humaan papillomavirus (hpv)":{"title":"Humaan papillomavirus (HPV)","short":"HPV is een DNA-virus dat wratten veroorzaakt; hoog-risicotypes (o.a. 16 en 18) veroorzaken baarmoederhalskanker en andere kankers.","definition":"<p>Het <strong>humaan papillomavirus</strong> infecteert basale cellen van huid en slijmvlies. Laag-risicotypes (6, 11) geven wratten en condylomata acuminata. Hoog-risicotypes maken de eiwitten E6 en E7, die p53 en Rb uitschakelen; persisterende infectie kan leiden tot cervixcarcinoom en kankers van anus, vulva, penis en orofarynx. Er is een vaccin en een bevolkingsonderzoek met hrHPV-test.</p>","image_url":"","wiki_title":"Human papillomavirus infection","match":"humaan papillomavirus (hpv)|hpv|humaan papillomavirus","option_only":true},"hiv":{"title":"Hiv (humaan immunodeficiëntievirus)","short":"Hiv is een retrovirus dat CD4-T-helpercellen infecteert; zonder behandeling ontstaat aids.","definition":"<p><strong>Hiv</strong> bindt met gp120 aan CD4 en een co-receptor (CCR5 of CXCR4), schrijft zijn RNA via reverse transcriptase om naar DNA en bouwt dat in het genoom in. Het aantal CD4-cellen daalt geleidelijk; onder ±200/µl ontstaan opportunistische infecties en tumoren (aids). Overdracht via seks, bloed en van moeder op kind. Combinatietherapie (cART) onderdrukt het virus volledig.</p>","image_url":"","wiki_title":"HIV","match":"hiv|humaan immunodeficiëntievirus|aids","option_only":true},"rotavirus":{"title":"Rotavirus","short":"Rotavirus is een dubbelstrengs RNA-virus dat bij jonge kinderen een ernstige gastro-enteritis met braken en waterige diarree veroorzaakt.","definition":"<p><strong>Rotavirus</strong> wordt fecaal-oraal overgedragen en beschadigt de villi van de dunne darm. Vooral kinderen onder de 2 jaar krijgen koorts, braken en waterige diarree, met risico op uitdroging. Er bestaat een oraal levend vaccin, inmiddels opgenomen in het Rijksvaccinatieprogramma.</p>","image_url":"","wiki_title":"Rotavirus","match":"rotavirus","option_only":true},"rhinovirus":{"title":"Rhinovirus","short":"Rhinovirussen zijn de belangrijkste verwekkers van de gewone verkoudheid.","definition":"<p><strong>Rhinovirussen</strong> zijn kleine, niet-omhulde RNA-virussen (picornavirussen) met meer dan 100 serotypes, waardoor je er steeds opnieuw verkouden van kunt worden. Ze vermenigvuldigen zich het best bij de iets lagere temperatuur in de neus. Ze kunnen ook astma- en COPD-exacerbaties uitlokken.</p>","image_url":"","wiki_title":"Rhinovirus","match":"rhinovirus|rhinovirussen","option_only":true},"virale meningitis":{"title":"Virale meningitis","short":"Virale meningitis is een ontsteking van de hersenvliezen door een virus; meestal milder dan bacteriële meningitis.","definition":"<p><strong>Virale meningitis</strong> wordt vaak veroorzaakt door enterovirussen, daarnaast o.a. door HSV-2 en VZV. Er zijn hoofdpijn, koorts, nekstijfheid en lichtschuwheid, meestal zonder verlaagd bewustzijn. Liquor toont een lymfocytaire pleiocytose met normaal glucose en licht verhoogd eiwit. Het beloop is meestal goedaardig.</p>","image_url":"","wiki_title":"Viral meningitis","match":"virale meningitis|aseptische meningitis","option_only":true},"tuberculeuze meningitis":{"title":"Tuberculeuze meningitis","short":"Tuberculeuze meningitis is een subacuut verlopende hersenvliesontsteking door Mycobacterium tuberculosis.","definition":"<p>Bij <strong>tuberculeuze meningitis</strong> ontstaan in dagen tot weken hoofdpijn, koorts, gedragsverandering en uitval van hersenzenuwen, vooral door ontsteking aan de schedelbasis. De liquor toont lymfocyten, een sterk verhoogd eiwit en een verlaagd glucose. Complicaties zijn hydrocephalus en infarcten. Behandeling met tuberculostatica en dexamethason.</p>","image_url":"","wiki_title":"Tuberculous meningitis","match":"tuberculeuze meningitis|tbc-meningitis","option_only":true},"neuroborreliose":{"title":"Neuroborreliose","short":"Neuroborreliose is een uiting van de ziekte van Lyme in het zenuwstelsel, met o.a. radiculitis, facialisparese en meningitis.","definition":"<p>Bij <strong>neuroborreliose</strong> verspreidt <em>Borrelia burgdorferi</em> zich naar het zenuwstelsel, weken tot maanden na een tekenbeet. Typisch zijn hevige, ’s nachts verergerende radiculaire pijn (meningoradiculitis, syndroom van Bannwarth), een (soms dubbelzijdige) perifere facialisparese en lymfocytaire meningitis. Diagnose via liquoronderzoek; behandeling met doxycycline of ceftriaxon.</p>","image_url":"","wiki_title":"Lyme neuroborreliosis","match":"neuroborreliose|lyme-neuroborreliose","option_only":true},"toxoplasmose":{"title":"Toxoplasmose","short":"Toxoplasmose is een infectie met de parasiet Toxoplasma gondii, opgelopen via kattenpoep of onvoldoende verhit vlees.","definition":"<p><strong><em>Toxoplasma gondii</em></strong> heeft de kat als eindgastheer. Bij gezonde mensen verloopt infectie meestal ongemerkt of als een mononucleose-achtig beeld. Bij een eerste infectie in de zwangerschap kan de parasiet de foetus infecteren (chorioretinitis, hydrocephalus, intracraniële verkalkingen). Bij afweergestoorden kan reactivatie toxoplasma-encefalitis geven.</p>","image_url":"","wiki_title":"Toxoplasmosis","match":"toxoplasmose|toxoplasma gondii|toxoplasma","option_only":true},"giardiasis":{"title":"Giardiasis","short":"Giardiasis is een darminfectie met de protozo Giardia lamblia, met langdurige diarree, opgeblazen gevoel en vetrijke ontlasting.","definition":"<p><strong><em>Giardia lamblia</em></strong> wordt via cysten in besmet water of voedsel opgelopen. De trofozoïeten hechten aan het dunnedarmepitheel zonder het te binnendringen. Klachten: waterige, vettige, stinkende ontlasting, buikkrampen, winderigheid en gewichtsverlies, soms wekenlang. Diagnose met PCR of microscopie van ontlasting; behandeling met metronidazol of tinidazol.</p>","image_url":"","wiki_title":"Giardiasis","match":"giardiasis|giardia lamblia|giardia","option_only":true},"strongyloidiasis":{"title":"Strongyloidiasis","short":"Strongyloidiasis is een infectie met de draadworm Strongyloides stercoralis, die zich in de mens kan blijven vermenigvuldigen.","definition":"<p>Larven van <strong><em>Strongyloides stercoralis</em></strong> dringen via de huid binnen (blootsvoets lopen in de tropen), reizen via de longen naar de darm en kunnen de mens opnieuw infecteren (auto-infectie), waardoor infecties decennia kunnen blijven bestaan. Vaak zijn er weinig klachten en eosinofilie. Bij immuunsuppressie (vooral corticosteroïden) kan een levensbedreigende hyperinfectie ontstaan. Behandeling met ivermectine.</p>","image_url":"","wiki_title":"Strongyloidiasis","match":"strongyloidiasis|strongyloides stercoralis|strongyloides","option_only":true},"leishmaniasis":{"title":"Leishmaniasis","short":"Leishmaniasis is een parasitaire infectie door Leishmania, overgebracht door zandvliegen, met huidzweren of een ernstige viscerale vorm.","definition":"<p>Bij <strong>cutane leishmaniasis</strong> ontstaat op de plek van de beet een langzaam groeiende, pijnloze zweer. Bij <strong>viscerale leishmaniasis</strong> (kala-azar) infecteert de parasiet macrofagen in milt, lever en beenmerg, met koorts, sterke splenomegalie, pancytopenie en gewichtsverlies; onbehandeld is dit dodelijk. Komt voor rond de Middellandse Zee, Afrika, Azië en Zuid-Amerika.</p>","image_url":"","wiki_title":"Leishmaniasis","match":"leishmaniasis|leishmania","option_only":true},"dengue":{"title":"Dengue (knokkelkoorts)","short":"Dengue is een door Aedes-muggen overgebrachte virusinfectie met hoge koorts, hevige spier- en gewrichtspijn en huiduitslag.","definition":"<p><strong>Dengue</strong> wordt veroorzaakt door een flavivirus met vier serotypes. Na een paar dagen incubatie volgen hoge koorts, hoofdpijn achter de ogen, spier- en gewrichtspijn en een rash. Een tweede infectie met een ander serotype geeft een groter risico op ernstige dengue met plasmalekkage, bloedingen en shock (door antistof-afhankelijke versterking). Behandeling is ondersteunend; NSAID's worden vermeden.</p>","image_url":"","wiki_title":"Dengue fever","match":"dengue|knokkelkoorts|denguevirus","option_only":true},"ebola":{"title":"Ebola","short":"Ebola is een zeer ernstige virale hemorragische koorts, overgedragen via lichaamsvloeistoffen van besmette mensen of dieren.","definition":"<p>Het <strong>ebolavirus</strong> is een filovirus. Na 2–21 dagen ontstaan koorts, zwakte, spierpijn, braken en diarree; in een deel van de gevallen volgen bloedingen en multi-orgaanfalen. De sterfte is hoog. Overdracht gebeurt via direct contact met bloed en lichaamsvloeistoffen, ook van overledenen; strikte isolatie is nodig. Er is inmiddels een vaccin tegen het Zaïre-type.</p>","image_url":"","wiki_title":"Ebola","match":"ebola|ebolavirus|ebolakoorts","option_only":true},"rabies":{"title":"Rabiës (hondsdolheid)","short":"Rabiës is een vrijwel altijd dodelijke virale encefalitis, overgedragen via beten of krabben van besmette zoogdieren.","definition":"<p>Het <strong>rabiësvirus</strong> reist via perifere zenuwen naar het centrale zenuwstelsel; de incubatietijd varieert van weken tot maanden. Zodra klachten optreden (agitatie, hydrofobie, verlammingen) is de ziekte vrijwel altijd fataal. Na een risicovolle beet is direct wondverzorging en postexpositieprofylaxe (vaccinatie, zo nodig met immunoglobuline) nodig.</p>","image_url":"","wiki_title":"Rabies","match":"rabies|rabiës|hondsdolheid","option_only":true},"roodvonk":{"title":"Roodvonk (scarlatina)","short":"Roodvonk is een infectie met groep A-streptokokken die een toxine maken, met keelpijn, koorts, een fijnvlekkige rash en een frambozentong.","definition":"<p>Bij <strong>roodvonk</strong> veroorzaken pyrogene exotoxinen van <em>Streptococcus pyogenes</em> een ruwe, fijnpapuleuze rode huiduitslag (schuurpapiergevoel), vooral in de plooien, met bleke huid rond de mond en een aardbeien- of frambozentong. Daarna schilfert de huid, vooral aan handen en voeten. Het komt vooral voor bij kinderen van 3–10 jaar; behandeling met penicilline.</p>","image_url":"","wiki_title":"Scarlet fever","match":"roodvonk|scarlatina","option_only":true},"pediculosis":{"title":"Pediculosis (luizen)","short":"Pediculosis is besmetting met luizen, zoals hoofdluis, met jeuk en neten aan de haren.","definition":"<p>Bij <strong>pediculosis capitis</strong> leven hoofdluizen op de hoofdhuid en zuigen ze bloed; de eitjes (neten) worden vlak bij de hoofdhuid aan de haren vastgeplakt. De jeuk komt door een overgevoeligheidsreactie op het speeksel. Overdracht gaat via direct hoofd-hoofdcontact. Behandeling: kammen met een netenkam, eventueel met dimeticon. Kleerluizen kunnen ziekten zoals vlektyfus overbrengen.</p>","image_url":"","wiki_title":"Head louse","match":"pediculosis|hoofdluis|luizen|pediculosis capitis","option_only":true},"scabiës":{"title":"Scabiës (schurft)","short":"Scabiës is een besmettelijke huidaandoening door de mijt Sarcoptes scabiei, met hevige nachtelijke jeuk en gangetjes in de huid.","definition":"<p>Bij <strong>scabiës</strong> graaft de vrouwtjesmijt gangetjes in de hoornlaag, vooral tussen de vingers, aan de polsen, oksels, genitaliën en rond de navel. De jeuk (vooral ’s nachts en bij warmte) ontstaat door een allergische reactie en begint pas na enkele weken. Overdracht via langdurig huidcontact. Behandeling met permetrinecrème of ivermectine, voor alle huisgenoten tegelijk.</p>","image_url":"","wiki_title":"Scabies","match":"scabiës|scabies|schurft|sarcoptes scabiei","option_only":true},"lipopolysaccharide":{"title":"Lipopolysaccharide (LPS, endotoxine)","short":"Lipopolysaccharide is een bestanddeel van de buitenmembraan van gramnegatieve bacteriën dat als endotoxine een sterke ontstekingsreactie uitlokt.","definition":"<p><strong>LPS</strong> bestaat uit lipide A (het toxische deel, verankerd in de buitenmembraan), een kernpolysacharide en een O-antigeen. Het wordt herkend door TLR4 op macrofagen, die daarop massaal TNF, IL-1 en IL-6 afgeven. In grote hoeveelheden kan dat leiden tot koorts, verwijde vaten, stollingsactivatie (DIS) en septische shock.</p>","image_url":"","wiki_title":"Lipopolysaccharide","match":"lipopolysaccharide|lps|endotoxine","option_only":true},"peptidoglycaanlaag":{"title":"Peptidoglycaan","short":"Peptidoglycaan is het netwerk van suikers en peptiden dat de bacteriële celwand stevigheid geeft.","definition":"<p><strong>Peptidoglycaan</strong> bestaat uit ketens van afwisselend N-acetylglucosamine en N-acetylmuraminezuur, onderling verbonden via korte peptidebruggen. Grampositieve bacteriën hebben een dikke laag (houdt het kristalviolet vast), gramnegatieve een dunne laag tussen twee membranen. Bètalactamantibiotica remmen de verknoping, vancomycine de opbouw en lysozym breekt het af.</p>","image_url":"","wiki_title":"Peptidoglycan","match":"peptidoglycaanlaag|peptidoglycaan|mureïne","option_only":true},"resistentie":{"title":"Antibioticaresistentie","short":"Resistentie betekent dat een micro-organisme ongevoelig is (geworden) voor een middel dat het normaal zou remmen of doden.","definition":"<p><strong>Antibioticaresistentie</strong> kan intrinsiek zijn (bijv. <em>Mycoplasma</em> zonder celwand) of verworven via mutaties of overdracht van resistentiegenen (bijv. via plasmiden). Mechanismen zijn afbraak van het middel (bètalactamasen), verandering van het doelwit (bijv. PBP2a bij MRSA), verminderde opname of actieve uitpomp (effluxpompen). Overmatig antibioticagebruik selecteert resistente stammen.</p>","image_url":"","wiki_title":"Antimicrobial resistance","match":"resistentie|antibioticaresistentie","option_only":true},"antibiotica":{"title":"Antibiotica","short":"Antibiotica zijn middelen die bacteriën doden of hun groei remmen; ze werken niet tegen virussen.","definition":"<p><strong>Antibiotica</strong> grijpen aan op structuren die bacteriën wel en menselijke cellen niet (of anders) hebben: de celwand (bètalactams, vancomycine), het ribosoom (o.a. macroliden, tetracyclines, aminoglycosiden), DNA-synthese (chinolonen, metronidazol) of foliumzuursynthese (trimethoprim, sulfonamiden). Bacteriostatisch betekent groeiremmend, bactericide dodend. Onnodig gebruik bevordert resistentie.</p>","image_url":"","wiki_title":"Antibiotic","match":"antibiotica|antibioticum","option_only":true},"ciprofloxacine":{"title":"Ciprofloxacine","short":"Ciprofloxacine is een fluorochinolon dat het bacteriële DNA-gyrase remt; werkzaam tegen veel gramnegatieve bacteriën.","definition":"<p><strong>Ciprofloxacine</strong> remt DNA-gyrase en topo-isomerase IV, waardoor de bacterie haar DNA niet kan repliceren (bactericide). Het werkt goed tegen gramnegatieve staven, inclusief <em>Pseudomonas</em>, en wordt o.a. gebruikt bij gecompliceerde urineweginfecties en prostatitis. Bijwerkingen: peesruptuur, QT-verlenging, verwardheid en <em>C. difficile</em>-infectie.</p>","image_url":"","wiki_title":"Ciprofloxacin","match":"ciprofloxacine|ciprofloxacin|fluorochinolon","option_only":true},"tobramycine":{"title":"Tobramycine","short":"Tobramycine is een aminoglycoside dat de bacteriële eiwitsynthese remt (30S) en goed werkt tegen Pseudomonas.","definition":"<p><strong>Tobramycine</strong> bindt aan de 30S-subeenheid van het ribosoom, wat tot foutieve eiwitten en celdood leidt (bactericide, concentratieafhankelijk). Het werkt tegen gramnegatieve aerobe bacteriën en wordt o.a. per inhalatie gebruikt bij cystische fibrose. Belangrijke bijwerkingen zijn nefrotoxiciteit en ototoxiciteit; spiegels worden gecontroleerd.</p>","image_url":"","wiki_title":"Tobramycin","match":"tobramycine|aminoglycoside","option_only":true},"metronidazol":{"title":"Metronidazol","short":"Metronidazol is een antibioticum tegen anaerobe bacteriën en bepaalde protozoën.","definition":"<p><strong>Metronidazol</strong> wordt in anaerobe micro-organismen omgezet in reactieve deeltjes die het DNA beschadigen. Het werkt tegen anaerobe bacteriën (o.a. <em>Bacteroides</em>, <em>Clostridioides</em>) en protozoën zoals <em>Giardia</em>, <em>Trichomonas</em> en <em>Entamoeba</em>. Bijwerkingen: metaalsmaak, misselijkheid en een disulfiramachtige reactie met alcohol.</p>","image_url":"","wiki_title":"Metronidazole","match":"metronidazol|flagyl","option_only":true},"amoxicilline/clavulaanzuur":{"title":"Amoxicilline-clavulaanzuur","short":"Amoxicilline-clavulaanzuur combineert een penicilline met een bètalactamaseremmer, waardoor ook bètalactamasevormende bacteriën worden gedekt.","definition":"<p>Clavulaanzuur heeft zelf nauwelijks antibacteriële werking maar remt veel <em>bètalactamasen</em>, zodat amoxicilline niet wordt afgebroken. De combinatie werkt daardoor ook tegen o.a. <em>S. aureus</em> (geen MRSA), <em>H. influenzae</em>, <em>Moraxella</em>, veel <em>E. coli</em> en anaeroben zoals <em>Bacteroides</em>. Bijwerkingen: diarree en (zelden) cholestatische hepatitis.</p>","image_url":"","wiki_title":"Amoxicillin/clavulanic acid","match":"amoxicilline/clavulaanzuur|amoxicilline-clavulaanzuur|augmentin|co-amoxiclav","option_only":true},"sputumkweek":{"title":"Sputumkweek","short":"Bij een sputumkweek wordt opgehoest slijm in het laboratorium gekweekt om de verwekker van een luchtweginfectie en de gevoeligheid voor antibiotica te bepalen.","definition":"<p>Voor een betrouwbare <strong>sputumkweek</strong> moet het materiaal uit de diepere luchtwegen komen en niet vooral uit speeksel (beoordeeld via het aantal plaveiselcellen en leukocyten). Een kweek duurt meestal 1–3 dagen; voor mycobacteriën weken. In de huisartsenpraktijk wordt het weinig gedaan; in het ziekenhuis vooral bij ernstige pneumonie, COPD-exacerbaties en verdenking op tuberculose.</p>","image_url":"","wiki_title":"Sputum culture","match":"sputumkweek|sputum kweek","option_only":true},"hypotensie":{"title":"Hypotensie","short":"Hypotensie is een lage bloeddruk; klinisch relevant als ze leidt tot klachten of onvoldoende doorbloeding van organen.","definition":"<p><strong>Hypotensie</strong> kan constitutioneel en onschuldig zijn. Pathologische hypotensie ontstaat bij ondervulling (bloedverlies, dehydratie), vaatverwijding (sepsis, anafylaxie, medicatie), verminderde pompfunctie (cardiogeen) of obstructie (tamponnade, longembolie). Orthostatische hypotensie treedt op bij opstaan. Een daling van de doorbloeding geeft duizeligheid, verwardheid, oligurie en uiteindelijk shock.</p>","image_url":"","wiki_title":"Hypotension","match":"hypotensie|lage bloeddruk","option_only":true},"pericarditis":{"title":"Pericarditis","short":"Pericarditis is een ontsteking van het hartzakje, met scherpe, houdingsafhankelijke pijn op de borst.","definition":"<p><strong>Pericarditis</strong> wordt meestal veroorzaakt door een virus, maar ook door bacteriën, auto-immuunziekten, nierfalen, tumoren of na een hartinfarct of hartoperatie. Typisch zijn scherpe pijn die verergert bij plat liggen en diep inademen, een pericardwrijven en diffuse ST-elevatie op het ECG. Bij veel vocht in het hartzakje kan een harttamponnade ontstaan.</p>","image_url":"","wiki_title":"Pericarditis","match":"pericarditis|hartzakontsteking","option_only":true},"glomerulonefritis":{"title":"Glomerulonefritis","short":"Glomerulonefritis is een (meestal immunologische) ontsteking van de glomeruli, met hematurie, proteïnurie, hypertensie en/of nierfunctieverlies.","definition":"<p>Bij een <strong>nefritisch syndroom</strong> zijn er erytrocytencilinders, hematurie, hypertensie, oedeem en een dalende nierfunctie. Oorzaken zijn o.a. IgA-nefropathie, poststreptokokken-glomerulonefritis, ANCA-vasculitis, lupusnefritis en anti-GBM-ziekte. Een snel progressieve vorm met halvemaanvorming kan binnen weken tot nierfalen leiden en vereist snelle diagnostiek met nierbiopt.</p>","image_url":"","wiki_title":"Glomerulonephritis","match":"glomerulonefritis","option_only":true},"nierinsufficiëntie":{"title":"Nierinsufficiëntie (nierfalen)","short":"Bij nierinsufficiëntie schiet de nierfunctie tekort, met ophoping van afvalstoffen en verstoring van water-, zout- en zuurhuishouding.","definition":"<p><strong>Acuut nierfalen</strong> ontstaat binnen uren tot dagen en wordt ingedeeld in prerenaal (ondervulling), renaal (bijv. acute tubulusnecrose, glomerulonefritis) en postrenaal (obstructie). <strong>Chronische nierschade</strong> is een eGFR &lt; 60 of nierschade langer dan 3 maanden, meestal door diabetes en hypertensie. Gevolgen zijn o.a. hyperkaliëmie, metabole acidose, anemie (minder EPO), botziekte en hypertensie.</p>","image_url":"","wiki_title":"Kidney failure","match":"nierinsufficiëntie|nierfalen|nierinsufficientie|chronische nierschade","option_only":true},"hypothyreoïdie":{"title":"Hypothyreoïdie","short":"Hypothyreoïdie is een te trage schildklierwerking, met vermoeidheid, kouwelijkheid, gewichtstoename en obstipatie.","definition":"<p><strong>Hypothyreoïdie</strong> wordt in Nederland meestal veroorzaakt door de auto-immuunziekte van Hashimoto, daarnaast na thyreoïdectomie of radioactief jodium, door medicatie (amiodaron, lithium) of zelden door hypofyse-uitval. Klachten: traagheid, kouwelijkheid, droge huid, gewichtstoename, obstipatie, bradycardie en depressieve klachten. Bij primaire hypothyreoïdie is het TSH verhoogd en het vrij T4 laag; behandeling met levothyroxine.</p>","image_url":"","wiki_title":"Hypothyroidism","match":"hypothyreoïdie|hypothyreoidie|trage schildklier","option_only":true},"hyperthyreoïdie":{"title":"Hyperthyreoïdie","short":"Hyperthyreoïdie is een te snelle schildklierwerking, met hartkloppingen, gewichtsverlies, warmte-intolerantie en onrust.","definition":"<p><strong>Hyperthyreoïdie</strong> wordt o.a. veroorzaakt door de ziekte van Graves, een toxisch multinodulair struma, een toxisch adenoom of een (tijdelijke) thyreoïditis. Klachten: hartkloppingen of boezemfibrilleren, gewichtsverlies ondanks goede eetlust, zweten, tremor, onrust, slecht slapen en diarree. Diagnose: laag TSH met verhoogd vrij T4.</p>","image_url":"","wiki_title":"Hyperthyroidism","match":"hyperthyreoïdie|hyperthyreoidie|hyperthyreoïdie|overactieve schildklier","option_only":true},"overgewicht":{"title":"Overgewicht","short":"Overgewicht is een te hoog lichaamsgewicht ten opzichte van de lengte, gedefinieerd als een BMI tussen 25 en 30 kg/m².","definition":"<p>Bij <strong>overgewicht</strong> (BMI 25–30) en vooral bij obesitas (BMI ≥30) neemt het risico op diabetes type 2, hart- en vaatziekten, artrose en sommige kankers toe. De verdeling van het vet is belangrijk: buikvet (gemeten met de middelomtrek) is metabool ongunstiger dan vet op heupen en bovenbenen.</p>","image_url":"","wiki_title":"Overweight","match":"overgewicht","option_only":true},"helicobacter pylori":{"title":"Helicobacter pylori","short":"Helicobacter pylori is een gekromde gramnegatieve bacterie die in de maag leeft en gastritis, ulcera, maagcarcinoom en MALT-lymfoom kan veroorzaken.","definition":"<p><strong><em>Helicobacter pylori</em></strong> overleeft in het zure milieu door urease, dat ureum omzet in ammoniak, en nestelt zich onder de slijmlaag. Besmetting gebeurt meestal op jonge leeftijd. Diagnose met een ademtest, antigeentest in de ontlasting of biopten. Eradicatie gebeurt met een protonpompremmer en twee antibiotica.</p>","image_url":"","wiki_title":"Helicobacter pylori","match":"helicobacter pylori|h. pylori|helicobacter","option_only":true},"coloncarcinoom":{"title":"Coloncarcinoom (darmkanker)","short":"Coloncarcinoom is een kwaadaardige tumor van de dikke darm, meestal een adenocarcinoom dat ontstaat uit een poliep.","definition":"<p>Het <strong>colorectaal carcinoom</strong> ontstaat meestal via de adenoom-carcinoomsequentie, waarbij mutaties (o.a. in APC, KRAS, p53) zich opstapelen. Risicofactoren zijn leeftijd, familiaire belasting (FAP, Lynch-syndroom), IBD, rood en bewerkt vlees, alcohol en roken. Klachten: veranderd ontlastingspatroon, bloed bij de ontlasting en ijzergebreksanemie. In Nederland is er een bevolkingsonderzoek met de FIT-test.</p>","image_url":"","wiki_title":"Colorectal cancer","match":"coloncarcinoom|darmkanker|colorectaal carcinoom|dikkedarmkanker","option_only":true},"coeliakie":{"title":"Coeliakie","short":"Coeliakie is een auto-immuunziekte waarbij gluten een ontsteking van de dunne darm met vlokatrofie veroorzaken.","definition":"<p>Bij <strong>coeliakie</strong> (geassocieerd met HLA-DQ2/DQ8) wordt gliadine door weefseltransglutaminase gemodificeerd en daarna door T-cellen herkend, wat leidt tot vlokatrofie en crypthyperplasie. Klachten: diarree, buikpijn, gewichtsverlies, groeiachterstand, ijzergebrek en vermoeidheid, maar ook atypische presentaties. Diagnose met anti-tTG-antistoffen en een duodenumbiopt; behandeling is een levenslang glutenvrij dieet.</p>","image_url":"","wiki_title":"Coeliac disease","match":"coeliakie|glutenintolerantie|glutenenteropathie","option_only":true},"x-boz":{"title":"X-buikoverzicht (X-BOZ)","short":"Een X-buikoverzicht is een röntgenfoto van de buik, vooral gebruikt om darmafsluiting of vrij lucht aan te tonen.","definition":"<p>Een <strong>X-BOZ</strong> toont darmgaspatronen, verwijde darmlissen met vloeistofspiegels (ileus), vrij lucht (perforatie, beter te zien op een staande X-thorax), stenen en vreemde voorwerpen. Door de beperkte informatie is het in veel situaties vervangen door een echo of CT.</p>","image_url":"","wiki_title":"Abdominal x-ray","match":"x-boz|buikoverzichtsfoto|x-buikoverzicht","option_only":true},"leukocyten":{"title":"Leukocyten (witte bloedcellen)","short":"Leukocyten zijn de witte bloedcellen van het afweersysteem: granulocyten, monocyten en lymfocyten.","definition":"<p><strong>Leukocyten</strong> worden in het beenmerg gemaakt (lymfocyten rijpen deels in thymus en lymfoïde organen). Normaal zijn er ongeveer 4–10 × 10⁹/L in het bloed. De differentiatie onderscheidt neutrofielen, lymfocyten, monocyten, eosinofielen en basofielen; de verhouding geeft aanwijzingen voor bijv. bacteriële infectie, virale infectie, allergie of leukemie.</p>","image_url":"","wiki_title":"White blood cell","match":"leukocyten|witte bloedcellen|leukocyt","option_only":true},"leukocytose":{"title":"Leukocytose","short":"Leukocytose is een verhoogd aantal witte bloedcellen, meestal door infectie of ontsteking.","definition":"<p>Bij <strong>leukocytose</strong> is het aantal leukocyten boven ongeveer 10 × 10⁹/L. Een neutrofiele leukocytose met linksverschuiving past bij bacteriële infectie; ook stress, corticosteroïden, roken, trauma en necrose kunnen het verhogen. Sterk verhoogde waarden met onrijpe cellen in het bloed wijzen op leukemie of een leukemoïde reactie.</p>","image_url":"","wiki_title":"Leukocytosis","match":"leukocytose","option_only":true},"granulocyten":{"title":"Granulocyten","short":"Granulocyten zijn witte bloedcellen met korrels in het cytoplasma: neutrofielen, eosinofielen en basofielen.","definition":"<p><strong>Granulocyten</strong> ontstaan uit de myeloïde lijn via myeloblast, promyelocyt, myelocyt, metamyelocyt en staafkernige vorm. <em>Neutrofielen</em> fagocyteren bacteriën, <em>eosinofielen</em> spelen een rol bij parasitaire infecties en allergie, <em>basofielen</em> geven histamine af. Ze maken deel uit van de aangeboren afweer.</p>","image_url":"","wiki_title":"Granulocyte","match":"granulocyten|granulocyt","option_only":true},"trombopenie":{"title":"Trombocytopenie","short":"Trombocytopenie is een te laag aantal bloedplaatjes, met een verhoogde neiging tot bloedingen.","definition":"<p>Bij <strong>trombocytopenie</strong> (&lt;150 × 10⁹/L) ontstaan pas bij lage waarden (&lt;20–50) spontane huid- en slijmvliesbloedingen zoals petechiën en neusbloedingen. Oorzaken: verminderde aanmaak (beenmergziekte, chemotherapie, B12-tekort), versterkte afbraak (ITP, HIT, DIS, TTP), sequestratie in een vergrote milt of verdunning. Een pseudotrombopenie door klontering in EDTA-buizen moet worden uitgesloten.</p>","image_url":"","wiki_title":"Thrombocytopenia","match":"trombopenie|trombocytopenie","option_only":true},"hemolyse":{"title":"Hemolyse","short":"Hemolyse is het voortijdig afbreken van rode bloedcellen, in de bloedbaan of in milt en lever.","definition":"<p>Bij <strong>hemolyse</strong> zijn het LDH en ongeconjugeerd bilirubine verhoogd, het haptoglobine verlaagd en het aantal reticulocyten gestegen. Oorzaken kunnen in de cel liggen (membraandefecten zoals sferocytose, enzymdefecten zoals G6PD-deficiëntie, hemoglobinopathieën) of erbuiten (auto-antistoffen, transfusiereacties, mechanische beschadiging, infecties zoals malaria). Hemolyse kan ook een kunstmatige laboratoriumfout zijn bij moeizame bloedafname.</p>","image_url":"","wiki_title":"Hemolysis","match":"hemolyse|hemolytische anemie","option_only":true},"hemochromatose":{"title":"Hemochromatose","short":"Hemochromatose is een erfelijke ijzerstapelingsziekte waarbij te veel ijzer uit de darm wordt opgenomen.","definition":"<p>Bij <strong>hereditaire hemochromatose</strong> (meestal homozygotie voor de C282Y-mutatie in het HFE-gen) is er te weinig hepcidine, waardoor ijzer ongeremd wordt opgenomen. IJzer stapelt in lever, pancreas, hart, gewrichten en huid, met leverfibrose of -cirrose, diabetes, cardiomyopathie, artropathie en een bronzen huid. De transferrineverzadiging en het ferritine zijn verhoogd; behandeling met aderlatingen.</p>","image_url":"","wiki_title":"Hemochromatosis","match":"hemochromatose|hereditaire hemochromatose|ijzerstapeling","option_only":true},"humorale afweer":{"title":"Humorale afweer","short":"De humorale afweer is het deel van de verworven afweer dat via antistoffen van B-cellen werkt.","definition":"<p>Bij de <strong>humorale afweer</strong> herkennen B-cellen een antigeen, worden ze (meestal met hulp van T-helpercellen) geactiveerd en differentiëren ze tot plasmacellen die antistoffen maken. Antistoffen neutraliseren toxines en virussen, opsoniseren bacteriën en activeren complement. Ze zijn vooral belangrijk tegen extracellulaire bacteriën; een tekort geeft recidiverende luchtweginfecties.</p>","image_url":"","wiki_title":"Humoral immunity","match":"humorale afweer|humorale immuniteit","option_only":true},"reumatoïde artritis":{"title":"Reumatoïde artritis","short":"Reumatoïde artritis is een chronische auto-immuunziekte met symmetrische ontsteking van vooral de kleine gewrichten van handen en voeten.","definition":"<p>Bij <strong>reumatoïde artritis</strong> leidt synovitis tot pannusvorming en erosie van kraakbeen en bot. Kenmerken: symmetrische polyartritis van MCP-, PIP- en MTP-gewrichten, ochtendstijfheid langer dan een uur, reumafactor en anti-CCP-antistoffen. Extra-articulair: reumanoduli, longaandoeningen, vasculitis. Vroege behandeling met DMARD's (zoals methotrexaat) voorkomt gewrichtsschade.</p>","image_url":"","wiki_title":"Rheumatoid arthritis","match":"reumatoïde artritis|reumatoide artritis|reumatoïde arthritis","option_only":true},"artritis":{"title":"Artritis","short":"Artritis is een ontsteking van een gewricht, met pijn, zwelling, warmte en bewegingsbeperking.","definition":"<p><strong>Artritis</strong> wordt ingedeeld naar het aantal gewrichten (mono-, oligo-, polyartritis) en de oorzaak: infectieus (septische artritis), kristalgeïnduceerd (jicht, pseudojicht), auto-immuun (reumatoïde artritis, spondyloartritis, SLE) of reactief. Bij een acute monoartritis is een gewrichtspunctie belangrijk om infectie en kristallen aan te tonen.</p>","image_url":"","wiki_title":"Arthritis","match":"artritis|arthritis|gewrichtsontsteking","option_only":true},"jicht":{"title":"Jicht","short":"Jicht is een gewrichtsontsteking door neerslag van uraatkristallen bij een verhoogd urinezuur.","definition":"<p>Bij <strong>jicht</strong> slaan mononatriumuraatkristallen neer in en rond gewrichten. Een aanval begint plotseling, vaak ’s nachts, met een rood, gezwollen, zeer pijnlijk gewricht. Uitlokkers zijn alcohol, purinerijk voedsel, diuretica en uitdroging. In het gewrichtsvocht zijn naaldvormige, negatief dubbelbrekende kristallen te zien. Behandeling van een aanval met NSAID's, colchicine of corticosteroïden; preventie met allopurinol.</p>","image_url":"","wiki_title":"Gout","match":"jicht|arthritis urica|podagra","option_only":true},"spondylartrose":{"title":"Spondylartrose","short":"Spondylartrose is artrose van de facetgewrichten van de wervelkolom, vaak samen met degeneratie van tussenwervelschijven.","definition":"<p>Bij <strong>spondylartrose</strong> ontstaan kraakbeenverlies, osteofyten en kapselverdikking in de facetgewrichten. Het komt veel voor op oudere leeftijd en geeft niet altijd klachten. Osteofyten kunnen het wervelkanaal of de foramina vernauwen, met wortelprikkeling of een lumbaal kanaalstenose als gevolg.</p>","image_url":"","wiki_title":"Spondylosis","match":"spondylartrose|spondylose","option_only":true},"osteoporose":{"title":"Osteoporose","short":"Osteoporose is een verlaagde botmassa met verzwakte botstructuur, waardoor botten sneller breken.","definition":"<p>Bij <strong>osteoporose</strong> is de afbraak van bot groter dan de opbouw. Risicofactoren: hoge leeftijd, postmenopauzaal oestrogeentekort, corticosteroïden, laag lichaamsgewicht, roken, alcohol en weinig beweging. Typische fracturen zijn wervelinzakkingen, heupfracturen en distale radiusfracturen. Diagnose met een DEXA-scan (T-score ≤ −2,5); behandeling o.a. met bisfosfonaten, calcium en vitamine D.</p>","image_url":"","wiki_title":"Osteoporosis","match":"osteoporose|botontkalking","option_only":true},"osteomyelitis":{"title":"Osteomyelitis","short":"Osteomyelitis is een infectie van het bot, meestal door Staphylococcus aureus.","definition":"<p><strong>Osteomyelitis</strong> ontstaat via de bloedbaan (vooral bij kinderen in de metafysen van lange pijpbeenderen), vanuit een nabijgelegen infectie (bijv. diabetische voet, decubitus) of na een open fractuur of operatie. Klachten: pijn, koorts, zwelling. Diagnose met MRI en kweek (bot of bloed). Chronische osteomyelitis met dood bot (sequester) vergt vaak chirurgie naast langdurige antibiotica.</p>","image_url":"","wiki_title":"Osteomyelitis","match":"osteomyelitis|botontsteking","option_only":true},"polymyalgia reumatica":{"title":"Polymyalgia reumatica","short":"Polymyalgia reumatica is een ontstekingsziekte bij ouderen met pijn en stijfheid in schouder- en heupgordel.","definition":"<p><strong>Polymyalgia reumatica</strong> treft vooral mensen boven de 50, vaker vrouwen. Kenmerkend zijn ochtendstijfheid en pijn in nek, schouders en heupen, met moeite om op te staan of de armen te heffen, en een sterk verhoogde BSE/CRP. Er is geen echte spierzwakte. De ziekte reageert snel op lage dosis prednison en gaat soms samen met reuscelarteriitis.</p>","image_url":"","wiki_title":"Polymyalgia rheumatica","match":"polymyalgia reumatica|polymyalgia rheumatica|pmr","option_only":true},"arteritis temporalis":{"title":"Arteriitis temporalis (reuscelarteriitis)","short":"Arteriitis temporalis is een granulomateuze vasculitis van grote en middelgrote arteriën bij ouderen, met risico op blindheid.","definition":"<p>Bij <strong>reuscelarteriitis</strong> zijn vooral takken van de a. carotis externa (zoals de a. temporalis) en soms de aorta en haar takken ontstoken. Klachten: nieuwe hoofdpijn, gevoelige slaapslagader, kauwclaudicatie, visusstoornissen en algemene malaise, met een sterk verhoogde BSE/CRP. Bij verdenking direct hoge dosis prednison om blindheid te voorkomen; diagnose met echo of biopt.</p>","image_url":"","wiki_title":"Giant cell arteritis","match":"arteritis temporalis|arteriitis temporalis|reuscelarteriitis|giant cell arteritis","option_only":true},"pariarteriitis nodosa":{"title":"Polyarteriitis nodosa","short":"Polyarteriitis nodosa is een necrotiserende vasculitis van middelgrote arteriën, zonder ANCA en zonder glomerulonefritis.","definition":"<p>Bij <strong>polyarteriitis nodosa</strong> raken middelgrote spierarteriën ontstoken, met microaneurysmata en infarcten in o.a. nieren (hypertensie), darm (buikpijn), huid (livedo, ulcera) en zenuwen (mononeuritis multiplex). Een deel van de gevallen hangt samen met hepatitis B. De longen zijn meestal niet aangedaan.</p>","image_url":"","wiki_title":"Polyarteritis nodosa","match":"pariarteriitis nodosa|polyarteriitis nodosa|periarteriitis nodosa","option_only":true},"ziekte van kawasaki":{"title":"Ziekte van Kawasaki","short":"De ziekte van Kawasaki is een vasculitis bij jonge kinderen met langdurige koorts; de belangrijkste complicatie zijn coronaire aneurysmata.","definition":"<p>De <strong>ziekte van Kawasaki</strong> treft vooral kinderen onder de 5 jaar. Kenmerken: koorts van minstens vijf dagen met conjunctivitis zonder pus, veranderingen van lippen en mondslijmvlies (aardbeientong), huiduitslag, roodheid en zwelling van handen en voeten (later vervellen) en een vergrote halsklier. Behandeling met intraveneuze immunoglobulinen en acetylsalicylzuur verkleint de kans op coronaire aneurysmata.</p>","image_url":"","wiki_title":"Kawasaki disease","match":"ziekte van kawasaki|kawasaki|mucocutaan lymfekliersyndroom","option_only":true},"infliximab":{"title":"Infliximab","short":"Infliximab is een monoklonaal antilichaam tegen TNF-α, gebruikt bij o.a. de ziekte van Crohn, colitis ulcerosa en reumatoïde artritis.","definition":"<p><strong>TNF-α-remmers</strong> zoals infliximab, adalimumab en etanercept remmen een centraal pro-inflammatoir cytokine. Ze worden gebruikt bij IBD, reumatoïde artritis, spondyloartritis en psoriasis. Doordat ze de cellulaire afweer verzwakken, kan latente tuberculose reactiveren; daarom wordt vooraf gescreend. Ook het risico op andere infecties is verhoogd.</p>","image_url":"","wiki_title":"Infliximab","match":"infliximab|anti-tnf|tnf-alfa antagonist|tnf-remmer","option_only":true},"methotrexaat":{"title":"Methotrexaat","short":"Methotrexaat is een foliumzuurantagonist; in lage dosis een basismiddel bij reumatoïde artritis en psoriasis, in hoge dosis een cytostaticum.","definition":"<p><strong>Methotrexaat</strong> remt dihydrofolaatreductase. In lage, wekelijkse dosering werkt het ontstekingsremmend (o.a. via adenosine) en is het een hoeksteen bij reumatoïde artritis, psoriasis en IBD; foliumzuur vermindert bijwerkingen. Bijwerkingen: beenmergsuppressie, levertoxiciteit, mucositis en pneumonitis. Het is teratogeen en wordt via de nier uitgescheiden.</p>","image_url":"","wiki_title":"Methotrexate","match":"methotrexaat|mtx|methotrexate","option_only":true},"nsaids":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"nsaids|nsaid|nsaid's|antiflogistica|ontstekingsremmers","option_only":true},"psoriasis":{"title":"Psoriasis","short":"Psoriasis is een chronische ontstekingsziekte van de huid met scherp begrensde rode plaques met zilverwitte schilfers.","definition":"<p>Bij <strong>psoriasis</strong> stimuleert een T-celreactie (IL-23/Th17) een sterk versnelde deling van keratinocyten. Er ontstaan schilferende plaques op strekzijden, hoofdhuid en bilnaad, met nagelafwijkingen en het köbnerfenomeen. Een deel van de patiënten krijgt artritis psoriatica. Behandeling met lokale middelen, lichttherapie of systemische en biologische middelen.</p>","image_url":"","wiki_title":"Psoriasis","match":"psoriasis","option_only":true},"seborroïsch eczeem":{"title":"Seborroïsch eczeem","short":"Seborroïsch eczeem is een chronisch terugkerend eczeem met roodheid en vettige schilfers in talgklierrijke gebieden.","definition":"<p><strong>Seborroïsch eczeem</strong> komt voor op het behaarde hoofd, in de wenkbrauwen, nasolabiale plooien, achter de oren en op de borst. De gist <em>Malassezia</em> speelt een rol. Bij zuigelingen kennen we het als berg. Het komt vaker voor bij de ziekte van Parkinson en hiv. Behandeling met antimycotische middelen, eventueel kort met een mild corticosteroïd.</p>","image_url":"","wiki_title":"Seborrhoeic dermatitis","match":"seborroïsch eczeem|seborroisch eczeem|seborroïsche dermatitis","option_only":true},"contactallergisch eczeem":{"title":"Contactallergisch eczeem","short":"Contactallergisch eczeem is een type IV-overgevoeligheidsreactie van de huid op een stof waarvoor iemand gesensibiliseerd is.","definition":"<p>Bij <strong>allergisch contacteczeem</strong> wordt de huid eerst gesensibiliseerd voor een stof (bijv. nikkel, parfum, rubberchemicaliën, conserveermiddelen). Bij herhaald contact ontstaat na 1–3 dagen een jeukend eczeem, dat zich ook buiten het contactgebied kan uitbreiden. Diagnose met plakproeven (epicutane test); behandeling is vermijden van het allergeen.</p>","image_url":"","wiki_title":"Allergic contact dermatitis","match":"contactallergisch eczeem|allergisch contacteczeem","option_only":true},"nummulair eczeem":{"title":"Nummulair eczeem","short":"Nummulair eczeem geeft muntvormige, scherp begrensde, jeukende en soms nattende eczeemplekken, vaak op de benen.","definition":"<p><strong>Nummulair eczeem</strong> komt vaak voor bij een droge huid, vooral bij oudere mannen, en kan verergeren in de winter. De ronde plekken zijn vaak sterk jeukend en kunnen secundair geïnfecteerd raken. Behandeling met vette zalven en lokale corticosteroïden.</p>","image_url":"","wiki_title":"Nummular dermatitis","match":"nummulair eczeem|eczema nummulare","option_only":true},"open comedonen":{"title":"Open comedonen (mee-eters)","short":"Open comedonen zijn verstopte talgklierfollikels met een donker propje aan de opening, een beginvorm van acne.","definition":"<p>Bij acne raakt de follikel verstopt door verhoorning en talg. Een <strong>open comedo</strong> (blackhead) heeft een wijde opening; de zwarte kleur komt door geoxideerde talg en melanine, niet door vuil. Een gesloten comedo (whitehead) heeft een nauwe opening. Uit comedonen kunnen ontstoken papels en pustels ontstaan.</p>","image_url":"","wiki_title":"Comedo","match":"open comedonen|open comedo|mee-eters|blackheads","option_only":true},"conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies, met een rood oog, tranen of afscheiding en een branderig gevoel, zonder visusdaling.","definition":"<p><strong>Conjunctivitis</strong> kan viraal (vaak adenovirus, waterige afscheiding), bacterieel (purulente afscheiding) of allergisch (jeuk, beide ogen, seizoensgebonden) zijn. Het zicht is normaal en er is meestal geen echte pijn of lichtschuwheid; die passen eerder bij keratitis, uveïtis of glaucoom. Bij pasgeborenen moet aan chlamydia of gonokokken worden gedacht.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"conjunctivitis|bindvliesontsteking","option_only":true},"morfine":{"title":"Morfine","short":"Morfine is een sterk werkend opioïd dat µ-opioïdreceptoren activeert; gebruikt bij ernstige pijn en kortademigheid in de palliatieve fase.","definition":"<p><strong>Morfine</strong> werkt pijnstillend via µ-receptoren in het centrale zenuwstelsel. Bijwerkingen zijn obstipatie (altijd een laxans erbij), misselijkheid, sufheid, ademhalingsdepressie, miosis en jeuk; bij langdurig gebruik ontstaan tolerantie en afhankelijkheid. De actieve metabolieten worden via de nier uitgescheiden en hopen op bij nierfalen. Antidotum: naloxon.</p>","image_url":"","wiki_title":"Morphine","match":"morfine|morphine","option_only":true},"hyaluronzuur":{"title":"Hyaluronzuur","short":"Hyaluronzuur is een groot, niet-gesulfateerd glycosaminoglycaan dat veel water bindt en de grondsubstantie en gewrichtsvloeistof stroperig maakt.","definition":"<p><strong>Hyaluronzuur</strong> is anders dan de andere glycosaminoglycanen niet aan een eiwitkern gebonden en wordt aan het celmembraan gemaakt. Het vormt de ruggengraat waaraan proteoglycanen (zoals aggrecan in kraakbeen) binden. Het komt veel voor in synoviaal vocht, glasvocht, huid en losmazig bindweefsel.</p>","image_url":"","wiki_title":"Hyaluronic acid","match":"hyaluronzuur|hyaluronan","option_only":true},"icterus":{"title":"Icterus (geelzucht)","short":"Icterus is gele verkleuring van huid, sclerae en slijmvliezen door een verhoogd bilirubine.","definition":"<p><strong>Icterus</strong> wordt meestal zichtbaar bij een bilirubine boven ongeveer 40–50 µmol/L. Men onderscheidt prehepatisch (hemolyse, vooral ongeconjugeerd bilirubine), hepatisch (leverziekte) en posthepatisch (galwegobstructie, met donkere urine en ontkleurde ontlasting). Bij pasgeborenen is lichte icterus in de eerste dagen fysiologisch.</p>","image_url":"","wiki_title":"Jaundice","match":"icterus|geelzucht","option_only":true},"prostaatcarcinoom":{"title":"Prostaatcarcinoom","short":"Het prostaatcarcinoom is een kwaadaardige tumor van de prostaat, meestal een adenocarcinoom uitgaand van de perifere zone.","definition":"<p><strong>Prostaatkanker</strong> komt vooral voor bij oudere mannen en groeit vaak langzaam. Vroege stadia geven meestal geen klachten; gevorderde stadia kunnen plasklachten en botmetastasen (botpijn) geven. Diagnostiek met rectaal toucher, PSA, MRI en biopten (Gleason-score). Behandeling varieert van actief volgen tot operatie, radiotherapie en hormonale therapie.</p>","image_url":"","wiki_title":"Prostate cancer","match":"prostaatcarcinoom|prostaatkanker","option_only":true},"bse":{"title":"Bezinkingssnelheid (BSE)","short":"De BSE meet hoe snel rode bloedcellen in een buisje uitzakken; een verhoogde waarde wijst op ontsteking, maar is weinig specifiek.","definition":"<p>De <strong>bezinkingssnelheid</strong> stijgt doordat acutefase-eiwitten (vooral fibrinogeen) en immunoglobulinen de rode bloedcellen in rouleaux laten samenklonteren. Ze stijgt en daalt trager dan het CRP. Sterk verhoogde waarden passen bij o.a. reuscelarteriitis, polymyalgia reumatica, multipel myeloom en ernstige infecties. Leeftijd, geslacht en anemie beïnvloeden de waarde.</p>","image_url":"","wiki_title":"Erythrocyte sedimentation rate","match":"bse|bezinking|bezinkingssnelheid|erytrocytenbezinking","option_only":true},"diverticulitis":{"title":"Diverticulitis","short":"Diverticulitis is een ontsteking van een of meer divertikels (uitstulpingen) van de dikke darm.","definition":"<p>Bij <b>diverticulitis</b> raakt een divertikel ontstoken, vermoedelijk door obstructie en microperforatie. Divertikels ontstaan vooral bij ouderen en bij vezelarme voeding. De ernst wordt ingedeeld volgens Hinchey (van lokale ontsteking tot abces en perforatie met peritonitis). Diagnose met echo of CT; ongecompliceerde gevallen worden meestal conservatief behandeld.</p>","image_url":"","wiki_title":"Diverticulitis","match":"diverticulitis","option_only":true},"m-proteïne":{"title":"M-proteïne (paraproteïne)","short":"Een M-proteïne is een monoklonaal immunoglobuline of een lichte keten, gemaakt door één kloon van plasmacellen of B-cellen.","definition":"<p>Een <strong>M-proteïne</strong> is te zien als een smalle piek (M-piek) in het eiwitspectrum en wordt getypeerd met immunofixatie. Het komt voor bij MGUS (een voorstadium zonder klachten), het multipel myeloom, AL-amyloïdose en sommige lymfomen. Vrije lichte ketens in de urine heten Bence-Jones-eiwit.</p>","image_url":"","wiki_title":"Paraproteinemia","match":"m-proteïne|m-proteine|paraproteïne|monoklonaal eiwit","option_only":true},"non-hodgkin lymfoom":{"title":"Non-Hodgkinlymfoom","short":"Non-Hodgkinlymfomen zijn een grote groep kwaadaardige ziekten van B-, T- of NK-cellen, van indolent tot zeer agressief.","definition":"<p><strong>Non-Hodgkinlymfomen</strong> worden ingedeeld naar celtype en gedrag. Indolente vormen (bijv. folliculair lymfoom) groeien langzaam maar zijn vaak niet te genezen; agressieve vormen (bijv. diffuus grootcellig B-cellymfoom, Burkitt) groeien snel maar zijn vaak wel curabel. Klachten: pijnloze lymfeklierzwelling, B-symptomen en extranodale lokalisaties.</p>","image_url":"","wiki_title":"Non-Hodgkin lymphoma","match":"non-hodgkin lymfoom|non-hodgkinlymfoom|nhl","option_only":true},"rituximab":{"title":"Rituximab","short":"Rituximab is een monoklonaal antilichaam tegen CD20 op B-cellen; gebruikt bij lymfomen, CLL en auto-immuunziekten.","definition":"<p><strong>Rituximab</strong> bindt aan CD20 op rijpe B-cellen en vernietigt ze via complement en ADCC. Plasmacellen (CD20-negatief) blijven gespaard. Indicaties zijn B-cel-non-Hodgkinlymfomen, CLL, reumatoïde artritis en ANCA-vasculitis. Bijwerkingen: infusiereacties, infecties en reactivatie van hepatitis B.</p>","image_url":"","wiki_title":"Rituximab","match":"rituximab|anti-cd20","option_only":true},"corticosteroïden":{"title":"Corticosteroïden","short":"Corticosteroïden zijn van cortisol afgeleide middelen met sterke ontstekingsremmende en immunosuppressieve werking.","definition":"<p>Glucocorticoïden binden aan een intracellulaire receptor en remmen de transcriptie van ontstekingsgenen (cytokines, COX-2) en de vorming van ontstekingsmediatoren. Ze worden lokaal (huid, inhalatie, injectie) en systemisch gebruikt. Bij langdurig systemisch gebruik: osteoporose, hyperglykemie, gewichtstoename, huidatrofie, infecties, spierzwakte, cataract en remming van de eigen bijnier (niet abrupt stoppen).</p>","image_url":"","wiki_title":"Corticosteroid","match":"corticosteroïden|corticosteroiden|glucocorticoïden|corticosteroïd","option_only":true},"hydroxychloroquine":{"title":"Hydroxychloroquine","short":"Hydroxychloroquine is een antimalariamiddel dat als mild immunomodulerend middel wordt gebruikt bij SLE en reumatoïde artritis.","definition":"<p><strong>Hydroxychloroquine</strong> remt o.a. de antigeenpresentatie en Toll-like-receptorsignalering door de pH in lysosomen te verhogen. Het is een basismiddel bij SLE (minder opvlammingen) en wordt gecombineerd bij reumatoïde artritis. Bij langdurig gebruik kan retinopathie ontstaan; daarom vindt oogheelkundige controle plaats.</p>","image_url":"","wiki_title":"Hydroxychloroquine","match":"hydroxychloroquine|plaquenil","option_only":true},"myocarditis":{"title":"Myocarditis","short":"Myocarditis is een ontsteking van de hartspier, meestal door een virus, met pijn op de borst, ritmestoornissen of hartfalen.","definition":"<p><strong>Myocarditis</strong> wordt vaak veroorzaakt door virussen (o.a. enterovirussen, parvovirus B19, SARS-CoV-2), maar ook door auto-immuunziekten, medicatie of vaccins. Klachten variëren van milde pijn op de borst met troponinestijging tot acuut hartfalen en plotse dood. Diagnose met cardiale MRI. Sporten wordt na myocarditis maanden afgeraden.</p>","image_url":"","wiki_title":"Myocarditis","match":"myocarditis|hartspierontsteking","option_only":true},"hypoxie":{"title":"Hypoxie","short":"Hypoxie is een tekort aan zuurstof in weefsels; hypoxemie is een te lage zuurstofspanning in het bloed.","definition":"<p>Oorzaken van <strong>hypoxemie</strong> zijn hypoventilatie, ventilatie-perfusiemismatch, shunt, diffusiestoornis en een lage zuurstofspanning in de ingeademde lucht (hoogte). Weefselhypoxie kan ook ontstaan bij anemie, koolmonoxidevergiftiging, verminderde doorbloeding of mitochondriale vergiftiging (cyanide). Cellen schakelen dan over op anaerobe stofwisseling, met lactaatvorming.</p>","image_url":"","wiki_title":"Hypoxia (medicine)","match":"hypoxie|hypoxemie|zuurstoftekort","option_only":true},"niercarcinoom":{"title":"Niercelcarcinoom","short":"Het niercelcarcinoom is een kwaadaardige tumor van het nierepitheel, meestal van het heldercellige type.","definition":"<p>Het <strong>niercelcarcinoom</strong> wordt vaak toevallig ontdekt op beeldvorming. De klassieke trias (hematurie, flankpijn, palpabele massa) is zeldzaam. Paraneoplastische verschijnselen zijn polycytemie (EPO), hypercalciëmie en koorts. Risicofactoren: roken, obesitas, hypertensie en het von Hippel-Lindau-syndroom. Het groeit soms in de nierader en v. cava in.</p>","image_url":"","wiki_title":"Renal cell carcinoma","match":"niercarcinoom|niercelcarcinoom|nierkanker","option_only":true},"cervixcarcinoom":{"title":"Cervixcarcinoom","short":"Het cervixcarcinoom is kanker van de baarmoederhals, vrijwel altijd veroorzaakt door een persisterende infectie met hoog-risico-HPV.","definition":"<p>Het <strong>cervixcarcinoom</strong> ontstaat via voorstadia (CIN) in de transformatiezone, meestal als plaveiselcelcarcinoom. Klachten: contactbloedingen (na gemeenschap), intermenstrueel bloedverlies en afscheiding. Preventie via HPV-vaccinatie en het bevolkingsonderzoek (hrHPV-test). Behandeling afhankelijk van stadium: operatie of (chemo)radiatie.</p>","image_url":"","wiki_title":"Cervical cancer","match":"cervixcarcinoom|baarmoederhalskanker","option_only":true},"borrelia burgdorferi":{"title":"Borrelia burgdorferi","short":"Borrelia burgdorferi is de spirocheet die door teken wordt overgebracht en de ziekte van Lyme veroorzaakt.","definition":"<p><strong><em>Borrelia burgdorferi</em></strong> wordt overgebracht door de schapenteek (<em>Ixodes ricinus</em>), meestal pas na een aanhechting van meer dan 24 uur. Vroege lokale infectie geeft erythema migrans; verspreiding kan leiden tot neuroborreliose, lyme-artritis, carditis (AV-blok) en huidafwijkingen (acrodermatitis). Behandeling met doxycycline of ceftriaxon.</p>","image_url":"","wiki_title":"Borrelia burgdorferi","match":"borrelia burgdorferi|borrelia","option_only":true},"herpes encefalitis":{"title":"Herpes-simplexencefalitis","short":"Herpes-simplexencefalitis is een ernstige virale ontsteking van de hersenen, typisch in de temporaalkwabben.","definition":"<p>Bij <strong>HSV-encefalitis</strong> (meestal HSV-1) ontstaan koorts, hoofdpijn, verwardheid, gedrags- en spraakstoornissen en epileptische aanvallen. MRI toont afwijkingen in de mediale temporaalkwab; de liquor toont lymfocyten en HSV-PCR is positief. Onbehandeld is de sterfte hoog; bij verdenking wordt direct aciclovir intraveneus gestart.</p>","image_url":"","wiki_title":"Herpes simplex encephalitis","match":"herpes encefalitis|herpesencefalitis|herpes simplex encefalitis|hsv-encefalitis","option_only":true},"meningokokkenmeningitis":{"title":"Meningokokkenmeningitis","short":"Meningokokkenmeningitis is een hersenvliesontsteking door Neisseria meningitidis, vaak met een snel verlopende sepsis en petechiën.","definition":"<p>Bij een <strong>invasieve meningokokkeninfectie</strong> kunnen binnen uren koorts, hoofdpijn, nekstijfheid, sufheid en niet-wegdrukbare petechiën ontstaan, soms met shock en diffuse intravasale stolling. Bij verdenking (zeker met petechiën) wordt zo snel mogelijk een antibioticum gegeven. Nauwe contacten krijgen profylaxe; er is vaccinatie tegen serogroepen ACWY en B.</p>","image_url":"","wiki_title":"Meningococcal disease","match":"meningokokkenmeningitis|meningokokkensepsis","option_only":true},"ascariasis":{"title":"Ascariasis (spoelworm)","short":"Ascariasis is een infectie met de grote spoelworm Ascaris lumbricoides, opgelopen via eitjes in besmet voedsel of grond.","definition":"<p>Bij <strong>ascariasis</strong> komen larven uit de darm via bloed en longen (soms met hoest en eosinofilie: syndroom van Löffler) terug in de darm, waar ze uitgroeien tot wormen van 15–35 cm. Lichte infecties geven weinig klachten; zware infecties kunnen darmobstructie, galwegobstructie en ondervoeding geven. Behandeling met mebendazol of albendazol.</p>","image_url":"","wiki_title":"Ascariasis","match":"ascariasis|ascaris lumbricoides|spoelworm","option_only":true},"amoebiasis":{"title":"Amoebiasis","short":"Amoebiasis is een infectie met Entamoeba histolytica, die bloederige diarree en leverabcessen kan veroorzaken.","definition":"<p><strong><em>Entamoeba histolytica</em></strong> wordt via cysten in besmet water of voedsel opgelopen. Invasieve infectie van het colon geeft amoebendysenterie met kolfvormige ulcera. Via de v. portae kan een amoebenleverabces ontstaan, met koorts en pijn rechtsboven. Behandeling met metronidazol, gevolgd door een middel dat de cysten in de darm doodt.</p>","image_url":"","wiki_title":"Amoebiasis","match":"amoebiasis|amoebendysenterie|entamoeba histolytica","option_only":true},"trichophyton rubrum":{"title":"Trichophyton rubrum","short":"Trichophyton rubrum is een dermatofyt en de meest voorkomende oorzaak van voetschimmel en schimmelnagels.","definition":"<p><strong>Dermatofyten</strong> leven van keratine in de hoornlaag, haren en nagels. <em>T. rubrum</em> veroorzaakt tinea pedis (tussen de tenen), tinea unguium (onychomycose), tinea cruris en tinea corporis (ringvormige plekken met een schilferende, actieve rand). Diagnose met KOH-preparaat of kweek; behandeling met lokale of orale antimycotica (terbinafine).</p>","image_url":"","wiki_title":"Trichophyton rubrum","match":"trichophyton rubrum|trichophyton|dermatofyt","option_only":true},"psoriasis guttata":{"title":"Psoriasis guttata","short":"Psoriasis guttata is een vorm van psoriasis met veel kleine, druppelvormige schilferende plekjes, vaak na een keelontsteking met streptokokken.","definition":"<p><strong>Psoriasis guttata</strong> komt vooral bij kinderen en jongvolwassenen voor en ontstaat vaak 1–3 weken na een streptokokkeninfectie van de keel. Over romp en ledematen verschijnen talrijke kleine rode, schilferende papels. Het kan spontaan verdwijnen of overgaan in chronische plaque-psoriasis.</p>","image_url":"","wiki_title":"Guttate psoriasis","match":"psoriasis guttata","option_only":true},"leucocytose":{"title":"Leukocytose","short":"Leukocytose is een verhoogd aantal witte bloedcellen, meestal door infectie of ontsteking.","definition":"<p>Bij <strong>leukocytose</strong> is het aantal leukocyten boven ongeveer 10 × 10⁹/L. Een neutrofiele leukocytose met linksverschuiving past bij bacteriële infectie; ook stress, corticosteroïden, roken, trauma en necrose kunnen het verhogen. Sterk verhoogde waarden met onrijpe cellen in het bloed wijzen op leukemie of een leukemoïde reactie.</p>","image_url":"","wiki_title":"Leukocytosis","match":"leucocytose","option_only":true},"niet-steroïdale anti-inflammatoire drugs (nsaids)":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"niet-steroïdale anti-inflammatoire drugs (nsaids)","option_only":true},"nsaid’s":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"nsaid’s","option_only":true},"lobaire pneumonie, veroorzaakt door pneumokokken":{"title":"Pneumonie","short":"Een pneumonie is een infectie van het longweefsel (alveoli), meestal door bacteriën of virussen, met koorts, hoesten en kortademigheid.","definition":"<p>Bij een <strong>pneumonie</strong> (longontsteking) raken de alveoli ontstoken en vullen ze zich met ontstekingsvocht en cellen. Daardoor is minder longoppervlak beschikbaar voor gaswisseling.</p><p>Typische klachten zijn koorts, hoesten (vaak met sputum), kortademigheid en soms pijn bij het ademen. Bij lichamelijk onderzoek kunnen crepitaties of een gedempte percussie optreden; een X-thorax toont een infiltraat. De meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie is <em>Streptococcus pneumoniae</em>.</p>","image_url":"","wiki_title":"Pneumonia","match":"lobaire pneumonie, veroorzaakt door pneumokokken","option_only":true},"mycobacterium tuberculosis (tuberculose)":{"title":"Mycobacterium tuberculosis","short":"M. tuberculosis is de zuurvaste, langzaam groeiende staafbacterie die tuberculose veroorzaakt.","definition":"<p><strong><em>Mycobacterium tuberculosis</em></strong> is een aerobe staafbacterie met een wasachtige, mycolzuurrijke celwand. Daardoor kleurt hij niet goed met de gramkleuring maar wel met de Ziehl-Neelsenkleuring (<em>zuurvast</em>).</p><p>Hij wordt aerogeen overgedragen, groeit zeer langzaam (weken in kweek) en overleeft in macrofagen. De afweer is vooral cellulair (T-cellen) en leidt tot granulomen met centrale verkazing. Hij veroorzaakt tuberculose.</p>","image_url":"","wiki_title":"Mycobacterium tuberculosis","match":"mycobacterium tuberculosis (tuberculose)","option_only":true},"bofvirus":{"title":"Bof","short":"Bof is een virale infectie (paramyxovirus) met pijnlijke zwelling van de oorspeekselklieren; complicaties zijn orchitis, meningitis en doofheid.","definition":"<p><strong>Bof</strong> (parotitis epidemica) wordt veroorzaakt door het bofvirus, een omhuld RNA-virus. Het wordt via druppels overgedragen.</p><p>Het typische beeld is een pijnlijke zwelling van één of beide <em>glandulae parotideae</em>, met koorts en malaise. Complicaties zijn orchitis (vooral na de puberteit), oöforitis, pancreatitis, meningitis en eenzijdige doofheid. Er wordt tegen gevaccineerd met het BMR-vaccin.</p>","image_url":"","wiki_title":"Mumps","match":"bofvirus","option_only":true},"epstein-barrvirusinfectie":{"title":"Epstein-Barrvirus (EBV)","short":"EBV is een herpesvirus dat B-cellen infecteert; het veroorzaakt de ziekte van Pfeiffer en is geassocieerd met enkele kankers.","definition":"<p>Het <strong>Epstein-Barrvirus</strong> wordt via speeksel overgedragen. Op jonge leeftijd verloopt infectie vaak ongemerkt; bij adolescenten geeft het vaak mononucleosis infectiosa. Het virus blijft levenslang latent in B-cellen. EBV is geassocieerd met o.a. het Burkittlymfoom, het nasofarynxcarcinoom, sommige Hodgkinlymfomen en posttransplantatie-lymfoproliferatieve ziekte.</p>","image_url":"","wiki_title":"Epstein–Barr virus","match":"epstein-barrvirusinfectie","option_only":true},"herpes simplexvirus type 1":{"title":"Herpes simplexvirus (HSV)","short":"Het herpes simplexvirus veroorzaakt blaasjes op huid en slijmvliezen en blijft daarna latent in sensibele ganglia.","definition":"<p>Er zijn twee typen: <strong>HSV-1</strong> (vooral oraal, koortslip, gingivostomatitis) en <strong>HSV-2</strong> (vooral genitaal), al overlappen ze. Na de primaire infectie blijft het virus latent in sensibele ganglia en kan het reactiveren. Ernstige vormen zijn herpesencefalitis, keratitis, eczema herpeticum en neonatale herpes. Behandeling met (val)aciclovir.</p>","image_url":"","wiki_title":"Herpes simplex virus","match":"herpes simplexvirus type 1","option_only":true},"diabetes type 2":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes type 2","option_only":true},"streptococcus pneumoniae (pneumokok)":{"title":"Streptococcus pneumoniae","short":"De pneumokok is een grampositieve diplokok met een kapsel; de belangrijkste verwekker van pneumonie, otitis media en bacteriële meningitis.","definition":"<p><strong><em>Streptococcus pneumoniae</em></strong> (pneumokok) is een grampositieve, lancetvormige diplokok die α-hemolyse geeft op bloedagar. Het polysacharidekapsel is de belangrijkste virulentiefactor: het beschermt tegen fagocytose.</p><p>De pneumokok koloniseert de nasofarynx en is de meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie, otitis media, sinusitis en bacteriële meningitis bij volwassenen. Kinderen en ouderen worden ertegen gevaccineerd.</p>","image_url":"","wiki_title":"Streptococcus pneumoniae","match":"streptococcus pneumoniae (pneumokok)","option_only":true},"diabetes mellitus 2":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes mellitus 2","option_only":true},"hoge koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"hoge koorts","option_only":true},"haemofilus influenzae type b":{"title":"Haemophilus influenzae","short":"H. influenzae is een kleine gramnegatieve staaf die luchtweginfecties, otitis en (vroeger vaak) meningitis en epiglottitis bij kinderen veroorzaakt.","definition":"<p><strong><em>Haemophilus influenzae</em></strong> is een kleine, gramnegatieve coccobacil. Ondanks de naam veroorzaakt hij geen influenza (dat is een virus).</p><p>Onomkapselde stammen veroorzaken otitis media, sinusitis en exacerbaties van COPD. Het omkapselde type b (Hib) veroorzaakte vroeger veel meningitis en epiglottitis bij jonge kinderen; sinds de Hib-vaccinatie is dat zeldzaam.</p>","image_url":"","wiki_title":"Haemophilus influenzae","match":"haemofilus influenzae type b","option_only":true},"haemophilus influenzae type b":{"title":"Haemophilus influenzae","short":"H. influenzae is een kleine gramnegatieve staaf die luchtweginfecties, otitis en (vroeger vaak) meningitis en epiglottitis bij kinderen veroorzaakt.","definition":"<p><strong><em>Haemophilus influenzae</em></strong> is een kleine, gramnegatieve coccobacil. Ondanks de naam veroorzaakt hij geen influenza (dat is een virus).</p><p>Onomkapselde stammen veroorzaken otitis media, sinusitis en exacerbaties van COPD. Het omkapselde type b (Hib) veroorzaakte vroeger veel meningitis en epiglottitis bij jonge kinderen; sinds de Hib-vaccinatie is dat zeldzaam.</p>","image_url":"","wiki_title":"Haemophilus influenzae","match":"haemophilus influenzae type b","option_only":true},"sarcoïdose":{"title":"Sarcoïdose","short":"Sarcoïdose is een systemische aandoening van onbekende oorzaak met niet-verkazende granulomen, vooral in longen en lymfeklieren.","definition":"<p>Bij <strong>sarcoïdose</strong> zijn vaak de hilaire lymfeklieren en het longweefsel aangedaan; ook huid (erythema nodosum), ogen (uveïtis), hart en zenuwstelsel kunnen betrokken zijn. Het ACE en calcium kunnen verhoogd zijn. Het syndroom van Löfgren (koorts, erythema nodosum, hilaire klieren, enkelartritis) heeft een goede prognose.</p>","image_url":"","wiki_title":"Sarcoidosis","match":"sarcoïdose|sarcoidose|ziekte van besnier-boeck","option_only":true},"necrotiserende fasciitis":{"title":"Necrotiserende fasciitis","short":"Necrotiserende fasciitis is een snel voortschrijdende, levensbedreigende infectie van de fascie en het onderhuidse weefsel.","definition":"<p>Bij <strong>necrotiserende fasciitis</strong> (vaak groep A-streptokokken of een gemengde flora) is de pijn veel heviger dan de huid doet vermoeden; later ontstaan bullae, verkleuring, gevoelloosheid en crepitaties, met sepsis. Snelle chirurgische verwijdering van het dode weefsel en antibiotica zijn levensreddend.</p>","image_url":"","wiki_title":"Necrotizing fasciitis","match":"necrotiserende fasciitis|vleesetende bacterie","option_only":true},"koplikse vlekjes":{"title":"Koplikvlekjes","short":"Koplikvlekjes zijn kleine witte stipjes op een rode ondergrond op het wangslijmvlies, kenmerkend voor mazelen.","definition":"<p><strong>Koplikvlekjes</strong> verschijnen in de prodromale fase van mazelen, een of twee dagen vóór de huiduitslag, vaak tegenover de kiezen. Ze zijn pathognomonisch maar verdwijnen snel.</p>","image_url":"","wiki_title":"Koplik's spots","match":"koplikse vlekjes|koplikvlekjes|koplik","option_only":true},"subacute scleroserende panencefalitis":{"title":"Subacute scleroserende panencefalitis (SSPE)","short":"SSPE is een zeldzame, dodelijke late complicatie van mazelen, jaren na de infectie, door persisterend virus in het brein.","definition":"<p><strong>SSPE</strong> treedt gemiddeld 7–10 jaar na mazelen op, vooral bij infectie op zeer jonge leeftijd. Het geeft progressieve gedrags- en cognitieve achteruitgang, myoclonieën en uiteindelijk coma. Er zijn hoge antistoftiters tegen mazelen in liquor. Vaccinatie voorkomt het.</p>","image_url":"","wiki_title":"Subacute sclerosing panencephalitis","match":"subacute scleroserende panencefalitis|sspe","option_only":true},"longtuberculose":{"title":"Longtuberculose","short":"Longtuberculose is tuberculose van de longen; de vorm die besmettelijk is via hoesten.","definition":"<p>Bij een <strong>primaire infectie</strong> ontstaat meestal een kleine haard met lymfeklierbetrokkenheid (Ghon-complex), die tot rust komt (latente tbc). Bij <strong>reactivatie</strong> (verminderde afweer, ouderdom) ontstaan vooral in de longtoppen infiltraten en holtes, met langdurig hoesten, nachtzweten, gewichtsverlies en soms hemoptoë. Latente tbc kan met een tuberculinehuidtest of IGRA worden aangetoond.</p>","image_url":"","wiki_title":"Tuberculosis","match":"longtuberculose|primaire tuberculose|reactivatie van tuberculose|latente tuberculose","option_only":true},"entamoeba":{"title":"Entamoeba histolytica","short":"Entamoeba histolytica is een protozo die amoebendysenterie en leverabcessen kan veroorzaken.","definition":"<p><strong><em>Entamoeba histolytica</em></strong> wordt via cysten in besmet water of voedsel opgelopen. Invasieve infectie van het colon geeft bloederige diarree; via de v. portae kan een amoebenleverabces ontstaan. Behandeling met metronidazol, gevolgd door een middel tegen de cysten in de darm.</p>","image_url":"","wiki_title":"Entamoeba histolytica","match":"entamoeba|entamoeba histolytica","option_only":true},"laryngitis subglottica":{"title":"Laryngitis subglottica (pseudokroep)","short":"Pseudokroep is een virale ontsteking onder de stembanden bij jonge kinderen, met blafhoest, heesheid en inspiratoire stridor.","definition":"<p><strong>Pseudokroep</strong> wordt meestal veroorzaakt door para-influenzavirussen en treedt vaak ’s nachts op bij kinderen van 6 maanden tot 3 jaar. Behandeling: geruststellen en bij matig tot ernstige klachten dexamethason; bij ernstige stridor in rust adrenalinevernevelingen. Het moet onderscheiden worden van epiglottitis.</p>","image_url":"","wiki_title":"Croup","match":"laryngitis subglottica|pseudokroep|kroep","option_only":true},"epiglottitis":{"title":"Epiglottitis","short":"Epiglottitis is een levensbedreigende bacteriële ontsteking van het strotklepje, met risico op acute luchtwegafsluiting.","definition":"<p>Bij <strong>epiglottitis</strong> (vroeger vooral door <em>H. influenzae</em> type b, nu zeldzaam dankzij vaccinatie) zijn kinderen ernstig ziek, met hoge koorts, kwijlen, slikpijn, een gedempte stem en een rechtop-voorovergebogen houding. Niet in de keel kijken en het kind niet laten liggen; direct een gecontroleerde luchtwegbeveiliging en antibiotica.</p>","image_url":"","wiki_title":"Epiglottitis","match":"epiglottitis","option_only":true},"propionibacterium acnes":{"title":"Cutibacterium acnes","short":"Cutibacterium (Propionibacterium) acnes is een grampositieve staaf van de huidflora die bijdraagt aan de ontsteking bij acne.","definition":"<p><strong><em>C. acnes</em></strong> leeft in talgrijke haarfollikels en breekt talg af tot vetzuren die ontsteking bevorderen. Het speelt een rol bij acne vulgaris; behandeling met benzoylperoxide en eventueel antibiotica remt de bacterie. Het kan ook infecties van prothesen en shunts veroorzaken.</p>","image_url":"","wiki_title":"Cutibacterium acnes","match":"propionibacterium acnes|cutibacterium acnes|p. acnes","option_only":true},"auspitz fenomeen":{"title":"Auspitz-fenomeen","short":"Het Auspitz-fenomeen zijn puntvormige bloedinkjes na het wegkrabben van schilfers van een psoriasisplaque.","definition":"<p>Bij psoriasis ligt de verlengde dermale papil met verwijde capillairen vlak onder een dunne epidermis. Na het afkrabben van de schilfers (eerst het kaarsvetfenomeen, dan een glanzend vliesje) ontstaan kleine bloedingspuntjes: het <strong>teken van Auspitz</strong>.</p>","image_url":"","wiki_title":"Auspitz's sign","match":"auspitz fenomeen|auspitz-fenomeen|teken van auspitz","option_only":true},"kaarsvet fenomeen":{"title":"Kaarsvetfenomeen","short":"Het kaarsvetfenomeen is het verschijnsel dat de schilfers van psoriasis bij krabben loskomen als witte, schilferige kaarsvetachtige lagen.","definition":"<p>Het <strong>kaarsvetfenomeen</strong> is een klassiek kenmerk van psoriasis, samen met het teken van Auspitz en het köbnerfenomeen (nieuwe plaques op plaatsen van huidbeschadiging).</p>","image_url":"","wiki_title":"","match":"kaarsvet fenomeen|kaarsvetfenomeen","option_only":true},"olievlek fenomeen":{"title":"Olievlekfenomeen","short":"Olievlekken zijn geelbruine verkleuringen onder de nagelplaat, een nagelafwijking bij psoriasis.","definition":"<p>Bij <strong>nagelpsoriasis</strong> komen putjes (pitting), olievlekken, onycholyse (loslaten van de nagel) en subunguale hyperkeratose voor. Nagelafwijkingen gaan vaak samen met artritis psoriatica.</p>","image_url":"","wiki_title":"","match":"olievlek fenomeen|olievlekfenomeen|olievlekken","option_only":true},"polycytemia vera":{"title":"Polycytemia vera","short":"Polycytemia vera is een myeloproliferatieve neoplasie met een overmatige aanmaak van rode bloedcellen, meestal door een JAK2-mutatie.","definition":"<p>Bij <strong>polycytemia vera</strong> zijn het hemoglobine en hematocriet verhoogd, vaak ook leukocyten en plaatjes. Klachten: hoofdpijn, roodheid, jeuk na een warm bad, splenomegalie en een verhoogd risico op trombose. Secundaire polycytemie (bijv. door hypoxie bij COPD of EPO-producerende tumoren) heeft een verhoogd EPO. Behandeling met aderlatingen en acetylsalicylzuur.</p>","image_url":"","wiki_title":"Polycythemia vera","match":"polycytemia vera|polycytemie|polycythemie","option_only":true},"imipenem/cilastatine":{"title":"Imipenem-cilastatine","short":"Imipenem is een carbapenem met een zeer breed spectrum; cilastatine voorkomt de afbraak ervan in de nier.","definition":"<p><strong>Imipenem</strong> werkt tegen grampositieve, gramnegatieve (incl. <em>Pseudomonas</em>) en anaerobe bacteriën en is stabiel tegen ESBL. Cilastatine remt een nierenzym (dehydropeptidase) dat imipenem anders zou afbreken. Bijwerking bij hoge doses: insulten.</p>","image_url":"","wiki_title":"Imipenem/cilastatin","match":"imipenem/cilastatine|imipenem","option_only":true},"fusidinezuurcrème":{"title":"Fusidinezuur","short":"Fusidinezuur is een antibioticum tegen stafylokokken, vooral lokaal gebruikt bij impetigo.","definition":"<p><strong>Fusidinezuur</strong> remt de eiwitsynthese (elongatiefactor G). Als crème wordt het gebruikt bij beperkte impetigo en geïnfecteerd eczeem. Bij langdurig gebruik ontstaat snel resistentie.</p>","image_url":"","wiki_title":"Fusidic acid","match":"fusidinezuurcrème|fusidinezuur","option_only":true},"claritromycine":{"title":"Claritromycine","short":"Claritromycine is een macrolide-antibioticum dat de eiwitsynthese remt (50S); het werkt ook tegen atypische verwekkers.","definition":"<p><strong>Macroliden</strong> (claritromycine, azitromycine, erytromycine) binden aan het 50S-ribosoom. Ze werken tegen o.a. streptokokken, <em>Mycoplasma</em>, <em>Chlamydia</em>, <em>Legionella</em> en kinkhoest, en zitten in H. pylori-eradicatie. Bijwerkingen: maag-darmklachten, QT-verlenging; claritromycine en erytromycine remmen CYP3A4 (interacties).</p>","image_url":"","wiki_title":"Clarithromycin","match":"claritromycine|macroliden|macrolide|azitromycine|erytromycine","option_only":true},"spondylodiscitis":{"title":"Spondylodiscitis","short":"Spondylodiscitis is een infectie van een tussenwervelschijf en de aangrenzende wervellichamen.","definition":"<p><strong>Spondylodiscitis</strong> ontstaat meestal via de bloedbaan (vaak <em>S. aureus</em>, ook bij endocarditis) of na een ingreep. Klachten zijn toenemende, ook nachtelijke rugpijn, soms met koorts; neurologische uitval kan ontstaan door een epiduraal abces. Diagnose met MRI en kweken; behandeling met langdurige antibiotica.</p>","image_url":"","wiki_title":"Discitis","match":"spondylodiscitis","option_only":true},"teleangiëctastieën":{"title":"Teleangiëctasieën","short":"Teleangiëctasieën zijn blijvend verwijde kleine bloedvaatjes in huid of slijmvlies.","definition":"<p><strong>Teleangiëctasieën</strong> komen voor bij zonbeschadigde huid, rosacea, langdurig gebruik van sterke corticosteroïdcrèmes, systemische sclerose (CREST), leverziekte (spider naevi) en de ziekte van Rendu-Osler-Weber (met bloedingen uit neus en darm).</p>","image_url":"","wiki_title":"Telangiectasia","match":"teleangiëctastieën|teleangiectasieën|teleangiëctasieën|spinnennevi","option_only":true},"episcleritis":{"title":"Episcleritis","short":"Episcleritis is een milde, meestal onschuldige ontsteking van de laag tussen bindvlies en sclera, met een lokaal rood oog.","definition":"<p>Bij <strong>episcleritis</strong> is een sectorvormig deel van het oog rood, met weinig pijn en normaal zicht. Het verdwijnt meestal vanzelf. Het onderscheid met scleritis (hevige, borende pijn; vaak bij systemische ziekten zoals reumatoïde artritis) is belangrijk.</p>","image_url":"","wiki_title":"Episcleritis","match":"episcleritis","option_only":true},"orale candida-infectie":{"title":"Orale candidiasis (spruw)","short":"Orale candidiasis (spruw) is een gistinfectie van het mondslijmvlies met witte, afschraapbare plaques.","definition":"<p><strong>Spruw</strong> komt voor bij zuigelingen, ouderen met een gebitsprothese, na antibiotica, bij inhalatiecorticosteroïden (mond spoelen na gebruik) en bij verminderde afweer (diabetes, hiv). Behandeling met lokale antimycotica (nystatine, miconazol). Recidiverende of uitgebreide spruw bij volwassenen vraagt om onderzoek naar immuunsuppressie.</p>","image_url":"","wiki_title":"Oral candidiasis","match":"orale candida-infectie|orale candidiasis|spruw|chronische mucocutane candidiasis","option_only":true},"syndroom van behçet":{"title":"Ziekte van Behçet","short":"De ziekte van Behçet is een vasculitis van vaten van alle groottes met recidiverende mond- en genitale ulcera, uveïtis en huidafwijkingen.","definition":"<p>De <strong>ziekte van Behçet</strong> komt vooral voor bij mensen uit landen langs de oude zijderoute (Turkije, Midden-Oosten) en is geassocieerd met HLA-B51. Kenmerken: pijnlijke aften in mond en genitaal, uveïtis, erythema nodosum, een positieve pathergietest, artritis en soms trombose of neurologische betrokkenheid.</p>","image_url":"","wiki_title":"Behçet's disease","match":"syndroom van behçet|ziekte van behçet|behçet|aanwezigheid van het hla-b51 antigeen","option_only":true},"acne conglobata":{"title":"Acne conglobata","short":"Acne conglobata is een ernstige vorm van acne met diepe, samenvloeiende knobbels, abcessen en littekenvorming.","definition":"<p>Bij <strong>acne conglobata</strong> zijn er onderling verbonden noduli en cysten op gezicht, romp en billen, vaak bij jonge mannen. Het laat diepe littekens na. Behandeling meestal met isotretinoïne.</p>","image_url":"","wiki_title":"Acne conglobata","match":"acne conglobata","option_only":true},"benzoylperoxide 5% gel 1dd":{"title":"Benzoylperoxide","short":"Benzoylperoxide is een lokaal acnemiddel dat Cutibacterium acnes doodt en licht keratolytisch werkt.","definition":"<p><strong>Benzoylperoxide</strong> geeft zuurstofradicalen af die bacteriën doden, zonder dat resistentie ontstaat. Het wordt vaak gecombineerd met een lokaal retinoïd of antibioticum. Bijwerkingen: irritatie en droge huid; het kan textiel en haar bleken.</p>","image_url":"","wiki_title":"Benzoyl peroxide","match":"benzoylperoxide 5% gel 1dd|benzoylperoxide","option_only":true},"cyclofosfamide":{"title":"Cyclofosfamide","short":"Cyclofosfamide is een alkylerend cytostaticum en immunosuppressivum, gebruikt bij kanker en ernstige vasculitis of lupusnefritis.","definition":"<p><strong>Cyclofosfamide</strong> wordt in de lever geactiveerd en vormt verbindingen in het DNA. Bijwerkingen: beenmergsuppressie, hemorragische cystitis (door acroleïne; preventie met mesna en ruim drinken), onvruchtbaarheid en een verhoogd risico op blaaskanker en leukemie.</p>","image_url":"","wiki_title":"Cyclophosphamide","match":"cyclofosfamide","option_only":true},"tramadol":{"title":"Tramadol","short":"Tramadol is een zwak opioïd dat ook de heropname van serotonine en noradrenaline remt.","definition":"<p><strong>Tramadol</strong> wordt gebruikt bij matige pijn. Het werkt deels via een actieve metaboliet (gevormd door CYP2D6), waardoor het effect per persoon verschilt. Bijwerkingen: misselijkheid, duizeligheid, obstipatie, verlaging van de insultdrempel, hyponatriëmie en serotoninesyndroom met andere serotonerge middelen.</p>","image_url":"","wiki_title":"Tramadol","match":"tramadol","option_only":true},"optochine":{"title":"Optochinetest","short":"De optochinetest onderscheidt Streptococcus pneumoniae (gevoelig) van andere alfa-hemolytische (viridans) streptokokken (resistent).","definition":"<p>Bij de <strong>optochinetest</strong> wordt een schijfje met optochine op een kweek gelegd; rond het schijfje ontstaat bij pneumokokken een remmingszone. Andere kenmerken van de pneumokok zijn galoplosbaarheid en een kapsel.</p>","image_url":"","wiki_title":"Optochin","match":"optochine|optochinetest","option_only":true},"oxidase":{"title":"Oxidasetest","short":"De oxidasetest toont aan of een bacterie cytochroom-c-oxidase heeft; het helpt gramnegatieve bacteriën te onderscheiden.","definition":"<p><strong>Oxidase-positief</strong> zijn bijvoorbeeld <em>Pseudomonas</em>, <em>Neisseria</em>, <em>Vibrio</em> en <em>Campylobacter</em>; de <em>Enterobacteriaceae</em> (zoals <em>E. coli</em>, <em>Klebsiella</em>, <em>Salmonella</em>) zijn oxidase-negatief.</p>","image_url":"","wiki_title":"Oxidase test","match":"oxidase|oxidasetest","option_only":true},"kapsel":{"title":"Bacterieel kapsel","short":"Een kapsel is een slijmerige laag (meestal polysacharide) om sommige bacteriën die beschermt tegen fagocytose en complement.","definition":"<p>Gekapselde bacteriën zijn o.a. pneumokokken, meningokokken, <em>H. influenzae</em> type b, <em>Klebsiella</em> en <em>Cryptococcus</em> (een gist). Antistoffen tegen het kapsel maken opsonisatie mogelijk; daarop zijn vaccins gericht (vaak geconjugeerd aan een eiwit om ook bij jonge kinderen te werken). Na splenectomie is het risico op ernstige infecties met gekapselde bacteriën verhoogd.</p>","image_url":"","wiki_title":"Bacterial capsule","match":"kapsel|polysaccharide kapsel|polysaccharidekapsel|kapselantigeen","option_only":true},"valaciclovir":{"title":"Valaciclovir","short":"Valaciclovir is een prodrug van aciclovir: een antiviraal middel tegen herpes simplex en varicella-zoster.","definition":"<p><strong>Aciclovir</strong> wordt in geïnfecteerde cellen door het virale thymidinekinase geactiveerd en remt dan het virale DNA-polymerase. Valaciclovir wordt beter opgenomen en hoeft minder vaak te worden ingenomen. Gebruik bij herpes zoster, genitale herpes en (intraveneus aciclovir) herpesencefalitis. Bij hoge doses kan nierschade optreden.</p>","image_url":"","wiki_title":"Valaciclovir","match":"valaciclovir|aciclovir","option_only":true},"cotrimoxazol":{"title":"Co-trimoxazol","short":"Co-trimoxazol combineert trimethoprim en sulfamethoxazol, die samen de foliumzuursynthese van bacteriën blokkeren.","definition":"<p><strong>Co-trimoxazol</strong> wordt gebruikt bij urineweginfecties, ter behandeling en preventie van <em>Pneumocystis</em>-pneumonie en bij enkele andere infecties. Bijwerkingen: huiduitslag (tot Stevens-Johnson), beenmergsuppressie, hyperkaliëmie en een stijging van het creatinine (minder tubulaire secretie).</p>","image_url":"","wiki_title":"Trimethoprim/sulfamethoxazole","match":"cotrimoxazol|co-trimoxazol|trimethoprim-sulfamethoxazol","option_only":true},"juveniele idiopathische artritis":{"title":"Juveniele idiopathische artritis (JIA)","short":"JIA is een chronische artritis die vóór het 16e jaar begint en langer dan zes weken duurt, zonder andere oorzaak.","definition":"<p><strong>JIA</strong> heeft verschillende vormen: oligoarticulair (vaak jonge meisjes, met risico op stille uveïtis anterior, daarom regelmatige oogcontrole), polyarticulair, systemisch (ziekte van Still), enthesitis-gerelateerd en psoriatisch. Behandeling met NSAID's, gewrichtsinjecties, methotrexaat en biologicals.</p>","image_url":"","wiki_title":"Juvenile idiopathic arthritis","match":"juveniele idiopathische artritis|jia|jeugdreuma","option_only":true},"artritis psoriatica":{"title":"Artritis psoriatica","short":"Artritis psoriatica is een gewrichtsontsteking bij psoriasis, met o.a. DIP-artritis, dactylitis, enthesitis en nagelafwijkingen.","definition":"<p><strong>Artritis psoriatica</strong> kan zich uiten als oligoartritis, polyartritis (lijkend op RA), DIP-artritis, axiale betrokkenheid of het zeldzame arthritis mutilans. Typisch zijn worstvingers (dactylitis), enthesitis en nagelpsoriasis. Reumafactor is meestal negatief.</p>","image_url":"","wiki_title":"Psoriatic arthritis","match":"artritis psoriatica|arthritis psoriatica","option_only":true},"clostridium perfringens":{"title":"Clostridium perfringens","short":"Clostridium perfringens is een anaerobe, sporenvormende staaf die voedselvergiftiging en gasgangreen kan veroorzaken.","definition":"<p><strong><em>C. perfringens</em></strong> komt voor in de bodem en de darm. Het alfatoxine veroorzaakt bij diepe, vuile wonden een snel verlopende myonecrose met gasvorming (crepitaties) en shock; behandeling met chirurgie en penicilline. Via langzaam afgekoelde vleesgerechten geeft het een milde voedselvergiftiging met diarree.</p>","image_url":"","wiki_title":"Clostridium perfringens","match":"clostridium perfringens|gasgangreen","option_only":true},"shigella spp":{"title":"Shigella","short":"Shigella is een gramnegatieve staaf die al bij een zeer kleine infectiedosis bloederige diarree (bacillaire dysenterie) veroorzaakt.","definition":"<p><strong>Shigella</strong> dringt het colonepitheel binnen en verspreidt zich van cel tot cel, met ulceraties, koorts, buikkrampen en bloederig-slijmerige diarree. <em>S. dysenteriae</em> type 1 maakt shigatoxine (risico op HUS). Overdracht fecaal-oraal, ook seksueel. Behandeling met antibiotica bij ernstige gevallen.</p>","image_url":"","wiki_title":"Shigellosis","match":"shigella spp|shigella|shigellose|bacillaire dysenterie|shigella dysenteriae","option_only":true},"cd4+-lymfocyten":{"title":"CD4+ T-helpercellen","short":"CD4+ T-helpercellen sturen de afweer via cytokines; hiv infecteert deze cellen en het CD4-getal is de belangrijkste maat voor de afweer bij hiv.","definition":"<p><strong>T-helpercellen</strong> herkennen antigeen op MHC klasse II en differentiëren tot o.a. Th1, Th2, Th17, Tfh en regulatoire T-cellen. Ze activeren macrofagen, helpen B-cellen bij antistofproductie en ondersteunen cytotoxische T-cellen. Bij een CD4-getal onder ongeveer 200 per µl ontstaan opportunistische infecties zoals <em>Pneumocystis</em>-pneumonie.</p>","image_url":"","wiki_title":"T helper cell","match":"cd4+-lymfocyten|cd4+ t-cellen|t-helpercellen|cd4-cellen","option_only":true},"av-block":{"title":"AV-blok","short":"Een AV-blok is een vertraagde of geblokkeerde geleiding van de prikkel van de boezems naar de kamers.","definition":"<p>Bij een <strong>eerstegraads AV-blok</strong> is het PR-interval verlengd. Bij een <strong>tweedegraads</strong> blok vallen sommige QRS-complexen weg (Wenckebach: geleidelijke PR-verlenging; Mobitz II: plotseling, gevaarlijker). Bij een <strong>derdegraads</strong> (totaal) blok kloppen boezems en kamers onafhankelijk, met een traag escaperitme. Oorzaken: degeneratie, ischemie, medicatie, ziekte van Lyme, sarcoïdose, aangeboren (maternale anti-SSA).</p>","image_url":"","wiki_title":"Atrioventricular block","match":"av-block|av-blok|atrioventriculair blok|atrioventriculaire geleidingsstoornissen|atroventriculaire geleidingsstoornissen","option_only":true},"atopische constitutie":{"title":"Atopische constitutie","short":"Atopie is een erfelijke aanleg om IgE te maken tegen alledaagse allergenen, met een verhoogde kans op eczeem, astma en hooikoorts.","definition":"<p>Bij een <strong>atopische constitutie</strong> komen constitutioneel eczeem, voedselallergie, allergisch astma en allergische rhinitis vaak in een volgorde voor (de ‘atopische mars’). De aanleg kan worden aangetoond met specifiek IgE of huidpriktesten.</p>","image_url":"","wiki_title":"Atopy","match":"atopische constitutie|atopie|atopisch","option_only":true},"hla-b27":{"title":"HLA-B27","short":"HLA-B27 is een MHC klasse I-variant die sterk geassocieerd is met spondyloartritiden zoals de ziekte van Bechterew.","definition":"<p>Dragers van <strong>HLA-B27</strong> hebben een sterk verhoogd risico op axiale spondyloartritis, reactieve artritis, uveïtis anterior en artritis bij IBD of psoriasis. Toch krijgt de grote meerderheid van de dragers nooit een van deze ziekten, en een deel van de patiënten is HLA-B27-negatief: de test ondersteunt de diagnose, maar bewijst haar niet.</p>","image_url":"","wiki_title":"HLA-B27","match":"hla-b27|hla b27|aanwezigheid van hla b27 antigeen","option_only":true},"acuut reuma (engels: rheumatic fever)":{"title":"Acuut reuma","short":"Acuut reuma is een ontstekingsziekte enkele weken na een keelinfectie met groep A-streptokokken, door kruisreactie van antistoffen.","definition":"<p><strong>Acuut reuma</strong> geeft volgens de Jones-criteria o.a. carditis, een migrerende polyartritis, chorea van Sydenham, erythema marginatum en subcutane noduli. De carditis kan leiden tot chronische reumatische klepziekte, vooral van de mitralisklep. Het is in Nederland zeldzaam geworden, maar wereldwijd nog een belangrijke oorzaak van hartziekte.</p>","image_url":"","wiki_title":"Rheumatic fever","match":"acuut reuma (engels: rheumatic fever)|acuut reuma|rheumatic fever","option_only":true},"diffuse intravasale stolling (dis)":{"title":"Diffuse intravasale stolling (DIS)","short":"Bij DIS wordt de stolling in het hele lichaam ontregeld geactiveerd, met microtrombi én bloedingen door verbruik van stollingsfactoren en plaatjes.","definition":"<p><strong>DIS</strong> ontstaat bij o.a. sepsis, trauma, obstetrische complicaties (placentaloslating, vruchtwaterembolie), acute promyelocytenleukemie en uitgebreide tumoren. Kenmerken: daling van plaatjes en fibrinogeen, verlengde PT/APTT en sterk verhoogde D-dimeer, met orgaanschade en bloedingen. Behandeling van de oorzaak staat centraal.</p>","image_url":"","wiki_title":"Disseminated intravascular coagulation","match":"diffuse intravasale stolling (dis)|diffuse intravasale stolling|dis|dic","option_only":true},"chronische veneuze insufficiëntie":{"title":"Chronische veneuze insufficiëntie","short":"Bij chronische veneuze insufficiëntie werkt de veneuze terugstroom uit de benen slecht, met oedeem, huidverkleuring en uiteindelijk ulcera.","definition":"<p>Door lekkende kleppen of een doorgemaakte trombose (posttrombotisch syndroom) stijgt de veneuze druk in de benen. Gevolgen: varices, oedeem, hyperpigmentatie (hemosiderine), eczeem, lipodermatosclerose, atrophie blanche en een ulcus cruris venosum, typisch rond de mediale enkel. Behandeling met compressietherapie.</p>","image_url":"","wiki_title":"Chronic venous insufficiency","match":"chronische veneuze insufficiëntie|veneuze insufficiëntie","option_only":true},"de ziekte van kawasaki":{"title":"Ziekte van Kawasaki","short":"De ziekte van Kawasaki is een vasculitis bij jonge kinderen met langdurige koorts; de belangrijkste complicatie zijn coronaire aneurysmata.","definition":"<p>De <strong>ziekte van Kawasaki</strong> treft vooral kinderen onder de 5 jaar. Kenmerken: koorts van minstens vijf dagen met conjunctivitis zonder pus, veranderingen van lippen en mondslijmvlies (aardbeientong), huiduitslag, roodheid en zwelling van handen en voeten (later vervellen) en een vergrote halsklier. Behandeling met intraveneuze immunoglobulinen en acetylsalicylzuur verkleint de kans op coronaire aneurysmata.</p>","image_url":"","wiki_title":"Kawasaki disease","match":"de ziekte van kawasaki","option_only":true},"syndroom van kawasaki":{"title":"Ziekte van Kawasaki","short":"De ziekte van Kawasaki is een vasculitis bij jonge kinderen met langdurige koorts; de belangrijkste complicatie zijn coronaire aneurysmata.","definition":"<p>De <strong>ziekte van Kawasaki</strong> treft vooral kinderen onder de 5 jaar. Kenmerken: koorts van minstens vijf dagen met conjunctivitis zonder pus, veranderingen van lippen en mondslijmvlies (aardbeientong), huiduitslag, roodheid en zwelling van handen en voeten (later vervellen) en een vergrote halsklier. Behandeling met intraveneuze immunoglobulinen en acetylsalicylzuur verkleint de kans op coronaire aneurysmata.</p>","image_url":"","wiki_title":"Kawasaki disease","match":"syndroom van kawasaki","option_only":true},"polyarteritis nodosa (pan)":{"title":"Polyarteriitis nodosa","short":"Polyarteriitis nodosa is een necrotiserende vasculitis van middelgrote arteriën, zonder ANCA en zonder glomerulonefritis.","definition":"<p>Bij <strong>polyarteriitis nodosa</strong> raken middelgrote spierarteriën ontstoken, met microaneurysmata en infarcten in o.a. nieren (hypertensie), darm (buikpijn), huid (livedo, ulcera) en zenuwen (mononeuritis multiplex). Een deel van de gevallen hangt samen met hepatitis B. De longen zijn meestal niet aangedaan.</p>","image_url":"","wiki_title":"Polyarteritis nodosa","match":"polyarteritis nodosa (pan)","option_only":true},"een myocardinfarct":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"een myocardinfarct","option_only":true},"doorgemaakt mi":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"doorgemaakt mi","option_only":true},"myocardinfarcering":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"myocardinfarcering","option_only":true},"reumatoide artritis":{"title":"Reumatoïde artritis","short":"Reumatoïde artritis is een chronische auto-immuunziekte met symmetrische ontsteking van vooral de kleine gewrichten van handen en voeten.","definition":"<p>Bij <strong>reumatoïde artritis</strong> leidt synovitis tot pannusvorming en erosie van kraakbeen en bot. Kenmerken: symmetrische polyartritis van MCP-, PIP- en MTP-gewrichten, ochtendstijfheid langer dan een uur, reumafactor en anti-CCP-antistoffen. Extra-articulair: reumanoduli, longaandoeningen, vasculitis. Vroege behandeling met DMARD's (zoals methotrexaat) voorkomt gewrichtsschade.</p>","image_url":"","wiki_title":"Rheumatoid arthritis","match":"reumatoide artritis","option_only":true},"bacteriële endocarditis met s. aureus":{"title":"Endocarditis","short":"Endocarditis is een infectie van het endocard, meestal van de hartkleppen, met vegetaties, koorts en een nieuw hartgeruis.","definition":"<p>Bij <strong>infectieuze endocarditis</strong> nestelen bacteriën (vaak <em>S. aureus</em>, streptokokken of enterokokken) zich op de hartkleppen en vormen vegetaties van bloedplaatjes, fibrine en micro-organismen.</p><p>Risicofactoren zijn klepafwijkingen, kunstkleppen en intraveneus drugsgebruik. Symptomen: koorts, een nieuw souffle en embolische verschijnselen (splinterbloedingen, Janewaylaesies, Oslernoduli, Rothvlekken). Diagnose via herhaalde bloedkweken en echocardiografie (Duke-criteria).</p>","image_url":"","wiki_title":"Infective endocarditis","match":"bacteriële endocarditis met s. aureus","option_only":true},"endocarditis lenta":{"title":"Endocarditis","short":"Endocarditis is een infectie van het endocard, meestal van de hartkleppen, met vegetaties, koorts en een nieuw hartgeruis.","definition":"<p>Bij <strong>infectieuze endocarditis</strong> nestelen bacteriën (vaak <em>S. aureus</em>, streptokokken of enterokokken) zich op de hartkleppen en vormen vegetaties van bloedplaatjes, fibrine en micro-organismen.</p><p>Risicofactoren zijn klepafwijkingen, kunstkleppen en intraveneus drugsgebruik. Symptomen: koorts, een nieuw souffle en embolische verschijnselen (splinterbloedingen, Janewaylaesies, Oslernoduli, Rothvlekken). Diagnose via herhaalde bloedkweken en echocardiografie (Duke-criteria).</p>","image_url":"","wiki_title":"Infective endocarditis","match":"endocarditis lenta","option_only":true},"glomerulaire filtratiesnelheid":{"title":"Nier","short":"De nieren filteren het bloed en regelen water-, zout- en zuur-base-evenwicht en bloeddruk; ook maken ze hormonen (renine, EPO, actief vitamine D).","definition":"<p>De <strong>nieren</strong> liggen retroperitoneaal aan weerszijden van de wervelkolom. De functionele eenheid is het <em>nefron</em>: glomerulus, proximale tubulus, lis van Henle, distale tubulus en verzamelbuis. Samen filteren de nieren ongeveer 180 liter per dag, waarvan meer dan 99% wordt teruggeresorbeerd.</p><p>Ze scheiden afvalstoffen (ureum, creatinine) en geneesmiddelen uit, regelen het volume en de samenstelling van de lichaamsvloeistoffen en de pH, en maken <em>renine</em> (bloeddruk), <em>erytropoëtine</em> (aanmaak van rode bloedcellen) en <em>calcitriol</em> (actief vitamine D).</p>","image_url":"","wiki_title":"Kidney","match":"glomerulaire filtratiesnelheid","option_only":true},"longontsteking door sars-cov-2":{"title":"COVID-19","short":"COVID-19 is de ziekte veroorzaakt door het coronavirus SARS-CoV-2, met klachten van verkoudheid tot ernstige pneumonie.","definition":"<p><strong>COVID-19</strong> wordt veroorzaakt door <em>SARS-CoV-2</em>, een omhuld RNA-coronavirus dat via het spike-eiwit aan de ACE2-receptor bindt. Overdracht via druppels en aerosolen.</p><p>Het klinisch beeld varieert van geen klachten of verkoudheid tot een virale pneumonie met ARDS. Verlies van reuk en smaak was een opvallend symptoom. Risicofactoren voor een ernstig beloop zijn hoge leeftijd, obesitas en comorbiditeit.</p>","image_url":"","wiki_title":"COVID-19","match":"longontsteking door sars-cov-2","option_only":true},"diclofenac":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"diclofenac","option_only":true},"erythema infectiosum":{"title":"Erythema infectiosum (vijfde ziekte)","short":"Erythema infectiosum is een kinderziekte door parvovirus B19 met felrode ‘slapwangen’ en daarna een kantachtige uitslag.","definition":"<p>Parvovirus B19 infecteert erytroïde voorlopercellen. Bij mensen met chronische hemolyse kan het een aplastische crise geven, en in de zwangerschap foetale anemie en hydrops. Bij volwassenen geeft het vaak symmetrische gewrichtsklachten.</p>","image_url":"","wiki_title":"Erythema infectiosum","match":"erythema infectiosum|vijfde ziekte|parvovirus b19|parvo b19","option_only":true},"zesde ziekte":{"title":"Zesde ziekte (exanthema subitum)","short":"De zesde ziekte is een infectie met humaan herpesvirus 6 bij jonge kinderen: eerst enkele dagen hoge koorts, daarna, als de koorts zakt, een vlekjesuitslag.","definition":"<p><strong>Exanthema subitum</strong> treft vooral kinderen van 6 maanden tot 2 jaar. Kenmerkend is dat de huiduitslag pas verschijnt nadat de koorts is verdwenen. Koortsconvulsies kunnen optreden. Het verloopt meestal onschuldig.</p>","image_url":"","wiki_title":"Roseola","match":"zesde ziekte|exanthema subitum|roseola infantum","option_only":true},"clostridium tetani":{"title":"Clostridium tetani","short":"Clostridium tetani is een anaerobe, sporenvormende bacterie uit de bodem die via wonden tetanus veroorzaakt.","definition":"<p>Het toxine van <strong><em>C. tetani</em></strong> (tetanospasmine) blokkeert in het ruggenmerg de afgifte van remmende neurotransmitters, met aanhoudende spierkrampen, kaakklem en opisthotonus. Preventie met vaccinatie en wondverzorging; bij verwondingen eventueel een booster en immunoglobuline.</p>","image_url":"","wiki_title":"Clostridium tetani","match":"clostridium tetani","option_only":true},"fibromyalgie":{"title":"Fibromyalgie","short":"Fibromyalgie is een chronisch pijnsyndroom met wijdverspreide pijn, vermoeidheid en slaapproblemen, zonder aantoonbare weefselschade.","definition":"<p>Bij <strong>fibromyalgie</strong> speelt een verhoogde pijngevoeligheid van het centrale zenuwstelsel (centrale sensitisatie) een rol. Laboratoriumonderzoek is normaal. Behandeling bestaat uit uitleg, geleidelijk opbouwen van beweging, aandacht voor slaap en stress en eventueel medicatie zoals amitriptyline of duloxetine.</p>","image_url":"","wiki_title":"Fibromyalgia","match":"fibromyalgie","option_only":true},"impetigo contagiosa":{"title":"Impetigo","short":"Impetigo (krentenbaard) is een oppervlakkige, besmettelijke bacteriële huidinfectie met honinggele korsten.","definition":"<p><strong>Impetigo</strong> wordt veroorzaakt door <em>S. aureus</em> en/of groep A-streptokokken en komt vooral bij kinderen voor, vaak rond neus en mond. Er zijn blaasjes die openbreken tot korsten. Behandeling met hygiëne en zo nodig fusidinezuurcrème of orale antibiotica.</p>","image_url":"","wiki_title":"Impetigo","match":"impetigo contagiosa|impetigo|krentenbaard","option_only":true},"cholera":{"title":"Cholera","short":"Cholera is een darminfectie met Vibrio cholerae die door een toxine enorme waterige diarree (‘rijstwaterdiarree’) veroorzaakt.","definition":"<p>Het <strong>choleratoxine</strong> activeert adenylaatcyclase in darmcellen, waardoor chloride en water massaal de darm in gaan. Zonder vochtaanvulling ontstaat binnen uren ernstige uitdroging. Orale rehydratie (ORS) of intraveneus vocht is levensreddend; antibiotica verkorten de ziekte.</p>","image_url":"","wiki_title":"Cholera","match":"cholera|vibrio cholerae","option_only":true},"zika":{"title":"Zikavirus","short":"Het zikavirus is een door muggen overgebracht flavivirus; infectie in de zwangerschap kan microcefalie bij het kind veroorzaken.","definition":"<p>Een infectie met het <strong>zikavirus</strong> verloopt meestal mild (koorts, rash, conjunctivitis, gewrichtspijn). Bij infectie tijdens de zwangerschap kan het virus de foetale hersenontwikkeling ernstig verstoren (congenitaal zikasyndroom). Ook seksuele overdracht is mogelijk; het kan het syndroom van Guillain-Barré uitlokken.</p>","image_url":"","wiki_title":"Zika virus","match":"zika|zikavirus","option_only":true},"urinekweek":{"title":"Urinekweek","short":"Bij een urinekweek wordt urine op voedingsbodems gekweekt om de verwekker van een urineweginfectie en de antibioticagevoeligheid te bepalen.","definition":"<p>Een <strong>urinekweek</strong> wordt gedaan bij gecompliceerde of recidiverende urineweginfecties, zwangeren, kinderen, mannen en bij koorts. Een goede (midstream) afname voorkomt verontreiniging met huid- of vaginaflora. De uitslag duurt meestal 1–2 dagen.</p>","image_url":"","wiki_title":"Urine culture","match":"urinekweek","option_only":true},"huidpriktesten":{"title":"Huidpriktest","short":"Bij een huidpriktest wordt een druppel allergeen in de huid geprikt om een IgE-gemedieerde allergie aan te tonen.","definition":"<p>Bij een <strong>huidpriktest</strong> ontstaat binnen 15–20 minuten een jeukende kwaddel als iemand gesensibiliseerd is. Antihistaminica moeten vooraf worden gestopt. Een positieve test betekent sensibilisatie, niet per se klinische allergie; de uitkomst moet passen bij de klachten. Alternatief is specifiek IgE in het bloed (RAST).</p>","image_url":"","wiki_title":"Skin allergy test","match":"huidpriktesten|huidpriktest|priktest","option_only":true},"laboratorium onderzoek (rast)":{"title":"Specifiek IgE (RAST)","short":"Met een RAST of specifiek-IgE-bepaling wordt in het bloed gemeten of iemand IgE-antistoffen tegen een bepaald allergeen heeft.","definition":"<p>De bepaling van <strong>specifiek IgE</strong> is een alternatief voor de huidpriktest, bijvoorbeeld bij uitgebreid eczeem of als antihistaminica niet gestopt kunnen worden. Ook hier geldt: sensibilisatie is niet hetzelfde als allergie.</p>","image_url":"","wiki_title":"Radioallergosorbent test","match":"laboratorium onderzoek (rast)|rast|specifiek ige","option_only":true},"eliminatie-provocatieproef":{"title":"Eliminatie-provocatietest","short":"Bij een eliminatie-provocatietest wordt een vermoedelijk allergeen weggelaten en daarna gecontroleerd weer toegediend, om een (voedsel)allergie te bevestigen.","definition":"<p>De <strong>dubbelblinde placebogecontroleerde voedselprovocatie</strong> is de gouden standaard voor het aantonen van een voedselallergie. Provocaties gebeuren onder medisch toezicht, omdat ernstige reacties mogelijk zijn.</p>","image_url":"","wiki_title":"Food challenge","match":"eliminatie-provocatieproef|eliminatie-provocatietest|provocatietest","option_only":true},"pleuraempyeem":{"title":"Pleura-empyeem","short":"Een pleura-empyeem is pus in de pleuraholte, meestal als complicatie van een pneumonie.","definition":"<p>Bij een <strong>empyeem</strong> ontstaan aanhoudende koorts en pijn ondanks antibiotica. De punctie toont pus of vocht met lage pH en glucose. Behandeling: drainage (eventueel met fibrinolytica of chirurgie) en antibiotica.</p>","image_url":"","wiki_title":"Pleural empyema","match":"pleuraempyeem|pleura-empyeem|empyeem","option_only":true},"leverabces":{"title":"Leverabces","short":"Een leverabces is een met pus gevulde holte in de lever, bacterieel (vaak vanuit galwegen of darm) of door amoeben.","definition":"<p>Een <strong>pyogeen leverabces</strong> ontstaat bij cholangitis, diverticulitis of appendicitis (via de v. portae). Klachten: koorts, pijn rechtsboven en een gevoelige lever. Behandeling met drainage en antibiotica. Bij een reisanamnese moet aan een amoebenabces worden gedacht.</p>","image_url":"","wiki_title":"Liver abscess","match":"leverabces|abces in de lever","option_only":true},"faryngitis":{"title":"Faryngitis","short":"Faryngitis is een ontsteking van de keel, meestal viraal, soms door groep A-streptokokken.","definition":"<p>De meeste <strong>keelontstekingen</strong> zijn viraal en gaan vanzelf over. Bij een bacteriële oorzaak (Centor-criteria: koorts, beslag, gezwollen pijnlijke halsklieren, geen hoest) kunnen antibiotica worden overwogen, vooral bij ernstige klachten of risicofactoren.</p>","image_url":"","wiki_title":"Pharyngitis","match":"faryngitis|keelontsteking","option_only":true},"coxsackievirus b":{"title":"Coxsackievirus B","short":"Coxsackievirus B is een enterovirus dat o.a. myocarditis, pericarditis, pleurodynie en meningitis kan veroorzaken.","definition":"<p><strong>Coxsackie B</strong>-virussen worden fecaal-oraal overgedragen. Naast milde koortsende ziekten veroorzaken ze myocarditis en pericarditis, pleurodynie (ziekte van Bornholm, met hevige pijn bij ademen) en virale meningitis. Bij pasgeborenen kunnen ze ernstige systemische infecties geven.</p>","image_url":"","wiki_title":"Coxsackie B virus","match":"coxsackievirus b","option_only":true},"clindamycine":{"title":"Clindamycine","short":"Clindamycine is een antibioticum (lincosamide) tegen grampositieve kokken en anaeroben; het remt ook toxineproductie.","definition":"<p><strong>Clindamycine</strong> bindt aan het 50S-ribosoom. Het wordt gebruikt bij huid- en wekedeleninfecties, botinfecties, tandheelkundige infecties en als toevoeging bij necrotiserende fasciitis en toxischeshocksyndroom. Een bekende bijwerking is <em>C. difficile</em>-colitis.</p>","image_url":"","wiki_title":"Clindamycin","match":"clindamycine","option_only":true},"ceftazidime":{"title":"Ceftazidim","short":"Ceftazidim is een derdegeneratie-cefalosporine die ook goed werkt tegen Pseudomonas.","definition":"<p><strong>Cefalosporines</strong> zijn bètalactamantibiotica die de celwandsynthese remmen. Hogere generaties werken beter tegen gramnegatieve bacteriën. Ceftriaxon wordt veel gebruikt bij meningitis en ernstige infecties; ceftazidim vooral bij <em>Pseudomonas</em>. Enterokokken en <em>Listeria</em> zijn van nature ongevoelig.</p>","image_url":"","wiki_title":"Ceftazidime","match":"ceftazidime|ceftazidim|cefalosporine|cefalosporines|ceftriaxon","option_only":true},"clavulaanzuur":{"title":"Clavulaanzuur","short":"Clavulaanzuur is een bètalactamaseremmer die, gecombineerd met amoxicilline, de afbraak van het antibioticum voorkomt.","definition":"<p><strong>Clavulaanzuur</strong> heeft zelf nauwelijks antibacteriële werking. Het bindt onomkeerbaar aan veel bètalactamasen, zodat amoxicilline ook werkt tegen bijv. <em>S. aureus</em> (geen MRSA), <em>H. influenzae</em> en anaeroben.</p>","image_url":"","wiki_title":"Clavulanic acid","match":"clavulaanzuur","option_only":true},"ergosterol":{"title":"Ergosterol","short":"Ergosterol is het sterol in de celmembraan van schimmels, het aangrijpingspunt van veel antimycotica.","definition":"<p>Schimmels gebruiken <strong>ergosterol</strong> in plaats van cholesterol. Azolen (fluconazol) en terbinafine remmen de aanmaak ervan; amfotericine B en nystatine binden eraan en maken gaten in de membraan.</p>","image_url":"","wiki_title":"Ergosterol","match":"ergosterol","option_only":true},"kraamvrouwenkoorts":{"title":"Kraamvrouwenkoorts (puerperale sepsis)","short":"Kraamvrouwenkoorts is een ernstige infectie na de bevalling, klassiek door groep A-streptokokken.","definition":"<p><strong>Puerperale sepsis</strong> ontstaat vanuit de uterus (endometritis) en kan zeer snel verlopen, met hoge koorts, buikpijn en shock. Semmelweis toonde in de 19e eeuw aan dat handhygiëne de sterfte sterk verminderde.</p>","image_url":"","wiki_title":"Puerperal fever","match":"kraamvrouwenkoorts|puerperale sepsis","option_only":true},"grote vaten-vasculitis":{"title":"Grote-vatenvasculitis","short":"Grote-vatenvasculitiden zijn ontstekingen van de aorta en haar grote takken: reuscelarteriitis en de ziekte van Takayasu.","definition":"<p>Bij <strong>reuscelarteriitis</strong> (ouderen) en de <strong>ziekte van Takayasu</strong> (jonge vrouwen) ontstaan granulomateuze ontsteking, vernauwingen en aneurysmata. Klachten: algemene malaise, claudicatio van armen, bloeddrukverschil en zwakke polsen. Behandeling met corticosteroïden.</p>","image_url":"","wiki_title":"Large-vessel vasculitis","match":"grote vaten-vasculitis|grote-vatenvasculitis","option_only":true},"cutaan lymfoom":{"title":"Cutaan T-cellymfoom (mycosis fungoides)","short":"Een cutaan lymfoom is een lymfoom dat primair in de huid ontstaat; de meest voorkomende vorm is mycosis fungoides.","definition":"<p><strong>Mycosis fungoides</strong> begint met jeukende, schilferende plekken die op eczeem of psoriasis lijken, vaak op de billen en romp, en verloopt langzaam via plaques naar tumoren. Diagnose met (herhaalde) huidbiopten.</p>","image_url":"","wiki_title":"Mycosis fungoides","match":"cutaan lymfoom|mycosis fungoides|cutaan t-cellymfoom","option_only":true},"herpes stomatitis":{"title":"Gingivostomatitis herpetica","short":"Gingivostomatitis herpetica is de primaire infectie met HSV-1 bij jonge kinderen, met pijnlijke blaasjes en zweertjes in de mond en koorts.","definition":"<p>Bij <strong>gingivostomatitis herpetica</strong> zijn er pijnlijke aften op tong, gehemelte en tandvlees, met gezwollen tandvlees, kwijlen, koorts en weigeren te drinken. Het risico op uitdroging is de belangrijkste complicatie. Vroeg gestart aciclovir kan het beloop verkorten.</p>","image_url":"","wiki_title":"Herpetic gingivostomatitis","match":"herpes stomatitis|gingivostomatitis herpetica|herpetische gingivostomatitis","option_only":true},"wondinfectie":{"title":"Wondinfectie","short":"Een wondinfectie is een infectie van een (operatie)wond, met roodheid, warmte, pijn, zwelling en eventueel pus.","definition":"<p>Postoperatieve <strong>wondinfecties</strong> worden vaak veroorzaakt door <em>S. aureus</em> of, bij darmchirurgie, door darmbacteriën. Risicofactoren zijn diabetes, obesitas, roken, lange operaties en contaminatie. Behandeling: openen en draineren, eventueel antibiotica.</p>","image_url":"","wiki_title":"Surgical site infection","match":"wondinfectie|postoperatieve wondinfectie","option_only":true},"norepinephrine":{"title":"Noradrenaline (norepinefrine)","short":"Noradrenaline is de neurotransmitter van de postganglionaire sympathische vezels en een vaatvernauwend middel bij shock.","definition":"<p><strong>Noradrenaline</strong> werkt vooral op α1-receptoren (vasoconstrictie) en β1-receptoren. Centraal komt het uit de locus coeruleus (alertheid, stemming). Als geneesmiddel is het de vasopressor van eerste keus bij septische shock.</p>","image_url":"","wiki_title":"Norepinephrine","match":"norepinephrine|noradrenaline|norepinefrine","option_only":true},"kortademigheid":{"title":"Dyspneu (kortademigheid)","short":"Dyspneu is het subjectieve gevoel van moeilijk of onvoldoende kunnen ademen.","definition":"<p><strong>Kortademigheid</strong> kan een pulmonale oorzaak hebben (astma, COPD, pneumonie, longembolie, pneumothorax), een cardiale (hartfalen, ischemie, ritmestoornissen), of samenhangen met anemie, obesitas, conditieverlies, angst of metabole acidose. Het tijdsbeloop (acuut of chronisch) en bijkomende klachten sturen de diagnostiek.</p>","image_url":"","wiki_title":"Shortness of breath","match":"kortademigheid|dyspneu|dyspnoe|benauwdheid","option_only":true},"amoxicilline/clavulaanzuur (augmentin®)":{"title":"Amoxicilline-clavulaanzuur","short":"Amoxicilline-clavulaanzuur combineert een penicilline met een bètalactamaseremmer, waardoor ook bètalactamasevormende bacteriën worden gedekt.","definition":"<p>Clavulaanzuur heeft zelf nauwelijks antibacteriële werking maar remt veel <em>bètalactamasen</em>, zodat amoxicilline niet wordt afgebroken. De combinatie werkt daardoor ook tegen o.a. <em>S. aureus</em> (geen MRSA), <em>H. influenzae</em>, <em>Moraxella</em>, veel <em>E. coli</em> en anaeroben zoals <em>Bacteroides</em>. Bijwerkingen: diarree en (zelden) cholestatische hepatitis.</p>","image_url":"","wiki_title":"Amoxicillin/clavulanic acid","match":"amoxicilline/clavulaanzuur (augmentin®)","option_only":true},"amoxicillin + clavulaanzuur (augmentin)":{"title":"Amoxicilline-clavulaanzuur","short":"Amoxicilline-clavulaanzuur combineert een penicilline met een bètalactamaseremmer, waardoor ook bètalactamasevormende bacteriën worden gedekt.","definition":"<p>Clavulaanzuur heeft zelf nauwelijks antibacteriële werking maar remt veel <em>bètalactamasen</em>, zodat amoxicilline niet wordt afgebroken. De combinatie werkt daardoor ook tegen o.a. <em>S. aureus</em> (geen MRSA), <em>H. influenzae</em>, <em>Moraxella</em>, veel <em>E. coli</em> en anaeroben zoals <em>Bacteroides</em>. Bijwerkingen: diarree en (zelden) cholestatische hepatitis.</p>","image_url":"","wiki_title":"Amoxicillin/clavulanic acid","match":"amoxicillin + clavulaanzuur (augmentin)","option_only":true},"systemische lupus erythematosis":{"title":"Systemische lupus erythematosus (SLE)","short":"SLE is een systemische auto-immuunziekte met antinucleaire antistoffen en immuuncomplexen; gewrichten, huid, nieren en bloed kunnen aangedaan zijn.","definition":"<p><strong>Systemische lupus erythematosus</strong> is een chronische auto-immuunziekte die vooral jonge vrouwen treft. Er worden antistoffen gevormd tegen kerncomponenten (ANA, anti-dsDNA, anti-Sm), die met antigenen <em>immuuncomplexen</em> vormen die neerslaan in weefsels (type III-reactie) en complement verbruiken.</p><p>Kenmerken: artralgie/artritis, vlindervormig erytheem in het gezicht, fotosensitiviteit, serositis, nefritis, cytopenieën en neurologische verschijnselen. Behandeling met o.a. hydroxychloroquine, corticosteroïden en immunosuppressiva.</p>","image_url":"","wiki_title":"Systemic lupus erythematosus","match":"systemische lupus erythematosis","option_only":true},"systemisch lupus erythematosus":{"title":"Systemische lupus erythematosus (SLE)","short":"SLE is een systemische auto-immuunziekte met antinucleaire antistoffen en immuuncomplexen; gewrichten, huid, nieren en bloed kunnen aangedaan zijn.","definition":"<p><strong>Systemische lupus erythematosus</strong> is een chronische auto-immuunziekte die vooral jonge vrouwen treft. Er worden antistoffen gevormd tegen kerncomponenten (ANA, anti-dsDNA, anti-Sm), die met antigenen <em>immuuncomplexen</em> vormen die neerslaan in weefsels (type III-reactie) en complement verbruiken.</p><p>Kenmerken: artralgie/artritis, vlindervormig erytheem in het gezicht, fotosensitiviteit, serositis, nefritis, cytopenieën en neurologische verschijnselen. Behandeling met o.a. hydroxychloroquine, corticosteroïden en immunosuppressiva.</p>","image_url":"","wiki_title":"Systemic lupus erythematosus","match":"systemisch lupus erythematosus","option_only":true},"constutitioneel eczeem":{"title":"Constitutioneel eczeem","short":"Chronisch, jeukend, atopisch eczeem met een gestoorde huidbarrière; begint meestal op de kinderleeftijd.","definition":"<p><b>Constitutioneel eczeem</b> (atopische dermatitis) is een chronische, jeukende huidontsteking die vaak al bij baby's begint.</p><p>Een gestoorde huidbarrière (o.a. door filaggrine-defect) en atopische aanleg spelen een rol. Bij kinderen zit het typisch in de elleboog- en knieplooien.</p>","image_url":"","wiki_title":"Atopic dermatitis","match":"constutitioneel eczeem","option_only":true},"listeria monocyogenes":{"title":"Listeria monocytogenes","short":"Listeria is een grampositieve staaf die via voedsel wordt opgelopen en vooral bij zwangeren, pasgeborenen, ouderen en afweergestoorden infecties geeft.","definition":"<p><strong><em>Listeria monocytogenes</em></strong> kan groeien bij koelkasttemperatuur en komt voor in rauwmelkse kaas, paté en gerookte vis. Hij groeit intracellulair en verspreidt zich van cel tot cel via actinestaarten. Infecties: meningitis en sepsis, en bij zwangeren risico op miskraam of neonatale infectie. Cefalosporines werken niet; amoxicilline wel.</p>","image_url":"","wiki_title":"Listeria monocytogenes","match":"listeria monocyogenes","option_only":true},"lyme borreliose":{"title":"Borrelia burgdorferi","short":"Borrelia burgdorferi is de spirocheet die door teken wordt overgebracht en de ziekte van Lyme veroorzaakt.","definition":"<p><strong><em>Borrelia burgdorferi</em></strong> wordt overgebracht door de schapenteek (<em>Ixodes ricinus</em>), meestal pas na een aanhechting van meer dan 24 uur. Vroege lokale infectie geeft erythema migrans; verspreiding kan leiden tot neuroborreliose, lyme-artritis, carditis (AV-blok) en huidafwijkingen (acrodermatitis). Behandeling met doxycycline of ceftriaxon.</p>","image_url":"","wiki_title":"Borrelia burgdorferi","match":"lyme borreliose","option_only":true},"cytomegalovirusinfectie":{"title":"Cytomegalovirus (CMV)","short":"CMV is een herpesvirus dat bij gezonden mild verloopt, maar gevaarlijk is bij immuungecompromitteerden en de belangrijkste congenitale virale infectie is.","definition":"<p>Het <strong>cytomegalovirus</strong> is een herpesvirus (HHV-5) dat na infectie levenslang latent aanwezig blijft. Geïnfecteerde cellen worden groot met kenmerkende ‘uilenoog’-inclusies.</p><p>Bij gezonde mensen verloopt infectie meestal ongemerkt of als een mononucleosebeeld. Bij transplantatie- en hiv-patiënten kan CMV retinitis, pneumonie en colitis veroorzaken. Congenitale CMV is de belangrijkste infectieuze oorzaak van aangeboren doofheid en ontwikkelingsachterstand.</p>","image_url":"","wiki_title":"Cytomegalovirus","match":"cytomegalovirusinfectie","option_only":true},"plasmodium falciparum malaria":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"plasmodium falciparum malaria","option_only":true},"orale candidiasis":{"title":"Orale candidiasis (spruw)","short":"Orale candidiasis (spruw) is een gistinfectie van het mondslijmvlies met witte, afschraapbare plaques.","definition":"<p><strong>Spruw</strong> komt voor bij zuigelingen, ouderen met een gebitsprothese, na antibiotica, bij inhalatiecorticosteroïden (mond spoelen na gebruik) en bij verminderde afweer (diabetes, hiv). Behandeling met lokale antimycotica (nystatine, miconazol). Recidiverende of uitgebreide spruw bij volwassenen vraagt om onderzoek naar immuunsuppressie.</p>","image_url":"","wiki_title":"Oral candidiasis","match":"orale candidiasis","option_only":true},"s. pneumoniae":{"title":"Streptococcus pneumoniae","short":"De pneumokok is een grampositieve diplokok met een kapsel; de belangrijkste verwekker van pneumonie, otitis media en bacteriële meningitis.","definition":"<p><strong><em>Streptococcus pneumoniae</em></strong> (pneumokok) is een grampositieve, lancetvormige diplokok die α-hemolyse geeft op bloedagar. Het polysacharidekapsel is de belangrijkste virulentiefactor: het beschermt tegen fagocytose.</p><p>De pneumokok koloniseert de nasofarynx en is de meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie, otitis media, sinusitis en bacteriële meningitis bij volwassenen. Kinderen en ouderen worden ertegen gevaccineerd.</p>","image_url":"","wiki_title":"Streptococcus pneumoniae","match":"s. pneumoniae","option_only":true},"s. aureus":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"s. aureus","option_only":true},"klebsiella spp":{"title":"Klebsiella pneumoniae","short":"K. pneumoniae is een gramnegatieve staaf met een dik kapsel die urineweginfecties en (ziekenhuis)pneumonie veroorzaakt.","definition":"<p><strong><em>Klebsiella pneumoniae</em></strong> is een gramnegatieve staaf uit de <em>Enterobacteriaceae</em> met een dik polysacharidekapsel, waardoor kolonies slijmerig zijn.</p><p>Hij veroorzaakt urineweginfecties, sepsis en pneumonie, vooral bij ouderen, alcoholisten en patiënten met diabetes of in het ziekenhuis. Klebsiella is berucht om antibioticaresistentie (ESBL- en carbapenemaseproducerende stammen).</p>","image_url":"","wiki_title":"Klebsiella pneumoniae","match":"klebsiella spp","option_only":true},"jicht (artritis urica)":{"title":"Jicht","short":"Jicht is een gewrichtsontsteking door neerslag van uraatkristallen bij een verhoogd urinezuur.","definition":"<p>Bij <strong>jicht</strong> slaan mononatriumuraatkristallen neer in en rond gewrichten. Een aanval begint plotseling, vaak ’s nachts, met een rood, gezwollen, zeer pijnlijk gewricht. Uitlokkers zijn alcohol, purinerijk voedsel, diuretica en uitdroging. In het gewrichtsvocht zijn naaldvormige, negatief dubbelbrekende kristallen te zien. Behandeling van een aanval met NSAID's, colchicine of corticosteroïden; preventie met allopurinol.</p>","image_url":"","wiki_title":"Gout","match":"jicht (artritis urica)","option_only":true},"vijfde ziekte":{"title":"Erythema infectiosum (vijfde ziekte)","short":"Erythema infectiosum is een kinderziekte door parvovirus B19 met felrode ‘slapwangen’ en daarna een kantachtige uitslag.","definition":"<p>Parvovirus B19 infecteert erytroïde voorlopercellen. Bij mensen met chronische hemolyse kan het een aplastische crise geven, en in de zwangerschap foetale anemie en hydrops. Bij volwassenen geeft het vaak symmetrische gewrichtsklachten.</p>","image_url":"","wiki_title":"Erythema infectiosum","match":"vijfde ziekte","option_only":true},"bacteri&euml;le conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies, met een rood oog, tranen of afscheiding en een branderig gevoel, zonder visusdaling.","definition":"<p><strong>Conjunctivitis</strong> kan viraal (vaak adenovirus, waterige afscheiding), bacterieel (purulente afscheiding) of allergisch (jeuk, beide ogen, seizoensgebonden) zijn. Het zicht is normaal en er is meestal geen echte pijn of lichtschuwheid; die passen eerder bij keratitis, uveïtis of glaucoom. Bij pasgeborenen moet aan chlamydia of gonokokken worden gedacht.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"bacteri&euml;le conjunctivitis","option_only":true},"bacteriële conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies, met een rood oog, tranen of afscheiding en een branderig gevoel, zonder visusdaling.","definition":"<p><strong>Conjunctivitis</strong> kan viraal (vaak adenovirus, waterige afscheiding), bacterieel (purulente afscheiding) of allergisch (jeuk, beide ogen, seizoensgebonden) zijn. Het zicht is normaal en er is meestal geen echte pijn of lichtschuwheid; die passen eerder bij keratitis, uveïtis of glaucoom. Bij pasgeborenen moet aan chlamydia of gonokokken worden gedacht.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"bacteriële conjunctivitis","option_only":true},"virale/banale conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies, met een rood oog, tranen of afscheiding en een branderig gevoel, zonder visusdaling.","definition":"<p><strong>Conjunctivitis</strong> kan viraal (vaak adenovirus, waterige afscheiding), bacterieel (purulente afscheiding) of allergisch (jeuk, beide ogen, seizoensgebonden) zijn. Het zicht is normaal en er is meestal geen echte pijn of lichtschuwheid; die passen eerder bij keratitis, uveïtis of glaucoom. Bij pasgeborenen moet aan chlamydia of gonokokken worden gedacht.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"virale/banale conjunctivitis","option_only":true},"bacteriële meningitis":{"title":"Meningitis","short":"Meningitis is een ontsteking van de hersenvliezen, met hoofdpijn, koorts, nekstijfheid en verminderd bewustzijn; bacteriële meningitis is een spoedgeval.","definition":"<p><strong>Meningitis</strong> is een ontsteking van de leptomeningen (pia en arachnoidea) en de liquor. Oorzaken zijn bacteriën (bij volwassenen vooral pneumokok en meningokok), virussen (vaak milder) en zelden schimmels.</p><p>Klassieke symptomen: hoofdpijn, koorts, nekstijfheid en een verlaagd bewustzijn; bij meningokokken soms petechiën. Diagnose via lumbaalpunctie (liquoronderzoek). Bacteriële meningitis vereist direct antibiotica en dexamethason.</p>","image_url":"","wiki_title":"Meningitis","match":"bacteriële meningitis","option_only":true},"methotrexaat (een immunosuppressivum)":{"title":"Methotrexaat","short":"Methotrexaat is een foliumzuurantagonist; in lage dosis een basismiddel bij reumatoïde artritis en psoriasis, in hoge dosis een cytostaticum.","definition":"<p><strong>Methotrexaat</strong> remt dihydrofolaatreductase. In lage, wekelijkse dosering werkt het ontstekingsremmend (o.a. via adenosine) en is het een hoeksteen bij reumatoïde artritis, psoriasis en IBD; foliumzuur vermindert bijwerkingen. Bijwerkingen: beenmergsuppressie, levertoxiciteit, mucositis en pneumonitis. Het is teratogeen en wordt via de nier uitgescheiden.</p>","image_url":"","wiki_title":"Methotrexate","match":"methotrexaat (een immunosuppressivum)","option_only":true},"een corticosteroïd":{"title":"Corticosteroïden","short":"Corticosteroïden zijn van cortisol afgeleide middelen met sterke ontstekingsremmende en immunosuppressieve werking.","definition":"<p>Glucocorticoïden binden aan een intracellulaire receptor en remmen de transcriptie van ontstekingsgenen (cytokines, COX-2) en de vorming van ontstekingsmediatoren. Ze worden lokaal (huid, inhalatie, injectie) en systemisch gebruikt. Bij langdurig systemisch gebruik: osteoporose, hyperglykemie, gewichtstoename, huidatrofie, infecties, spierzwakte, cataract en remming van de eigen bijnier (niet abrupt stoppen).</p>","image_url":"","wiki_title":"Corticosteroid","match":"een corticosteroïd","option_only":true},"herpes simplex type 2":{"title":"Herpes genitalis","short":"Herpes genitalis is een seksueel overdraagbare infectie met HSV-2 of HSV-1, met pijnlijke blaasjes en zweertjes in het genitale gebied.","definition":"<p>Bij <strong>herpes genitalis</strong> ontstaan na besmetting pijnlijke groepjes blaasjes die openbreken tot oppervlakkige ulcera, vaak met koorts, pijn bij het plassen en vergrote lieslymfeklieren. Het virus blijft latent in de sacrale ganglia en kan recidiveren. Een primaire infectie rond de bevalling geeft een groot risico op neonatale herpes.</p>","image_url":"","wiki_title":"Genital herpes","match":"herpes simplex type 2","option_only":true},"hpv-virus":{"title":"Humaan papillomavirus (HPV)","short":"HPV is een DNA-virus dat wratten veroorzaakt; hoog-risicotypes (o.a. 16 en 18) veroorzaken baarmoederhalskanker en andere kankers.","definition":"<p>Het <strong>humaan papillomavirus</strong> infecteert basale cellen van huid en slijmvlies. Laag-risicotypes (6, 11) geven wratten en condylomata acuminata. Hoog-risicotypes maken de eiwitten E6 en E7, die p53 en Rb uitschakelen; persisterende infectie kan leiden tot cervixcarcinoom en kankers van anus, vulva, penis en orofarynx. Er is een vaccin en een bevolkingsonderzoek met hrHPV-test.</p>","image_url":"","wiki_title":"Human papillomavirus infection","match":"hpv-virus","option_only":true},"humaan papillomavirus 16/18":{"title":"Humaan papillomavirus (HPV)","short":"HPV is een DNA-virus dat wratten veroorzaakt; hoog-risicotypes (o.a. 16 en 18) veroorzaken baarmoederhalskanker en andere kankers.","definition":"<p>Het <strong>humaan papillomavirus</strong> infecteert basale cellen van huid en slijmvlies. Laag-risicotypes (6, 11) geven wratten en condylomata acuminata. Hoog-risicotypes maken de eiwitten E6 en E7, die p53 en Rb uitschakelen; persisterende infectie kan leiden tot cervixcarcinoom en kankers van anus, vulva, penis en orofarynx. Er is een vaccin en een bevolkingsonderzoek met hrHPV-test.</p>","image_url":"","wiki_title":"Human papillomavirus infection","match":"humaan papillomavirus 16/18","option_only":true},"ebv-virus":{"title":"Epstein-Barrvirus (EBV)","short":"EBV is een herpesvirus dat B-cellen infecteert; het veroorzaakt de ziekte van Pfeiffer en is geassocieerd met enkele kankers.","definition":"<p>Het <strong>Epstein-Barrvirus</strong> wordt via speeksel overgedragen. Op jonge leeftijd verloopt infectie vaak ongemerkt; bij adolescenten geeft het vaak mononucleosis infectiosa. Het virus blijft levenslang latent in B-cellen. EBV is geassocieerd met o.a. het Burkittlymfoom, het nasofarynxcarcinoom, sommige Hodgkinlymfomen en posttransplantatie-lymfoproliferatieve ziekte.</p>","image_url":"","wiki_title":"Epstein–Barr virus","match":"ebv-virus","option_only":true},"pet scan":{"title":"PET-CT","short":"Een PET-CT combineert een metabole PET-scan (meestal met radioactief glucose, FDG) met een CT voor de anatomie.","definition":"<p>Bij <strong>FDG-PET</strong> nemen cellen met een hoge glucosestofwisseling, zoals veel tumoren en ontstekingshaarden, meer tracer op. Gecombineerd met CT kan de plaats precies worden bepaald. Het wordt gebruikt voor stadiëring en respons van o.a. lymfomen en longkanker, en bij onverklaarde koorts of vasculitis.</p>","image_url":"","wiki_title":"PET-CT","match":"pet scan","option_only":true},"diverticultis":{"title":"Diverticulitis","short":"Diverticulitis is een ontsteking van een of meer divertikels (uitstulpingen) van de dikke darm.","definition":"<p>Bij <b>diverticulitis</b> raakt een divertikel ontstoken, vermoedelijk door obstructie en microperforatie. Divertikels ontstaan vooral bij ouderen en bij vezelarme voeding. De ernst wordt ingedeeld volgens Hinchey (van lokale ontsteking tot abces en perforatie met peritonitis). Diagnose met echo of CT; ongecompliceerde gevallen worden meestal conservatief behandeld.</p>","image_url":"","wiki_title":"Diverticulitis","match":"diverticultis","option_only":true},"type 2 diabetes mellitus":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"type 2 diabetes mellitus","option_only":true},"pneumocystis jiroveci":{"title":"Pneumocystis jirovecii","short":"Pneumocystis jirovecii is een gistachtige schimmel die bij een sterk verminderde cellulaire afweer een interstitiële longontsteking veroorzaakt.","definition":"<p><strong>Pneumocystis</strong> groeit niet in standaardkweek en wordt aangetoond met PCR of zilverkleuring op sputum of BAL. Risicogroepen: hiv met laag CD4-getal, transplantatiepatiënten, langdurig hoge dosis corticosteroïden. Behandeling en profylaxe met co-trimoxazol.</p>","image_url":"","wiki_title":"Pneumocystis jirovecii","match":"pneumocystis jiroveci|pneumocystis jirovecii|pcp|pjp","option_only":true},"erythema migrans":{"title":"Erythema migrans","short":"Erythema migrans is een rode, zich langzaam uitbreidende ringvormige huiduitslag rond een tekenbeet bij een Borrelia-infectie.","definition":"<p><strong>Erythema migrans</strong> ontstaat dagen tot weken na een tekenbeet en breidt zich centrifugaal uit (vaak &gt;5 cm), soms met centrale verbleking. Het is een klinische diagnose; serologie is in dit stadium vaak nog negatief. Behandeling met doxycycline.</p>","image_url":"","wiki_title":"Erythema migrans","match":"erythema migrans","option_only":true},"colchicine":{"title":"Colchicine","short":"Colchicine remt de polymerisatie van microtubuli in neutrofielen en wordt gebruikt bij jicht, pericarditis en familiaire mediterrane koorts.","definition":"<p><strong>Colchicine</strong> vermindert de migratie en activatie van neutrofielen en remt het inflammasoom. Bij een jichtaanval werkt het het best als het vroeg wordt gestart. Bijwerkingen: diarree, misselijkheid en bij overdosering of nierfalen ernstige toxiciteit. Interacties met o.a. claritromycine.</p>","image_url":"","wiki_title":"Colchicine","match":"colchicine","option_only":true},"flagelline":{"title":"Flagelline","short":"Flagelline is het eiwit waaruit de zweepdraad (flagel) van bacteriën bestaat; TLR5 herkent het.","definition":"<p>Bacteriële <strong>flagellen</strong> maken beweging mogelijk en zijn een virulentiefactor. Het H-antigeen van Salmonella en E. coli is gebaseerd op flagelline. Eukaryote flagellen (zoals de staart van een zaadcel) zijn anders opgebouwd, uit microtubuli.</p>","image_url":"","wiki_title":"Flagellin","match":"flagelline|flagel|zweepdraad","option_only":true},"k. oxytoca":{"title":"Klebsiella oxytoca","short":"Klebsiella oxytoca is een gramnegatieve staaf die urineweg- en ziekenhuisinfecties en een antibiotica-geassocieerde hemorragische colitis kan veroorzaken.","definition":"<p><strong><em>K. oxytoca</em></strong> lijkt op <em>K. pneumoniae</em> maar is indol-positief. Na gebruik van penicillines kan het een bloederige diarree (hemorragische colitis) veroorzaken door een cytotoxine.</p>","image_url":"","wiki_title":"Klebsiella oxytoca","match":"k. oxytoca|klebsiella oxytoca","option_only":true},"rickettsia coronii":{"title":"Rickettsia conorii (boutonneuse koorts)","short":"Rickettsia conorii is een intracellulaire bacterie die door teken wordt overgebracht en boutonneuse koorts veroorzaakt, rond de Middellandse Zee.","definition":"<p><strong>Rickettsiosen</strong> geven koorts, hoofdpijn en een huiduitslag. Rickettsiae infecteren endotheelcellen. Behandeling met doxycycline.</p>","image_url":"","wiki_title":"Boutonneuse fever","match":"rickettsia coronii|rickettsia conorii|rickettsia|vlektyfus","option_only":true},"tekenencefalitisvirus":{"title":"Tekenencefalitis (TBE)","short":"Tekenencefalitis is een flavivirusinfectie die door teken wordt overgebracht en meningitis of encefalitis kan veroorzaken.","definition":"<p><strong>TBE</strong> komt voor in Midden- en Oost-Europa en sporadisch in Nederland. Na een griepachtige fase volgt bij een deel een tweede fase met meningitis, encefalitis of myelitis. Er is geen antivirale behandeling, wel een vaccin voor mensen met een verhoogd risico.</p>","image_url":"","wiki_title":"Tick-borne encephalitis","match":"tekenencefalitisvirus|tekenencefalitis|tbe","option_only":true},"bedwantsinfestatie":{"title":"Bedwantsen","short":"Bedwantsen zijn kleine insecten die ’s nachts bloed zuigen en jeukende bultjes in een rij geven.","definition":"<p><strong>Bedwantsen</strong> verstoppen zich overdag in matrassen, naden en kieren en worden vaak via bagage meegenomen. De beten zitten vaak in groepjes of rijtjes op onbedekte huid. Ze brengen geen ziekten over; bestrijding vraagt een professionele aanpak.</p>","image_url":"","wiki_title":"Bed bug","match":"bedwantsinfestatie|bedwantsen|bedwants","option_only":true},"pruritus senilis":{"title":"Pruritus senilis","short":"Pruritus senilis is jeuk bij ouderen zonder duidelijke huidziekte, vaak samenhangend met een droge huid.","definition":"<p>Bij oudere mensen wordt de huid droger en dunner, wat <strong>jeuk</strong> geeft, vooral in de winter en na veel wassen. Systemische oorzaken (cholestase, nierfalen, ijzergebrek, schildklierziekten, hematologische maligniteiten, medicatie) moeten worden overwogen. Behandeling met vette crèmes en minder zeep.</p>","image_url":"","wiki_title":"Itch","match":"pruritus senilis|ouderdomsjeuk","option_only":true},"zinkoxidesmeersel":{"title":"Zinkoxidesmeersel","short":"Zinkoxidesmeersel is een indrogend en beschermend middel voor de huid, bijvoorbeeld bij luieruitslag of nattende eczeem.","definition":"<p><strong>Zinkoxide</strong> vormt een beschermende laag, werkt licht indrogend en verzachtend. Het wordt gebruikt bij luierdermatitis, intertrigo en nattende huidafwijkingen.</p>","image_url":"","wiki_title":"Zinc oxide","match":"zinkoxidesmeersel|zinkzalf|zinkolie","option_only":true},"mupirocinecrème (bactroban®)":{"title":"Mupirocine","short":"Mupirocine is een lokaal antibioticum tegen stafylokokken en streptokokken, o.a. gebruikt bij impetigo en om MRSA-dragerschap in de neus te behandelen.","definition":"<p><strong>Mupirocine</strong> remt de bacteriële eiwitsynthese. Neuszalf wordt gebruikt voor dekolonisatie van <em>S. aureus</em> vóór bepaalde operaties en bij MRSA-dragerschap. Bij langdurig gebruik ontstaat resistentie.</p>","image_url":"","wiki_title":"Mupirocin","match":"mupirocinecrème (bactroban®)|mupirocine|bactroban","option_only":true},"flucloxacilline oraal":{"title":"Flucloxacilline","short":"Flucloxacilline is een bètalactamasestabiele penicilline voor infecties met Staphylococcus aureus.","definition":"<p><strong>Flucloxacilline</strong> wordt gebruikt bij huid- en wekedeleninfecties (impetigo, cellulitis, wondinfecties) en, intraveneus, bij ernstige <em>S. aureus</em>-infecties. Het werkt niet tegen MRSA. Een zeldzame bijwerking is cholestatische hepatitis.</p>","image_url":"","wiki_title":"Flucloxacillin","match":"flucloxacilline oraal|flucloxacilline","option_only":true},"dermatomycose":{"title":"Dermatomycose","short":"Een dermatomycose is een schimmelinfectie van huid, haren of nagels, meestal door dermatofyten.","definition":"<p>Voorbeelden zijn tinea pedis (zwemmerseczeem), tinea corporis (ringvormig met actieve schilferende rand), tinea cruris, tinea capitis en onychomycose. Diagnose met een KOH-preparaat of kweek; behandeling met lokale of orale antimycotica. Lokale corticosteroïden maskeren het beeld (tinea incognito).</p>","image_url":"","wiki_title":"Dermatophytosis","match":"dermatomycose|tinea|schimmelinfectie van de huid","option_only":true},"compressietherapie":{"title":"Compressietherapie","short":"Bij compressietherapie wordt met zwachtels of therapeutisch elastische kousen druk op het been uitgeoefend om de veneuze en lymfatische afvoer te verbeteren.","definition":"<p><strong>Compressie</strong> is de basis van de behandeling van chronische veneuze insufficiëntie, een ulcus cruris venosum, lymfoedeem en het posttrombotisch syndroom. Bij ernstig arterieel vaatlijden is het gecontra-indiceerd; daarom wordt eerst de enkel-armindex gemeten.</p>","image_url":"","wiki_title":"Compression therapy","match":"compressietherapie|steunkousen|zwachtelen","option_only":true},"exanthema":{"title":"Exantheem","short":"Een exantheem is een uitgebreide huiduitslag die plotseling ontstaat, vaak bij een virusinfectie of als geneesmiddelreactie.","definition":"<p>Een <strong>exantheem</strong> kan maculeus, papuleus, vesiculeus of petechiaal zijn. Klassieke virale exanthemen zijn mazelen, rode hond, de vijfde en zesde ziekte en waterpokken. Een maculopapuleus geneesmiddelexantheem ontstaat meestal 7–14 dagen na de start van een middel.</p>","image_url":"","wiki_title":"Exanthem","match":"exanthema|exantheem|maculopapulaire rash","option_only":true},"colloïdale infusievloeistof":{"title":"Colloïdale infusievloeistof","short":"Colloïden zijn infusievloeistoffen met grote moleculen (zoals albumine of zetmeel) die langer in de bloedbaan blijven dan kristalloïden.","definition":"<p><strong>Colloïden</strong> trekken door hun colloïd-osmotische druk vocht vast in de bloedbaan. Synthetische colloïden (HES) worden vanwege nierschade nauwelijks meer gebruikt. Kristalloïden (fysiologisch zout, gebalanceerde oplossingen) zijn meestal eerste keus.</p>","image_url":"","wiki_title":"Volume expander","match":"colloïdale infusievloeistof|colloïden|colloïd","option_only":true},"intraveneus immuunglobulines":{"title":"Intraveneuze immunoglobulinen (IVIG)","short":"IVIG is een gezuiverd IgG-preparaat uit donorplasma, gebruikt bij afweerstoornissen en als immuunmodulerende behandeling.","definition":"<p><strong>IVIG</strong> wordt gebruikt als vervanging bij antistofdeficiënties en als immunomodulatie bij o.a. de ziekte van Kawasaki, het syndroom van Guillain-Barré, ITP en myasthenie. Bijwerkingen zijn hoofdpijn, infusiereacties, nierschade en trombose.</p>","image_url":"","wiki_title":"Intravenous immunoglobulin","match":"intraveneus immuunglobulines|ivig|intraveneuze immunoglobulinen","option_only":true},"acute hiv-infectie":{"title":"Acute hiv-infectie","short":"Een acute hiv-infectie geeft 2–4 weken na besmetting vaak een griep- of Pfeifferachtig beeld met koorts, keelpijn, huiduitslag en klierzwelling.","definition":"<p>In de acute fase is de virale lading zeer hoog en is iemand erg besmettelijk, terwijl antistoftests nog negatief kunnen zijn; een combinatietest (antigeen/antistof) of PCR toont het dan aan. Direct starten met behandeling is gunstig.</p>","image_url":"","wiki_title":"HIV/AIDS","match":"acute hiv-infectie|acuut retroviraal syndroom","option_only":true},"lactaat acidose":{"title":"Lactaatacidose","short":"Lactaatacidose is een metabole acidose door ophoping van lactaat, meestal door onvoldoende zuurstof in weefsels.","definition":"<p>Een <strong>lactaatacidose</strong> ontstaat vooral bij shock, sepsis, ernstige hypoxie en ischemie (bijv. darmischemie); daarnaast bij leverfalen, metformine (zeldzaam), intoxicaties en mitochondriale ziekten. Een verhoogd lactaat is een maat voor de ernst van shock.</p>","image_url":"","wiki_title":"Lactic acidosis","match":"lactaat acidose|lactaatacidose|melkzuuracidose","option_only":true},"transpeptidase":{"title":"Transpeptidase (penicillinebindend eiwit)","short":"Transpeptidasen (penicillinebindende eiwitten) verknopen de peptideketens van peptidoglycaan; bètalactamantibiotica remmen ze.","definition":"<p>Bètalactams lijken op het D-alanyl-D-alanine-uiteinde en binden onomkeerbaar aan de <strong>transpeptidase</strong>. Bij MRSA codeert het mecA-gen voor een gewijzigd PBP (PBP2a) met lage affiniteit voor bètalactams, wat de resistentie verklaart.</p>","image_url":"","wiki_title":"Penicillin-binding proteins","match":"transpeptidase|penicillinebindend eiwit|pbp","option_only":true},"voedselvergiftiging":{"title":"Voedselvergiftiging (-infectie)","short":"Bij een voedselvergiftiging ontstaan maag-darmklachten door toxines of micro-organismen in voedsel.","definition":"<p>Bij een <strong>voedselintoxicatie</strong> zit het toxine al in het voedsel, met snel (1–6 uur) braken, bijv. door <em>S. aureus</em> of <em>Bacillus cereus</em>. Bij een <strong>voedselinfectie</strong> vermenigvuldigt het micro-organisme zich in de darm, met later (12–72 uur) diarree en koorts, bijv. <em>Salmonella</em> of <em>Campylobacter</em>.</p>","image_url":"","wiki_title":"Foodborne illness","match":"voedselvergiftiging|voedselintoxicatie|voedselinfectie","option_only":true},"serologie":{"title":"Serologie","short":"Bij serologie wordt in het bloed gezocht naar antistoffen (of antigenen) om een infectie of auto-immuunziekte aan te tonen.","definition":"<p>Bij infecties wijst specifiek <strong>IgM</strong> of een viervoudige stijging van IgG tussen twee monsters op een recente infectie; IgG alleen op een doorgemaakte infectie of vaccinatie. In het begin van een infectie kunnen antistoffen nog ontbreken (vensterperiode).</p>","image_url":"","wiki_title":"Serology","match":"serologie|serologisch onderzoek","option_only":true},"antigeentest":{"title":"Antigeentest","short":"Een antigeentest toont onderdelen (antigenen) van een micro-organisme aan, vaak als snelle test.","definition":"<p>Voorbeelden zijn de <strong>urine-antigeentest</strong> voor <em>Legionella</em> en pneumokokken, sneltests voor groep A-streptokokken en influenza, en de malariasneltest. Ze zijn snel, maar meestal minder gevoelig dan PCR.</p>","image_url":"","wiki_title":"Antigen test","match":"antigeentest|sneltest","option_only":true},"crepiteren":{"title":"Crepitaties","short":"Crepitaties zijn fijne of grove knisperende bijgeluiden bij het luisteren naar de longen, vooral tijdens de inademing.","definition":"<p><strong>Fijne crepitaties</strong> (laat-inspiratoir, ‘klittenband’) passen bij longfibrose en beginnend longoedeem; <strong>grovere</strong> bij pneumonie, longoedeem of bronchiëctasieën. Ook bij gewrichten en onderhuids (emfyseem) spreekt men van crepitaties.</p>","image_url":"","wiki_title":"Crackles","match":"crepiteren|crepitaties|crepitatie","option_only":true},"acute nierinsufficiëntie":{"title":"Nierinsufficiëntie (nierfalen)","short":"Bij nierinsufficiëntie schiet de nierfunctie tekort, met ophoping van afvalstoffen en verstoring van water-, zout- en zuurhuishouding.","definition":"<p><strong>Acuut nierfalen</strong> ontstaat binnen uren tot dagen en wordt ingedeeld in prerenaal (ondervulling), renaal (bijv. acute tubulusnecrose, glomerulonefritis) en postrenaal (obstructie). <strong>Chronische nierschade</strong> is een eGFR &lt; 60 of nierschade langer dan 3 maanden, meestal door diabetes en hypertensie. Gevolgen zijn o.a. hyperkaliëmie, metabole acidose, anemie (minder EPO), botziekte en hypertensie.</p>","image_url":"","wiki_title":"Kidney failure","match":"acute nierinsufficiëntie","option_only":true},"katalase":{"title":"Catalase","short":"Catalase is een enzym dat waterstofperoxide omzet in water en zuurstof; bacteriën met catalase (zoals stafylokokken) zijn catalasepositief.","definition":"<p><strong>Catalase</strong> breekt <em>waterstofperoxide</em> af: 2 H<sub>2</sub>O<sub>2</sub> → 2 H<sub>2</sub>O + O<sub>2</sub>. In menselijke cellen zit het vooral in de peroxisomen en beschermt het tegen oxidatieve schade.</p><p>In de microbiologie is de catalasetest een snelle manier om grampositieve kokken te onderscheiden: <em>stafylokokken</em> zijn catalasepositief (bruisen met H<sub>2</sub>O<sub>2</sub>), <em>streptokokken</em> catalasenegatief. Catalasepositieve micro-organismen zijn ook beter bestand tegen de oxidatieve burst van fagocyten.</p>","image_url":"","wiki_title":"Catalase","match":"katalase","option_only":true},"amoxycilline":{"title":"Amoxicilline","short":"Amoxicilline is een breedspectrum-penicilline die ook een deel van de gramnegatieve bacteriën dekt; veel gebruikt bij luchtweginfecties.","definition":"<p><strong>Amoxicilline</strong> is een aminopenicilline: een bètalactamantibioticum dat de celwandsynthese remt. Het spectrum is breder dan penicilline en omvat ook o.a. <em>H. influenzae</em> en <em>E. coli</em> (mits geen bètalactamase).</p><p>Het is in de huisartsenpraktijk eerste keus bij pneumonie en wordt ook gebruikt bij otitis en sinusitis. Met clavulaanzuur (amoxicilline-clavulaanzuur) is het ook werkzaam tegen bètalactamasevormers.</p>","image_url":"","wiki_title":"Amoxicillin","match":"amoxycilline","option_only":true},"amoxycilline oraal":{"title":"Amoxicilline","short":"Amoxicilline is een breedspectrum-penicilline die ook een deel van de gramnegatieve bacteriën dekt; veel gebruikt bij luchtweginfecties.","definition":"<p><strong>Amoxicilline</strong> is een aminopenicilline: een bètalactamantibioticum dat de celwandsynthese remt. Het spectrum is breder dan penicilline en omvat ook o.a. <em>H. influenzae</em> en <em>E. coli</em> (mits geen bètalactamase).</p><p>Het is in de huisartsenpraktijk eerste keus bij pneumonie en wordt ook gebruikt bij otitis en sinusitis. Met clavulaanzuur (amoxicilline-clavulaanzuur) is het ook werkzaam tegen bètalactamasevormers.</p>","image_url":"","wiki_title":"Amoxicillin","match":"amoxycilline oraal","option_only":true},"respiratoir syncytieelvirus":{"title":"Respiratoir syncytieel virus (RSV)","short":"RSV is een RNA-virus dat in de winter luchtweginfecties geeft, bij zuigelingen vaak bronchiolitis.","definition":"<p><strong>RSV</strong> geeft bij volwassenen meestal een verkoudheid, maar bij zuigelingen kan het de kleine luchtwegen aantasten, met piepen, benauwdheid en drinkproblemen. Ex-prematuren en kinderen met hart- of longafwijkingen lopen het meeste risico. Er bestaan antistoffen ter preventie (palivizumab, nirsevimab) en een vaccin voor zwangeren en ouderen.</p>","image_url":"","wiki_title":"Respiratory syncytial virus","match":"respiratoir syncytieelvirus|rsv|respiratoir syncytieel virus","option_only":true},"gele koortsvirus":{"title":"Gelekoortsvirus","short":"Het gelekoortsvirus is een flavivirus dat door Aedes-muggen wordt overgebracht; tegen gele koorts bestaat een levend verzwakt vaccin.","definition":"<p>Gele koorts komt voor in tropisch Afrika en Zuid-Amerika. Een deel van de patiënten ontwikkelt na de griepachtige fase leverfalen met icterus, bloedingen en nierfalen. Bij inreis in sommige landen is vaccinatie verplicht.</p>","image_url":"","wiki_title":"Yellow fever virus","match":"gele koortsvirus|gelekoortsvirus|gele koorts","option_only":true},"proteus mirabilis":{"title":"Proteus mirabilis","short":"Proteus mirabilis is een gramnegatieve staaf die urineweginfecties en, via urease, struvietstenen veroorzaakt.","definition":"<p>Het enzym <strong>urease</strong> zet ureum om in ammoniak, waardoor de urine alkalisch wordt en magnesium-ammoniumfosfaatstenen (koraalstenen) ontstaan. Op een kweekplaat ‘zwermt’ de bacterie. Het komt vooral voor bij gecompliceerde urineweginfecties en katheters.</p>","image_url":"","wiki_title":"Proteus mirabilis","match":"proteus mirabilis|proteus","option_only":true},"systemische lupus erythematodes (sle)":{"title":"Systemische lupus erythematosus (SLE)","short":"SLE is een systemische auto-immuunziekte met antinucleaire antistoffen en immuuncomplexen; gewrichten, huid, nieren en bloed kunnen aangedaan zijn.","definition":"<p><strong>Systemische lupus erythematosus</strong> is een chronische auto-immuunziekte die vooral jonge vrouwen treft. Er worden antistoffen gevormd tegen kerncomponenten (ANA, anti-dsDNA, anti-Sm), die met antigenen <em>immuuncomplexen</em> vormen die neerslaan in weefsels (type III-reactie) en complement verbruiken.</p><p>Kenmerken: artralgie/artritis, vlindervormig erytheem in het gezicht, fotosensitiviteit, serositis, nefritis, cytopenieën en neurologische verschijnselen. Behandeling met o.a. hydroxychloroquine, corticosteroïden en immunosuppressiva.</p>","image_url":"","wiki_title":"Systemic lupus erythematosus","match":"systemische lupus erythematodes (sle)","option_only":true},"systemische lupus erythematodes":{"title":"Systemische lupus erythematosus (SLE)","short":"SLE is een systemische auto-immuunziekte met antinucleaire antistoffen en immuuncomplexen; gewrichten, huid, nieren en bloed kunnen aangedaan zijn.","definition":"<p><strong>Systemische lupus erythematosus</strong> is een chronische auto-immuunziekte die vooral jonge vrouwen treft. Er worden antistoffen gevormd tegen kerncomponenten (ANA, anti-dsDNA, anti-Sm), die met antigenen <em>immuuncomplexen</em> vormen die neerslaan in weefsels (type III-reactie) en complement verbruiken.</p><p>Kenmerken: artralgie/artritis, vlindervormig erytheem in het gezicht, fotosensitiviteit, serositis, nefritis, cytopenieën en neurologische verschijnselen. Behandeling met o.a. hydroxychloroquine, corticosteroïden en immunosuppressiva.</p>","image_url":"","wiki_title":"Systemic lupus erythematosus","match":"systemische lupus erythematodes","option_only":true},"polymyalgia reumatica (pmr)":{"title":"Polymyalgia reumatica","short":"Polymyalgia reumatica is een ontstekingsziekte bij ouderen met pijn en stijfheid in schouder- en heupgordel.","definition":"<p><strong>Polymyalgia reumatica</strong> treft vooral mensen boven de 50, vaker vrouwen. Kenmerkend zijn ochtendstijfheid en pijn in nek, schouders en heupen, met moeite om op te staan of de armen te heffen, en een sterk verhoogde BSE/CRP. Er is geen echte spierzwakte. De ziekte reageert snel op lage dosis prednison en gaat soms samen met reuscelarteriitis.</p>","image_url":"","wiki_title":"Polymyalgia rheumatica","match":"polymyalgia reumatica (pmr)","option_only":true},"acuut myocardinfarct":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"acuut myocardinfarct","option_only":true},"hemophilus influenzae":{"title":"Haemophilus influenzae","short":"H. influenzae is een kleine gramnegatieve staaf die luchtweginfecties, otitis en (vroeger vaak) meningitis en epiglottitis bij kinderen veroorzaakt.","definition":"<p><strong><em>Haemophilus influenzae</em></strong> is een kleine, gramnegatieve coccobacil. Ondanks de naam veroorzaakt hij geen influenza (dat is een virus).</p><p>Onomkapselde stammen veroorzaken otitis media, sinusitis en exacerbaties van COPD. Het omkapselde type b (Hib) veroorzaakte vroeger veel meningitis en epiglottitis bij jonge kinderen; sinds de Hib-vaccinatie is dat zeldzaam.</p>","image_url":"","wiki_title":"Haemophilus influenzae","match":"hemophilus influenzae","option_only":true},"haemophilus influenza":{"title":"Haemophilus influenzae","short":"H. influenzae is een kleine gramnegatieve staaf die luchtweginfecties, otitis en (vroeger vaak) meningitis en epiglottitis bij kinderen veroorzaakt.","definition":"<p><strong><em>Haemophilus influenzae</em></strong> is een kleine, gramnegatieve coccobacil. Ondanks de naam veroorzaakt hij geen influenza (dat is een virus).</p><p>Onomkapselde stammen veroorzaken otitis media, sinusitis en exacerbaties van COPD. Het omkapselde type b (Hib) veroorzaakte vroeger veel meningitis en epiglottitis bij jonge kinderen; sinds de Hib-vaccinatie is dat zeldzaam.</p>","image_url":"","wiki_title":"Haemophilus influenzae","match":"haemophilus influenza","option_only":true},"corynebacterium diphtheriae (difterie)":{"title":"Difterie","short":"Difterie is een infectie door Corynebacterium diphtheriae waarbij een toxine een grijs pseudomembraan in de keel en schade aan hart en zenuwen veroorzaakt.","definition":"<p><strong>Difterie</strong> wordt veroorzaakt door toxineproducerende stammen van <em>Corynebacterium diphtheriae</em>, een grampositieve staaf. Het difterietoxine remt de eiwitsynthese van gastheercellen.</p><p>Lokaal ontstaat een grijswit, vastzittend <em>pseudomembraan</em> in keel en neus, met risico op luchtwegobstructie. Het toxine kan systemisch myocarditis en neuropathie geven. Door vaccinatie (DKTP) is het in Nederland zeldzaam.</p>","image_url":"","wiki_title":"Diphtheria","match":"corynebacterium diphtheriae (difterie)","option_only":true},"infectie met epstein-barrvirus":{"title":"Epstein-Barrvirus (EBV)","short":"EBV is een herpesvirus dat B-cellen infecteert; het veroorzaakt de ziekte van Pfeiffer en is geassocieerd met enkele kankers.","definition":"<p>Het <strong>Epstein-Barrvirus</strong> wordt via speeksel overgedragen. Op jonge leeftijd verloopt infectie vaak ongemerkt; bij adolescenten geeft het vaak mononucleosis infectiosa. Het virus blijft levenslang latent in B-cellen. EBV is geassocieerd met o.a. het Burkittlymfoom, het nasofarynxcarcinoom, sommige Hodgkinlymfomen en posttransplantatie-lymfoproliferatieve ziekte.</p>","image_url":"","wiki_title":"Epstein–Barr virus","match":"infectie met epstein-barrvirus","option_only":true},"bacteriodes fragilis":{"title":"Bacteroides fragilis","short":"Bacteroides fragilis is een gramnegatieve anaerobe staaf uit de darmflora en een belangrijke verwekker van buikabcessen.","definition":"<p><strong><em>Bacteroides fragilis</em></strong> is een van de talrijkste anaeroben in het colon. Bij perforatie of darmchirurgie kan hij in de buikholte terechtkomen en (met andere bacteriën) abcessen en peritonitis veroorzaken; het kapsel bevordert abcesvorming. Hij maakt vaak bètalactamase; metronidazol, amoxicilline-clavulaanzuur en carbapenems werken wel.</p>","image_url":"","wiki_title":"Bacteroides fragilis","match":"bacteriodes fragilis","option_only":true},"rotavirus infectie":{"title":"Rotavirus","short":"Rotavirus is een dubbelstrengs RNA-virus dat bij jonge kinderen een ernstige gastro-enteritis met braken en waterige diarree veroorzaakt.","definition":"<p><strong>Rotavirus</strong> wordt fecaal-oraal overgedragen en beschadigt de villi van de dunne darm. Vooral kinderen onder de 2 jaar krijgen koorts, braken en waterige diarree, met risico op uitdroging. Er bestaat een oraal levend vaccin, inmiddels opgenomen in het Rijksvaccinatieprogramma.</p>","image_url":"","wiki_title":"Rotavirus","match":"rotavirus infectie","option_only":true},"rhinovirusinfectie":{"title":"Rhinovirus","short":"Rhinovirussen zijn de belangrijkste verwekkers van de gewone verkoudheid.","definition":"<p><strong>Rhinovirussen</strong> zijn kleine, niet-omhulde RNA-virussen (picornavirussen) met meer dan 100 serotypes, waardoor je er steeds opnieuw verkouden van kunt worden. Ze vermenigvuldigen zich het best bij de iets lagere temperatuur in de neus. Ze kunnen ook astma- en COPD-exacerbaties uitlokken.</p>","image_url":"","wiki_title":"Rhinovirus","match":"rhinovirusinfectie","option_only":true},"jichtartritis":{"title":"Jicht","short":"Jicht is een gewrichtsontsteking door neerslag van uraatkristallen bij een verhoogd urinezuur.","definition":"<p>Bij <strong>jicht</strong> slaan mononatriumuraatkristallen neer in en rond gewrichten. Een aanval begint plotseling, vaak ’s nachts, met een rood, gezwollen, zeer pijnlijk gewricht. Uitlokkers zijn alcohol, purinerijk voedsel, diuretica en uitdroging. In het gewrichtsvocht zijn naaldvormige, negatief dubbelbrekende kristallen te zien. Behandeling van een aanval met NSAID's, colchicine of corticosteroïden; preventie met allopurinol.</p>","image_url":"","wiki_title":"Gout","match":"jichtartritis","option_only":true},"infectieuze artritis":{"title":"Septische artritis","short":"Septische artritis is een bacteriële infectie van een gewricht (vaak S. aureus): acuut, pijnlijk, gezwollen, warm gewricht met koorts; een spoedgeval.","definition":"<p>Bij <strong>septische artritis</strong> raakt een gewricht geïnfecteerd, meestal via de bloedbaan, soms na een punctie of operatie. De meest voorkomende verwekker is <em>Staphylococcus aureus</em>; bij seksueel actieve jongvolwassenen ook <em>Neisseria gonorrhoeae</em>.</p><p>Het geeft een acuut rood, warm, gezwollen en zeer pijnlijk gewricht (vaak de knie) met bewegingsbeperking en meestal koorts. Diagnose door punctie (troebel synoviaal vocht met veel leukocyten, kweek). Snel draineren en antibiotica zijn nodig om kraakbeenvernietiging te voorkomen.</p>","image_url":"","wiki_title":"Septic arthritis","match":"infectieuze artritis","option_only":true},"suppuratieve artritis":{"title":"Septische artritis","short":"Septische artritis is een bacteriële infectie van een gewricht (vaak S. aureus): acuut, pijnlijk, gezwollen, warm gewricht met koorts; een spoedgeval.","definition":"<p>Bij <strong>septische artritis</strong> raakt een gewricht geïnfecteerd, meestal via de bloedbaan, soms na een punctie of operatie. De meest voorkomende verwekker is <em>Staphylococcus aureus</em>; bij seksueel actieve jongvolwassenen ook <em>Neisseria gonorrhoeae</em>.</p><p>Het geeft een acuut rood, warm, gezwollen en zeer pijnlijk gewricht (vaak de knie) met bewegingsbeperking en meestal koorts. Diagnose door punctie (troebel synoviaal vocht met veel leukocyten, kweek). Snel draineren en antibiotica zijn nodig om kraakbeenvernietiging te voorkomen.</p>","image_url":"","wiki_title":"Septic arthritis","match":"suppuratieve artritis","option_only":true},"lichttherapie":{"title":"Lichttherapie","short":"Lichttherapie gebruikt licht ter behandeling: UV-licht bij huidziekten of fel licht bij winterdepressie en slaapritmestoornissen.","definition":"<p>Bij <strong>huidziekten</strong> (psoriasis, eczeem, vitiligo) wordt smalspectrum-UVB of PUVA gebruikt, met op lange termijn een verhoogd risico op huidkanker. Bij een <strong>seizoensgebonden depressie</strong> helpt dagelijkse blootstelling aan fel licht in de ochtend.</p>","image_url":"","wiki_title":"Light therapy","match":"lichttherapie|uvb-therapie|smalspectrum uvb fototherapie","option_only":true},"q-koorts (coxiella burnetii)":{"title":"Q-koorts (Coxiella burnetii)","short":"Q-koorts is een zoönose door Coxiella burnetii, verspreid via stof van besmette geiten en schapen.","definition":"<p><strong>Q-koorts</strong> geeft vaak een griepachtig beeld, pneumonie of hepatitis; chronische Q-koorts kan endocarditis en vaatinfecties geven, vooral bij klepafwijkingen of vaatprothesen. In 2007–2010 was er in Nederland een grote epidemie rond geitenhouderijen. Behandeling met doxycycline.</p>","image_url":"","wiki_title":"Q fever","match":"q-koorts (coxiella burnetii)|q-koorts|coxiella burnetii","option_only":true},"dithranol":{"title":"Dithranol","short":"Dithranol is een oud, effectief lokaal middel tegen psoriasis, dat de deling van keratinocyten remt.","definition":"<p><strong>Dithranol</strong> wordt vaak als korte contacttherapie gebruikt. Het kan de huid irriteren en verkleurt huid, kleding en badkamer tijdelijk paarsbruin.</p>","image_url":"","wiki_title":"Dithranol","match":"dithranol","option_only":true},"furunculosis":{"title":"Furunkel","short":"Een furunkel (steenpuist) is een diepe infectie van een haarfollikel door S. aureus; een karbunkel is een samenvloeiing van meerdere furunkels.","definition":"<p>Een <strong>furunkel</strong> is een pijnlijke, rode knobbel die abcedeert. Bij recidiverende furunkels wordt gedacht aan dragerschap van <em>S. aureus</em> (eventueel PVL-producerend), diabetes en slechte hygiëne; dekolonisatie kan helpen.</p>","image_url":"","wiki_title":"Boil","match":"furunculosis|furunkel|furunkels|karbunkel|recidiverende furunkels (steenpuisten)","option_only":true},"prurigo":{"title":"Prurigo","short":"Prurigo is een jeukende huidaandoening met knobbeltjes die ontstaan door langdurig krabben.","definition":"<p>Bij <strong>prurigo nodularis</strong> ontstaan door een jeuk-krabcyclus harde, jeukende knobbels, vaak op de strekzijden. Het komt voor bij atopie, maar ook bij systemische oorzaken van jeuk (nierfalen, leverziekte, hematologische ziekten).</p>","image_url":"","wiki_title":"Prurigo","match":"prurigo|prurigopapels","option_only":true},"hyperhidrose":{"title":"Hyperhidrose","short":"Hyperhidrose is overmatig zweten, primair (oksels, handen, voeten) of secundair aan een ziekte of medicatie.","definition":"<p>Primaire <strong>hyperhidrose</strong> begint vaak in de jeugd en is lokaal. Secundaire, gegeneraliseerde hyperhidrose kan passen bij hyperthyreoïdie, infecties (tbc), lymfomen, menopauze, hypoglykemie of medicatie (antidepressiva). Behandeling: aluminiumchloride, botuline-injecties of iontoforese.</p>","image_url":"","wiki_title":"Hyperhidrosis","match":"hyperhidrose|overmatig zweten","option_only":true},"natalizumab":{"title":"Natalizumab","short":"Natalizumab is een antistof tegen het integrine α4, die het binnendringen van lymfocyten in het brein remt; gebruikt bij actieve MS.","definition":"<p><strong>Natalizumab</strong> is zeer effectief bij MS, maar kan bij dragers van het JC-virus progressieve multifocale leuko-encefalopathie (PML) veroorzaken; daarom wordt het risico vooraf ingeschat.</p>","image_url":"","wiki_title":"Natalizumab","match":"natalizumab","option_only":true},"anakinra":{"title":"Anakinra","short":"Anakinra is een IL-1-receptorantagonist, gebruikt bij o.a. de ziekte van Still, auto-inflammatoire syndromen en soms jicht.","definition":"<p><strong>Anakinra</strong> wordt dagelijks subcutaan gespoten en blokkeert de werking van IL-1α en IL-1β. Het wordt ook ingezet bij het macrofaagactivatiesyndroom.</p>","image_url":"","wiki_title":"Anakinra","match":"anakinra","option_only":true},"syndroom van cushing":{"title":"Syndroom van Cushing","short":"Het syndroom van Cushing is het geheel van klachten door langdurig te veel cortisol.","definition":"<p>Kenmerken van <strong>Cushing</strong>: centrale obesitas, vollemaansgezicht, buffalo hump, paarse striae, dunne huid, spierzwakte, hypertensie, diabetes, osteoporose en stemmingsklachten. De meest voorkomende oorzaak is gebruik van corticosteroïden. Endogene oorzaken: een ACTH-producerend hypofyseadenoom (ziekte van Cushing), ectopische ACTH-productie of een bijniertumor.</p>","image_url":"","wiki_title":"Cushing's syndrome","match":"syndroom van cushing|cushing|hypercortisolisme|morbus cushing|overmatig gebruik van corticosteroïden","option_only":true},"fotosensibilisatie":{"title":"Fotosensibilisatie","short":"Bij fotosensibilisatie maakt een stof de huid overgevoelig voor zonlicht, met verbranding of eczeem op aan licht blootgestelde huid.","definition":"<p>Bekende <strong>fotosensibiliserende</strong> middelen zijn doxycycline, amiodaron, thiaziden, NSAID's en sommige parfums en planten (berenklauw). Ook SLE en porfyrie gaan gepaard met lichtovergevoeligheid.</p>","image_url":"","wiki_title":"Photosensitivity","match":"fotosensibilisatie|fotosensitiviteit","option_only":true},"ototoxiciteit":{"title":"Ototoxiciteit","short":"Ototoxiciteit is beschadiging van het binnenoor door geneesmiddelen, met gehoorverlies, oorsuizen of evenwichtsstoornissen.","definition":"<p>Bekende <strong>ototoxische</strong> middelen zijn aminoglycosiden, cisplatine, lisdiuretica (vooral bij hoge doses intraveneus) en hoge doses salicylaten. Gehoorverlies door aminoglycosiden en cisplatine is vaak blijvend.</p>","image_url":"","wiki_title":"Ototoxicity","match":"ototoxiciteit|ototoxisch","option_only":true},"triple feces test (tft)":{"title":"Triple feces test","short":"De triple feces test onderzoekt drie opeenvolgende ontlastingsmonsters op darmparasieten.","definition":"<p>Met de <strong>TFT</strong> worden protozoën zoals <em>Giardia</em> en <em>Dientamoeba</em> en wormeieren opgespoord. Steeds vaker wordt PCR op ontlasting gebruikt, die gevoeliger is.</p>","image_url":"","wiki_title":"","match":"triple feces test (tft)|triple feces test|tft","option_only":true},"positieve nitriet":{"title":"Nitriettest","short":"Een positieve nitriettest in de urine wijst op een urineweginfectie met bacteriën die nitraat omzetten in nitriet, zoals E. coli.","definition":"<p>De <strong>nitriettest</strong> is specifiek maar niet erg gevoelig: enterokokken en stafylokokken maken geen nitriet, en de urine moet enige uren in de blaas hebben gezeten. Een negatieve test sluit een infectie dus niet uit.</p>","image_url":"","wiki_title":"Urinalysis","match":"positieve nitriet|nitriettest|nitriet","option_only":true},"slagpijn nierloge":{"title":"Slagpijn in de nierloge","short":"Slagpijn in de nierloge (pijn bij kloppen op de flank) wijst op een ontsteking of stuwing van de nier, zoals pyelonefritis.","definition":"<p><strong>Slagpijn</strong> wordt onderzocht door met de vuist op de hand in de flank te kloppen. Samen met koorts past het bij pyelonefritis; zonder koorts kan het ook passen bij nierstenen.</p>","image_url":"","wiki_title":"","match":"slagpijn nierloge|slagpijn","option_only":true},"tuberculostatica":{"title":"Tuberculostatica","short":"Tuberculostatica zijn middelen tegen tuberculose, die altijd in combinatie en langdurig worden gegeven om resistentie te voorkomen.","definition":"<p>De standaardbehandeling bestaat uit twee maanden <strong>isoniazide, rifampicine, pyrazinamide en ethambutol</strong>, gevolgd door vier maanden isoniazide en rifampicine. Bijwerkingen: leverschade (INH, RIF, PZA), neuropathie (INH, voorkomen met vitamine B6), oranje lichaamsvloeistoffen en veel interacties (RIF), en gezichtsstoornissen (ethambutol).</p>","image_url":"","wiki_title":"Tuberculosis treatment","match":"tuberculostatica|isoniazide|rifampicine|ethambutol|pyrazinamide","option_only":true},"intertrigineus eczeem":{"title":"Intertrigo","short":"Intertrigo is een ontsteking van de huid in plooien (liezen, onder de borsten), door wrijving, vocht en warmte, vaak met candida.","definition":"<p><strong>Intertrigo</strong> komt vaker voor bij overgewicht, diabetes en bij warm weer. Behandeling: plooien droog houden en zo nodig een antimycotische crème.</p>","image_url":"","wiki_title":"Intertrigo","match":"intertrigineus eczeem|intertrigo","option_only":true},"tetracycline":{"title":"Tetracyclines","short":"Tetracyclines remmen de bacteriële eiwitsynthese via het 30S-ribosoom; doxycycline is de bekendste.","definition":"<p><strong>Tetracyclines</strong> werken tegen veel bacteriën, inclusief intracellulaire (Chlamydia, Mycoplasma, Rickettsia, Borrelia). Ze worden ook bij acne en rosacea gebruikt. Ze binden aan calcium in tanden en botten (verkleuring), dus niet bij zwangeren en jonge kinderen, en geven fotosensibilisatie.</p>","image_url":"","wiki_title":"Tetracycline antibiotics","match":"tetracycline|tetracyclines|minocycline","option_only":true},"psoriasis inversa":{"title":"Psoriasis inversa","short":"Psoriasis inversa is psoriasis in huidplooien (liezen, oksels, bilnaad, onder de borsten), met glanzende rode plekken zonder veel schilfers.","definition":"<p>Door het vocht in de plooien ontbreken bij <strong>psoriasis inversa</strong> de typische schilfers, waardoor het op intertrigo of een schimmelinfectie kan lijken.</p>","image_url":"","wiki_title":"Inverse psoriasis","match":"psoriasis inversa","option_only":true},"asteatotisch eczeem":{"title":"Asteatotisch eczeem (eczéma craquelé)","short":"Asteatotisch eczeem ontstaat in een zeer droge huid, vooral op de onderbenen van ouderen in de winter, met een barstjespatroon.","definition":"<p>Bij <strong>asteatotisch eczeem</strong> lijkt de huid op een gebarsten ondergrond. Het verbetert met minder wassen en douchen, geen zeep en dagelijks vette crèmes.</p>","image_url":"","wiki_title":"Xerotic eczema","match":"asteatotisch eczeem|eczema craquelé","option_only":true},"eczema herpeticum":{"title":"Eczema herpeticum","short":"Eczema herpeticum is een uitgebreide herpes simplex-infectie in een eczeemhuid, met ‘uitgeponste’ erosies en koorts; een spoedgeval.","definition":"<p>Bij <strong>eczema herpeticum</strong> verspreidt HSV zich snel over beschadigde huid, vooral bij kinderen met atopisch eczeem. Behandeling met (intraveneus) aciclovir; bij betrokkenheid van de ogen is snel oogheelkundig onderzoek nodig.</p>","image_url":"","wiki_title":"Eczema herpeticum","match":"eczema herpeticum","option_only":true},"methemoglobulinemie":{"title":"Methemoglobinemie","short":"Bij methemoglobinemie is het ijzer in hemoglobine geoxideerd tot Fe³⁺, waardoor het geen zuurstof kan binden; de huid wordt grijsblauw.","definition":"<p>Oorzaken zijn o.a. nitraten/nitrieten (putwater), dapson, lokale anesthetica (benzocaïne) en zelden erfelijke afwijkingen. De pulsoxymeter meet een saturatie rond 85% die niet stijgt met zuurstof; het bloed is chocoladebruin. Behandeling met methyleenblauw.</p>","image_url":"","wiki_title":"Methemoglobinemia","match":"methemoglobulinemie|methemoglobinemie","option_only":true},"atypische lymfocyten":{"title":"Atypische lymfocyten","short":"Atypische (reactieve) lymfocyten zijn grote, geactiveerde T-cellen in het bloeduitstrijkje, kenmerkend voor de ziekte van Pfeiffer.","definition":"<p>Veel <strong>atypische lymfocyten</strong> passen bij mononucleosis infectiosa (EBV), maar komen ook voor bij CMV, acute hiv, toxoplasmose en geneesmiddelreacties.</p>","image_url":"","wiki_title":"Atypical lymphocyte","match":"atypische lymfocyten|reactieve lymfocyten","option_only":true},"demodex folliculitis":{"title":"Demodexfolliculitis","short":"Bij demodexfolliculitis veroorzaakt een overmaat aan haarzakjesmijten (Demodex) jeukende puistjes in het gezicht.","definition":"<p><strong>Demodex</strong>-mijten komen bij vrijwel iedereen voor. Een overgroei (bijv. bij langdurig gebruik van corticosteroïdcrème of verminderde afweer) geeft een rosacea-achtig beeld. Behandeling met ivermectine- of permetrinecrème.</p>","image_url":"","wiki_title":"Demodicosis","match":"demodex folliculitis|demodexfolliculitis|demodex","option_only":true},"hidradenitis suppurativa":{"title":"Hidradenitis suppurativa (acne inversa)","short":"Hidradenitis suppurativa is een chronische ontstekingsziekte van haarfollikels in oksels, liezen en bilnaad, met pijnlijke knobbels, abcessen en fistels.","definition":"<p><strong>Hidradenitis suppurativa</strong> begint na de puberteit; roken en overgewicht verergeren het. Er ontstaan recidiverende abcessen, sinussen en littekens. Behandeling met antibiotica, biologicals (TNF-remmers) en chirurgie.</p>","image_url":"","wiki_title":"Hidradenitis suppurativa","match":"hidradenitis suppurativa|acne inversa","option_only":true},"pityriasis alba":{"title":"Pityriasis alba","short":"Pityriasis alba zijn lichte, licht schilferende vlekken op de wangen van kinderen, vaak bij atopie.","definition":"<p><strong>Pityriasis alba</strong> valt vooral op bij een donkere of gebruinde huid. Het is onschuldig en verdwijnt vanzelf; vette crème en zonbescherming helpen.</p>","image_url":"","wiki_title":"Pityriasis alba","match":"pityriasis alba","option_only":true},"pityriasis rosea":{"title":"Pityriasis rosea","short":"Pityriasis rosea is een onschuldige huiduitslag met eerst één grote ‘moederplek’ en daarna kleinere ovale plekken in een kerstboompatroon op de romp.","definition":"<p><strong>Pityriasis rosea</strong> wordt in verband gebracht met reactivatie van HHV-6/7 en verdwijnt binnen 6–12 weken vanzelf. Secundaire syfilis kan er op lijken.</p>","image_url":"","wiki_title":"Pityriasis rosea","match":"pityriasis rosea","option_only":true},"milia":{"title":"Milia","short":"Milia zijn kleine witte cystjes (gerstekorrels) in de huid, vaak op het gezicht van pasgeborenen.","definition":"<p><strong>Milia</strong> zijn kleine keratinecysten. Bij pasgeborenen verdwijnen ze vanzelf; bij volwassenen kunnen ze na huidbeschadiging ontstaan.</p>","image_url":"","wiki_title":"Milium (dermatology)","match":"milia|gerstekorrels","option_only":true},"malassezia folliculitis":{"title":"Malassezia (Pityrosporum)","short":"Malassezia is een gist op de huid die pityriasis versicolor, seborroïsch eczeem en een jeukende folliculitis kan veroorzaken.","definition":"<p>Bij <strong>pityriasis versicolor</strong> ontstaan schilferende, licht- of donkergekleurde vlekken op de romp; in een KOH-preparaat is het ‘spaghetti met gehaktballen’-beeld te zien. Behandeling met antimycotische shampoo of crème.</p>","image_url":"","wiki_title":"Malassezia","match":"malassezia folliculitis|malassezia|malessezia furfur|pityriasis versicolor","option_only":true},"allergische bronchopulmonale alveolitis":{"title":"Allergische bronchopulmonale aspergillose (ABPA)","short":"ABPA is een overgevoeligheidsreactie op Aspergillus in de luchtwegen, vooral bij astma en cystische fibrose.","definition":"<p>Bij <strong>ABPA</strong> zijn er moeilijk te behandelen astma, bruine slijmproppen, eosinofilie, een zeer hoog totaal IgE en specifiek IgE tegen <em>Aspergillus</em>, met centrale bronchiëctasieën. Behandeling met prednison en eventueel itraconazol.</p>","image_url":"","wiki_title":"Allergic bronchopulmonary aspergillosis","match":"allergische bronchopulmonale alveolitis|abpa|allergische bronchopulmonale aspergillose","option_only":true},"aspergilloma":{"title":"Aspergilloom","short":"Een aspergilloom is een schimmelbal van Aspergillus in een bestaande longholte, bijv. na tuberculose.","definition":"<p>Een <strong>aspergilloom</strong> geeft vaak weinig klachten, maar kan hemoptoë veroorzaken. Op beeldvorming is een bol in een holte met een luchtsikkel te zien.</p>","image_url":"","wiki_title":"Aspergilloma","match":"aspergilloma|aspergilloom|schimmelbal","option_only":true},"otomycosis":{"title":"Otomycose","short":"Otomycose is een schimmelinfectie van de uitwendige gehoorgang, met jeuk en zwarte of witte schimmeldraden.","definition":"<p><strong>Otomycose</strong> (meestal <em>Aspergillus</em> of <em>Candida</em>) ontstaat vaak na het gebruik van antibiotische oordruppels of in een vochtig klimaat. Behandeling: reinigen en antimycotische druppels.</p>","image_url":"","wiki_title":"Otomycosis","match":"otomycosis|otomycose","option_only":true},"syndroom van reye":{"title":"Syndroom van Reye","short":"Het syndroom van Reye is een zeldzame, ernstige combinatie van leverfalen en hersenoedeem bij kinderen na een virale infectie en gebruik van aspirine.","definition":"<p>Vanwege het <strong>syndroom van Reye</strong> wordt acetylsalicylzuur niet gegeven aan kinderen met koorts of virale infecties (vooral influenza en waterpokken).</p>","image_url":"","wiki_title":"Reye syndrome","match":"syndroom van reye|reye","option_only":true},"anuscarcinoom":{"title":"Anuscarcinoom","short":"Het anuscarcinoom is een plaveiselcelcarcinoom van het anaalkanaal, sterk geassocieerd met HPV.","definition":"<p>Risicofactoren voor <strong>anuscarcinoom</strong> zijn HPV-infectie, hiv, receptief anaal contact en immuunsuppressie. Klachten: bloedverlies, pijn en een zwelling. Behandeling meestal met chemoradiatie.</p>","image_url":"","wiki_title":"Anal cancer","match":"anuscarcinoom|anaal carcinoom","option_only":true},"dermatitis perioralis":{"title":"Periorale dermatitis","short":"Periorale dermatitis is een uitslag van rode bultjes en schilfering rond de mond, vaak na gebruik van corticosteroïdcrème.","definition":"<p>Bij <strong>periorale dermatitis</strong> blijft een smalle zone direct rond het lippenrood vaak vrij. Behandeling: stoppen met corticosteroïdcrème en cosmetica, eventueel metronidazolcrème of een tetracycline.</p>","image_url":"","wiki_title":"Perioral dermatitis","match":"dermatitis perioralis|periorale dermatitis","option_only":true},"ungus incarnatus (ingegroeide nagel)":{"title":"Unguis incarnatus (ingegroeide teennagel)","short":"Bij een unguis incarnatus groeit de rand van de teennagel in de nagelwal, met pijn, ontsteking en soms granulatieweefsel.","definition":"<p>Een <strong>ingegroeide teennagel</strong> komt vooral bij de grote teen voor, door te kort of rond knippen, strakke schoenen of een brede nagel. Behandeling: voetbadjes, een tampon onder de nagelrand of een operatieve wigexcisie met fenolisatie.</p>","image_url":"","wiki_title":"Ingrown nail","match":"ungus incarnatus (ingegroeide nagel)|unguis incarnatus|ingegroeide teennagel","option_only":true},"erytrogeen toxine":{"title":"Erytrogeen toxine","short":"Erytrogene (pyrogene) toxines van groep A-streptokokken veroorzaken de huiduitslag bij roodvonk en kunnen als superantigeen een toxischeshocksyndroom geven.","definition":"<p><strong>Superantigenen</strong> binden buiten de gewone antigeenpresentatie om aan MHC II en de T-celreceptor, waardoor een groot deel van de T-cellen tegelijk wordt geactiveerd, met een cytokinestorm.</p>","image_url":"","wiki_title":"Streptococcal pyrogenic exotoxin","match":"erytrogeen toxine|pyrogeen exotoxine","option_only":true},"streptolysine o":{"title":"Streptolysine O","short":"Streptolysine O is een toxine van groep A-streptokokken dat rode bloedcellen kapotmaakt; antistoffen ertegen (ASLO) wijzen op een recente infectie.","definition":"<p>Een verhoogde <strong>ASLO</strong>-titer ondersteunt de diagnose acuut reuma of poststreptokokken-glomerulonefritis. Streptolysine O is zuurstofgevoelig; streptolysine S geeft de bètahemolyse op de bloedagar.</p>","image_url":"","wiki_title":"Streptolysin","match":"streptolysine o|aslo|antistreptolysine","option_only":true},"trypanosomiasis":{"title":"Trypanosomiasis","short":"Trypanosomiasis is een infectie met Trypanosoma: in Afrika de slaapziekte (tseetseevlieg), in Latijns-Amerika de ziekte van Chagas (roofwants).","definition":"<p><strong>Afrikaanse slaapziekte</strong> geeft koorts, lymfeklierzwelling en later neurologische klachten en slaapstoornissen. De <strong>ziekte van Chagas</strong> kan na jaren cardiomyopathie, megaoesofagus en megacolon geven.</p>","image_url":"","wiki_title":"Trypanosomiasis","match":"trypanosomiasis|slaapziekte|ziekte van chagas","option_only":true},"lipo-oligosaccharide":{"title":"Lipo-oligosacharide (LOS)","short":"Lipo-oligosacharide is de korte variant van LPS in de buitenmembraan van Neisseria en Haemophilus, met endotoxinewerking.","definition":"<p>Het <strong>LOS</strong> van meningokokken veroorzaakt de heftige ontstekingsreactie en shock bij een meningokokkensepsis.</p>","image_url":"","wiki_title":"Lipooligosaccharide","match":"lipo-oligosaccharide|lipo-oligosacharide|los","option_only":true},"enterobacter spp":{"title":"Enterobacter","short":"Enterobacter-soorten zijn gramnegatieve darmbacteriën die vooral ziekenhuisinfecties veroorzaken.","definition":"<p><strong>Enterobacter</strong> kan tijdens behandeling resistent worden tegen derdegeneratiecefalosporines door een induceerbaar AmpC-bètalactamase. Het veroorzaakt urineweg-, wond- en bloedbaaninfecties en pneumonie in het ziekenhuis.</p>","image_url":"","wiki_title":"Enterobacter","match":"enterobacter spp|enterobacter|enterobacterales","option_only":true},"afstervingsfase":{"title":"Bacteriële groeicurve","short":"De groeicurve van bacteriën in een kweek bestaat uit een lagfase, exponentiële (log)fase, stationaire fase en afstervingsfase.","definition":"<p>In de <strong>lagfase</strong> passen bacteriën zich aan, in de <strong>logfase</strong> delen ze maximaal (gevoeligst voor celwandantibiotica), in de <strong>stationaire fase</strong> zijn voedingsstoffen op en ontstaan vaak sporen en toxines, en daarna volgt de <strong>afstervingsfase</strong>.</p>","image_url":"","wiki_title":"Bacterial growth","match":"afstervingsfase|lagfase|logfase|stationaire fase|groeicurve","option_only":true},"schistosomiasis":{"title":"Schistosomiasis (bilharzia)","short":"Schistosomiasis is een worminfectie via zoet water in de tropen, waarbij larven door de huid binnendringen.","definition":"<p>Afhankelijk van de soort ontstaan klachten van de blaas (hematurie, later blaaskanker) of darm en lever (portale hypertensie). Een acute vorm (Katayama-koorts) geeft koorts, hoest en eosinofilie. Behandeling met praziquantel.</p>","image_url":"","wiki_title":"Schistosomiasis","match":"schistosomiasis|bilharzia","option_only":true},"coxiella burnetii":{"title":"Coxiella burnetii","short":"Coxiella burnetii is de intracellulaire bacterie die Q-koorts veroorzaakt.","definition":"<p><strong><em>Coxiella</em></strong> is zeer besmettelijk via de lucht, vooral rond het werpen van geiten en schapen. Chronische infectie kan endocarditis en vaatinfecties geven.</p>","image_url":"","wiki_title":"Coxiella burnetii","match":"coxiella burnetii","option_only":true},"roseolen":{"title":"Roseolen","short":"Roseolen zijn kleine, roze, wegdrukbare vlekjes op de romp, kenmerkend voor buiktyfus.","definition":"<p><strong>Roseolen</strong> verschijnen in de tweede week van buiktyfus en zijn vaak moeilijk te zien. Andere kenmerken zijn hoge koorts, relatieve bradycardie, buikpijn en obstipatie of diarree.</p>","image_url":"","wiki_title":"","match":"roseolen","option_only":true},"buiktyfus":{"title":"Buiktyfus","short":"Buiktyfus is een systemische infectie met Salmonella typhi, met hoge koorts, buikpijn en algemeen ziek-zijn.","definition":"<p>Bij <strong>buiktyfus</strong> is er een geleidelijk stijgende koorts met relatieve bradycardie, roseolen en hepatosplenomegalie. Complicaties zijn darmbloedingen en perforatie. Diagnose met bloedkweken; behandeling met antibiotica (ceftriaxon, azitromycine). Er is een vaccin voor reizigers.</p>","image_url":"","wiki_title":"Typhoid fever","match":"buiktyfus|tyfus|salmonella typhi","option_only":true},"splinterbloedingen":{"title":"Splinterbloedingen","short":"Splinterbloedingen zijn kleine, roodbruine lengtestreepjes onder de nagels, o.a. bij endocarditis.","definition":"<p><strong>Splinterbloedingen</strong> passen bij endocarditis (samen met Janeway-laesies, Osler-knobbeltjes en Roth-vlekken), maar komen veel vaker voor door een klein trauma van de nagel.</p>","image_url":"","wiki_title":"Splinter hemorrhage","match":"splinterbloedingen","option_only":true},"tuberculeuze lymfadenitis":{"title":"Tuberculeuze lymfadenitis","short":"Tuberculeuze lymfadenitis is tuberculose van de lymfeklieren, vaak in de hals, met een pijnloze zwelling die kan fistelen.","definition":"<p><strong>Tuberculeuze lymfadenitis</strong> is de meest voorkomende vorm van extrapulmonale tbc. Diagnose met een punctie of biopt (granulomen, kweek, PCR).</p>","image_url":"","wiki_title":"Tuberculous lymphadenitis","match":"tuberculeuze lymfadenitis|scrofula","option_only":true},"plasmodium ovale":{"title":"Plasmodium vivax en ovale","short":"P. vivax en P. ovale veroorzaken een mildere malaria, maar kunnen slapende vormen (hypnozoïeten) in de lever achterlaten, met recidieven.","definition":"<p>Na behandeling van <strong>vivax- of ovalemalaria</strong> wordt primaquine gegeven om de hypnozoïeten te doden (eerst G6PD-deficiëntie uitsluiten). <em>P. knowlesi</em> komt uit Zuidoost-Azië (apen) en kan ernstig verlopen.</p>","image_url":"","wiki_title":"Plasmodium vivax","match":"plasmodium ovale|plasmodium vivax|plasmodium knowlesi","option_only":true},"fenomeen van raynaud":{"title":"Fenomeen van Raynaud","short":"Bij het fenomeen van Raynaud verkleuren vingers bij kou of stress wit, daarna blauw en rood, door vaatkramp.","definition":"<p>Het <strong>primaire</strong> fenomeen van Raynaud komt veel voor bij jonge vrouwen en is onschuldig. <strong>Secundair</strong> Raynaud (later begin, ernstiger, met wondjes) past bij systemische sclerose, SLE, medicatie (bètablokkers) of trilmachines. Behandeling: warm houden, eventueel calciumantagonisten.</p>","image_url":"","wiki_title":"Raynaud syndrome","match":"fenomeen van raynaud|raynaud","option_only":true},"polyangiitis nodosa (pan)":{"title":"Polyarteriitis nodosa","short":"Polyarteriitis nodosa is een necrotiserende vasculitis van middelgrote arteriën, zonder ANCA en zonder glomerulonefritis.","definition":"<p>Bij <strong>polyarteriitis nodosa</strong> raken middelgrote spierarteriën ontstoken, met microaneurysmata en infarcten in o.a. nieren (hypertensie), darm (buikpijn), huid (livedo, ulcera) en zenuwen (mononeuritis multiplex). Een deel van de gevallen hangt samen met hepatitis B. De longen zijn meestal niet aangedaan.</p>","image_url":"","wiki_title":"Polyarteritis nodosa","match":"polyangiitis nodosa (pan)","option_only":true},"haemophilus influenza type b":{"title":"Haemophilus influenzae","short":"H. influenzae is een kleine gramnegatieve staaf die luchtweginfecties, otitis en (vroeger vaak) meningitis en epiglottitis bij kinderen veroorzaakt.","definition":"<p><strong><em>Haemophilus influenzae</em></strong> is een kleine, gramnegatieve coccobacil. Ondanks de naam veroorzaakt hij geen influenza (dat is een virus).</p><p>Onomkapselde stammen veroorzaken otitis media, sinusitis en exacerbaties van COPD. Het omkapselde type b (Hib) veroorzaakte vroeger veel meningitis en epiglottitis bij jonge kinderen; sinds de Hib-vaccinatie is dat zeldzaam.</p>","image_url":"","wiki_title":"Haemophilus influenzae","match":"haemophilus influenza type b","option_only":true},"haemofilus influenzae":{"title":"Haemophilus influenzae","short":"H. influenzae is een kleine gramnegatieve staaf die luchtweginfecties, otitis en (vroeger vaak) meningitis en epiglottitis bij kinderen veroorzaakt.","definition":"<p><strong><em>Haemophilus influenzae</em></strong> is een kleine, gramnegatieve coccobacil. Ondanks de naam veroorzaakt hij geen influenza (dat is een virus).</p><p>Onomkapselde stammen veroorzaken otitis media, sinusitis en exacerbaties van COPD. Het omkapselde type b (Hib) veroorzaakte vroeger veel meningitis en epiglottitis bij jonge kinderen; sinds de Hib-vaccinatie is dat zeldzaam.</p>","image_url":"","wiki_title":"Haemophilus influenzae","match":"haemofilus influenzae","option_only":true},"pulmonale tuberculose":{"title":"Longtuberculose","short":"Longtuberculose is tuberculose van de longen; de vorm die besmettelijk is via hoesten.","definition":"<p>Bij een <strong>primaire infectie</strong> ontstaat meestal een kleine haard met lymfeklierbetrokkenheid (Ghon-complex), die tot rust komt (latente tbc). Bij <strong>reactivatie</strong> (verminderde afweer, ouderdom) ontstaan vooral in de longtoppen infiltraten en holtes, met langdurig hoesten, nachtzweten, gewichtsverlies en soms hemoptoë. Latente tbc kan met een tuberculinehuidtest of IGRA worden aangetoond.</p>","image_url":"","wiki_title":"Tuberculosis","match":"pulmonale tuberculose","option_only":true},"primaire longtuberculose":{"title":"Longtuberculose","short":"Longtuberculose is tuberculose van de longen; de vorm die besmettelijk is via hoesten.","definition":"<p>Bij een <strong>primaire infectie</strong> ontstaat meestal een kleine haard met lymfeklierbetrokkenheid (Ghon-complex), die tot rust komt (latente tbc). Bij <strong>reactivatie</strong> (verminderde afweer, ouderdom) ontstaan vooral in de longtoppen infiltraten en holtes, met langdurig hoesten, nachtzweten, gewichtsverlies en soms hemoptoë. Latente tbc kan met een tuberculinehuidtest of IGRA worden aangetoond.</p>","image_url":"","wiki_title":"Tuberculosis","match":"primaire longtuberculose","option_only":true},"pulmonale tb met cavernes":{"title":"Longtuberculose","short":"Longtuberculose is tuberculose van de longen; de vorm die besmettelijk is via hoesten.","definition":"<p>Bij een <strong>primaire infectie</strong> ontstaat meestal een kleine haard met lymfeklierbetrokkenheid (Ghon-complex), die tot rust komt (latente tbc). Bij <strong>reactivatie</strong> (verminderde afweer, ouderdom) ontstaan vooral in de longtoppen infiltraten en holtes, met langdurig hoesten, nachtzweten, gewichtsverlies en soms hemoptoë. Latente tbc kan met een tuberculinehuidtest of IGRA worden aangetoond.</p>","image_url":"","wiki_title":"Tuberculosis","match":"pulmonale tb met cavernes","option_only":true},"open tuberculose":{"title":"Longtuberculose","short":"Longtuberculose is tuberculose van de longen; de vorm die besmettelijk is via hoesten.","definition":"<p>Bij een <strong>primaire infectie</strong> ontstaat meestal een kleine haard met lymfeklierbetrokkenheid (Ghon-complex), die tot rust komt (latente tbc). Bij <strong>reactivatie</strong> (verminderde afweer, ouderdom) ontstaan vooral in de longtoppen infiltraten en holtes, met langdurig hoesten, nachtzweten, gewichtsverlies en soms hemoptoë. Latente tbc kan met een tuberculinehuidtest of IGRA worden aangetoond.</p>","image_url":"","wiki_title":"Tuberculosis","match":"open tuberculose","option_only":true},"legionellose (legionella pneumophila)":{"title":"Legionella pneumophila","short":"Legionella is een gramnegatieve staaf uit warm water die een ernstige (atypische) pneumonie kan veroorzaken: de veteranenziekte.","definition":"<p><strong><em>Legionella pneumophila</em></strong> groeit in warmwatersystemen, koeltorens en bubbelbaden en wordt via aerosolen ingeademd; er is geen overdracht van mens op mens. Risicofactoren zijn hogere leeftijd, roken en immuunsuppressie. Naast pneumonie kunnen diarree, verwardheid en hyponatriëmie optreden. Diagnose met de urine-antigeentest; bètalactamantibiotica werken niet, macroliden en chinolonen wel.</p>","image_url":"","wiki_title":"Legionella pneumophila","match":"legionellose (legionella pneumophila)","option_only":true},"candida-infectie":{"title":"Candida albicans","short":"Candida albicans is een gist die normaal op slijmvliezen voorkomt en bij verminderde weerstand spruw, vaginale schimmelinfectie of invasieve infecties geeft.","definition":"<p><strong><em>Candida albicans</em></strong> is een gist (schimmel) die bij veel mensen in mond, darm en vagina voorkomt. Hij kan zowel als ronde gistcel als met (pseudo)hyfen groeien.</p><p>Bij een verstoorde flora (antibiotica) of verminderde afweer veroorzaakt hij oppervlakkige infecties zoals spruw (orale candidiasis), vaginale candidiasis en intertrigo. Bij ernstig immuungecompromitteerden of patiënten met lijnen kan een invasieve candidemie ontstaan.</p>","image_url":"","wiki_title":"Candida albicans","match":"candida-infectie","option_only":true},"rsv bronchiolitis":{"title":"Respiratoir syncytieel virus (RSV)","short":"RSV is een RNA-virus dat in de winter luchtweginfecties geeft, bij zuigelingen vaak bronchiolitis.","definition":"<p><strong>RSV</strong> geeft bij volwassenen meestal een verkoudheid, maar bij zuigelingen kan het de kleine luchtwegen aantasten, met piepen, benauwdheid en drinkproblemen. Ex-prematuren en kinderen met hart- of longafwijkingen lopen het meeste risico. Er bestaan antistoffen ter preventie (palivizumab, nirsevimab) en een vaccin voor zwangeren en ouderen.</p>","image_url":"","wiki_title":"Respiratory syncytial virus","match":"rsv bronchiolitis","option_only":true},"rotavirusinfectie":{"title":"Rotavirus","short":"Rotavirus is een dubbelstrengs RNA-virus dat bij jonge kinderen een ernstige gastro-enteritis met braken en waterige diarree veroorzaakt.","definition":"<p><strong>Rotavirus</strong> wordt fecaal-oraal overgedragen en beschadigt de villi van de dunne darm. Vooral kinderen onder de 2 jaar krijgen koorts, braken en waterige diarree, met risico op uitdroging. Er bestaat een oraal levend vaccin, inmiddels opgenomen in het Rijksvaccinatieprogramma.</p>","image_url":"","wiki_title":"Rotavirus","match":"rotavirusinfectie","option_only":true},"pneumonie door pneumokokken":{"title":"Streptococcus pneumoniae","short":"De pneumokok is een grampositieve diplokok met een kapsel; de belangrijkste verwekker van pneumonie, otitis media en bacteriële meningitis.","definition":"<p><strong><em>Streptococcus pneumoniae</em></strong> (pneumokok) is een grampositieve, lancetvormige diplokok die α-hemolyse geeft op bloedagar. Het polysacharidekapsel is de belangrijkste virulentiefactor: het beschermt tegen fagocytose.</p><p>De pneumokok koloniseert de nasofarynx en is de meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie, otitis media, sinusitis en bacteriële meningitis bij volwassenen. Kinderen en ouderen worden ertegen gevaccineerd.</p>","image_url":"","wiki_title":"Streptococcus pneumoniae","match":"pneumonie door pneumokokken","option_only":true},"mycoplasmapneumonie":{"title":"Mycoplasma pneumoniae","short":"Mycoplasma pneumoniae is een bacterie zonder celwand die bij jongeren een ‘atypische’ pneumonie veroorzaakt.","definition":"<p><strong><em>Mycoplasma pneumoniae</em></strong> heeft geen peptidoglycaanwand en is daardoor ongevoelig voor bètalactamantibiotica en niet zichtbaar met een gramkleuring. Het veroorzaakt vooral bij schoolkinderen en jongvolwassenen een geleidelijk beginnende luchtweginfectie met droge hoest. Er kunnen koude agglutininen (hemolyse) en extrapulmonale verschijnselen optreden. Behandeling met macroliden of doxycycline.</p>","image_url":"","wiki_title":"Mycoplasma pneumoniae","match":"mycoplasmapneumonie","option_only":true},"malaria tropica":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"malaria tropica","option_only":true},"plasmodium falciparum-malaria":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"plasmodium falciparum-malaria","option_only":true},"plasmodium vivax-malaria":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"plasmodium vivax-malaria","option_only":true},"plasmodium spp":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"plasmodium spp","option_only":true},"malariaparasiet":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"malariaparasiet","option_only":true},"ziekte van lyme":{"title":"Borrelia burgdorferi","short":"Borrelia burgdorferi is de spirocheet die door teken wordt overgebracht en de ziekte van Lyme veroorzaakt.","definition":"<p><strong><em>Borrelia burgdorferi</em></strong> wordt overgebracht door de schapenteek (<em>Ixodes ricinus</em>), meestal pas na een aanhechting van meer dan 24 uur. Vroege lokale infectie geeft erythema migrans; verspreiding kan leiden tot neuroborreliose, lyme-artritis, carditis (AV-blok) en huidafwijkingen (acrodermatitis). Behandeling met doxycycline of ceftriaxon.</p>","image_url":"","wiki_title":"Borrelia burgdorferi","match":"ziekte van lyme","option_only":true},"borreliose":{"title":"Borrelia burgdorferi","short":"Borrelia burgdorferi is de spirocheet die door teken wordt overgebracht en de ziekte van Lyme veroorzaakt.","definition":"<p><strong><em>Borrelia burgdorferi</em></strong> wordt overgebracht door de schapenteek (<em>Ixodes ricinus</em>), meestal pas na een aanhechting van meer dan 24 uur. Vroege lokale infectie geeft erythema migrans; verspreiding kan leiden tot neuroborreliose, lyme-artritis, carditis (AV-blok) en huidafwijkingen (acrodermatitis). Behandeling met doxycycline of ceftriaxon.</p>","image_url":"","wiki_title":"Borrelia burgdorferi","match":"borreliose","option_only":true},"hepatitis-b":{"title":"Hepatitis B","short":"Hepatitis B is een via bloed en seks overgedragen DNA-virus dat acute en chronische leverontsteking geeft, met risico op cirrose en levercelcarcinoom.","definition":"<p><strong>Hepatitis B</strong> wordt veroorzaakt door het hepatitis B-virus, een omhuld (gedeeltelijk dubbelstrengs) DNA-virus. Overdracht via bloed, seksueel contact en van moeder op kind rond de geboorte.</p><p>Bij volwassenen geneest de meeste acute infectie; bij pasgeborenen wordt de infectie meestal <em>chronisch</em>. Chronische hepatitis B kan leiden tot levercirrose en hepatocellulair carcinoom. Diagnostiek via serologie (HBsAg, anti-HBc, anti-HBs). Er is een effectief vaccin.</p>","image_url":"","wiki_title":"Hepatitis B","match":"hepatitis-b","option_only":true},"hepatitis b virus":{"title":"Hepatitis B","short":"Hepatitis B is een via bloed en seks overgedragen DNA-virus dat acute en chronische leverontsteking geeft, met risico op cirrose en levercelcarcinoom.","definition":"<p><strong>Hepatitis B</strong> wordt veroorzaakt door het hepatitis B-virus, een omhuld (gedeeltelijk dubbelstrengs) DNA-virus. Overdracht via bloed, seksueel contact en van moeder op kind rond de geboorte.</p><p>Bij volwassenen geneest de meeste acute infectie; bij pasgeborenen wordt de infectie meestal <em>chronisch</em>. Chronische hepatitis B kan leiden tot levercirrose en hepatocellulair carcinoom. Diagnostiek via serologie (HBsAg, anti-HBc, anti-HBs). Er is een effectief vaccin.</p>","image_url":"","wiki_title":"Hepatitis B","match":"hepatitis b virus","option_only":true},"chlamydia psittaci":{"title":"Psittacose","short":"Psittacose is een longontsteking door Chlamydia psittaci, opgelopen via (stof van) besmette vogels.","definition":"<p>Bij <strong>psittacose</strong> zijn er hoge koorts, hoofdpijn, droge hoest en spierpijn, soms met een relatief trage pols. Contact met vogels (papegaaien, duiven) is de belangrijkste aanwijzing. Behandeling met doxycycline.</p>","image_url":"","wiki_title":"Psittacosis","match":"chlamydia psittaci","option_only":true},"enveloppe eiwit":{"title":"Virale envelop","short":"Een envelop is de lipide-buitenmantel van sommige virussen, afkomstig van de membraan van de gastheercel.","definition":"<p><strong>Omhulde virussen</strong> (bijv. influenza, hiv, herpes, corona) zijn gevoelig voor uitdroging, zeep, alcohol en detergentia en worden meestal via druppels, bloed of direct contact overgedragen. Niet-omhulde virussen (bijv. norovirus, adenovirus) zijn veel stabieler in de omgeving.</p>","image_url":"","wiki_title":"Viral envelope","match":"enveloppe eiwit","option_only":true},"nucleocapside eiwit":{"title":"Capside","short":"Het capside is de eiwitmantel die het genetisch materiaal van een virus omsluit.","definition":"<p>Het <strong>capside</strong> bestaat uit herhaalde eiwiteenheden (capsomeren) en is meestal icosaëdrisch of helixvormig. Samen met het nucleïnezuur vormt het het nucleocapside; omhulde virussen hebben daaromheen nog een lipide-envelop afkomstig van de gastheercel. Niet-omhulde virussen zijn stabieler in de omgeving.</p>","image_url":"","wiki_title":"Capsid","match":"nucleocapside eiwit","option_only":true},"humaan papillomavirus 16":{"title":"Humaan papillomavirus (HPV)","short":"HPV is een DNA-virus dat wratten veroorzaakt; hoog-risicotypes (o.a. 16 en 18) veroorzaken baarmoederhalskanker en andere kankers.","definition":"<p>Het <strong>humaan papillomavirus</strong> infecteert basale cellen van huid en slijmvlies. Laag-risicotypes (6, 11) geven wratten en condylomata acuminata. Hoog-risicotypes maken de eiwitten E6 en E7, die p53 en Rb uitschakelen; persisterende infectie kan leiden tot cervixcarcinoom en kankers van anus, vulva, penis en orofarynx. Er is een vaccin en een bevolkingsonderzoek met hrHPV-test.</p>","image_url":"","wiki_title":"Human papillomavirus infection","match":"humaan papillomavirus 16","option_only":true},"ankylosing spondylitis (m. bechterew)":{"title":"Ziekte van Bechterew (spondylitis ankylopoetica)","short":"De ziekte van Bechterew is een chronische ontsteking van de wervelkolom en SI-gewrichten, vaak bij jonge mannen met HLA-B27, met ochtendstijfheid en lage rugpijn.","definition":"<p>De <strong>ziekte van Bechterew</strong> is een axiale spondyloartritis: een chronische ontsteking van de <em>sacro-iliacale gewrichten</em> en de wervelkolom, met name de aanhechtingen van banden en pezen (enthesitis).</p><p>Ze begint meestal voor het 40e jaar met inflammatoire lage rugpijn: ochtendstijfheid, verbetering bij bewegen, ’s nachts pijn. Er is een sterke associatie met <em>HLA-B27</em>. Op termijn kan verbening de wervelkolom verstijven (‘bamboo spine’). Extra-articulair: uveïtis anterior, IBD en psoriasis.</p>","image_url":"","wiki_title":"Ankylosing spondylitis","match":"ankylosing spondylitis (m. bechterew)","option_only":true},"campylobacter spp":{"title":"Campylobacter jejuni","short":"Campylobacter jejuni is een gekromde gramnegatieve staaf en een belangrijke oorzaak van bacteriële gastro-enteritis, vaak via kip.","definition":"<p><strong><em>Campylobacter jejuni</em></strong> wordt opgelopen via onvoldoende verhit gevogelte, rauwe melk of besmet water. Het geeft koorts, buikkrampen en (soms bloederige) diarree. Een bekende late complicatie is het syndroom van Guillain-Barré, door kruisreactie van antistoffen met gangliosiden in zenuwen; ook reactieve artritis komt voor.</p>","image_url":"","wiki_title":"Campylobacter jejuni","match":"campylobacter spp","option_only":true},"contact allergisch eczeem":{"title":"Contactallergisch eczeem","short":"Contactallergisch eczeem is een type IV-overgevoeligheidsreactie van de huid op een stof waarvoor iemand gesensibiliseerd is.","definition":"<p>Bij <strong>allergisch contacteczeem</strong> wordt de huid eerst gesensibiliseerd voor een stof (bijv. nikkel, parfum, rubberchemicaliën, conserveermiddelen). Bij herhaald contact ontstaat na 1–3 dagen een jeukend eczeem, dat zich ook buiten het contactgebied kan uitbreiden. Diagnose met plakproeven (epicutane test); behandeling is vermijden van het allergeen.</p>","image_url":"","wiki_title":"Allergic contact dermatitis","match":"contact allergisch eczeem","option_only":true},"acuut rheuma (rheumatic fever)":{"title":"Acuut reuma","short":"Acuut reuma is een ontstekingsziekte enkele weken na een keelinfectie met groep A-streptokokken, door kruisreactie van antistoffen.","definition":"<p><strong>Acuut reuma</strong> geeft volgens de Jones-criteria o.a. carditis, een migrerende polyartritis, chorea van Sydenham, erythema marginatum en subcutane noduli. De carditis kan leiden tot chronische reumatische klepziekte, vooral van de mitralisklep. Het is in Nederland zeldzaam geworden, maar wereldwijd nog een belangrijke oorzaak van hartziekte.</p>","image_url":"","wiki_title":"Rheumatic fever","match":"acuut rheuma (rheumatic fever)","option_only":true},"juveniele chronische artritis":{"title":"Juveniele idiopathische artritis (JIA)","short":"JIA is een chronische artritis die vóór het 16e jaar begint en langer dan zes weken duurt, zonder andere oorzaak.","definition":"<p><strong>JIA</strong> heeft verschillende vormen: oligoarticulair (vaak jonge meisjes, met risico op stille uveïtis anterior, daarom regelmatige oogcontrole), polyarticulair, systemisch (ziekte van Still), enthesitis-gerelateerd en psoriatisch. Behandeling met NSAID's, gewrichtsinjecties, methotrexaat en biologicals.</p>","image_url":"","wiki_title":"Juvenile idiopathic arthritis","match":"juveniele chronische artritis","option_only":true},"cyclo-oxygenase inhibitors (cox-remmers)":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"cyclo-oxygenase inhibitors (cox-remmers)","option_only":true},"secundaire syphilis":{"title":"Syfilis (lues)","short":"Syfilis is een seksueel overdraagbare infectie door Treponema pallidum, die in stadia verloopt.","definition":"<p><strong>Syfilis</strong> begint (primair) met een pijnloos ulcus (sjanker) op de plek van besmetting. Weken later volgt het secundaire stadium met huiduitslag (ook op handpalmen en voetzolen), condylomata lata en algemene klachten. Na een latente fase kan na jaren tertiaire syfilis ontstaan (gummata, cardiovasculaire en neurosyfilis). Congenitale syfilis wordt voorkomen door screening in de zwangerschap.</p>","image_url":"","wiki_title":"Syphilis","match":"secundaire syphilis","option_only":true},"secundaire syfilis":{"title":"Syfilis (lues)","short":"Syfilis is een seksueel overdraagbare infectie door Treponema pallidum, die in stadia verloopt.","definition":"<p><strong>Syfilis</strong> begint (primair) met een pijnloos ulcus (sjanker) op de plek van besmetting. Weken later volgt het secundaire stadium met huiduitslag (ook op handpalmen en voetzolen), condylomata lata en algemene klachten. Na een latente fase kan na jaren tertiaire syfilis ontstaan (gummata, cardiovasculaire en neurosyfilis). Congenitale syfilis wordt voorkomen door screening in de zwangerschap.</p>","image_url":"","wiki_title":"Syphilis","match":"secundaire syfilis","option_only":true},"dermatomycosis corporis":{"title":"Dermatomycose","short":"Een dermatomycose is een schimmelinfectie van huid, haren of nagels, meestal door dermatofyten.","definition":"<p>Voorbeelden zijn tinea pedis (zwemmerseczeem), tinea corporis (ringvormig met actieve schilferende rand), tinea cruris, tinea capitis en onychomycose. Diagnose met een KOH-preparaat of kweek; behandeling met lokale of orale antimycotica. Lokale corticosteroïden maskeren het beeld (tinea incognito).</p>","image_url":"","wiki_title":"Dermatophytosis","match":"dermatomycosis corporis","option_only":true},"aspergillus fumigatis":{"title":"Aspergillus fumigatus","short":"Aspergillus fumigatus is een schimmel waarvan de sporen overal in de lucht zijn; bij neutropenie kan hij een invasieve longinfectie geven.","definition":"<p><strong><em>Aspergillus</em></strong> kan verschillende ziektebeelden geven: allergische bronchopulmonale aspergillose (bij astma en CF), een aspergilloom (schimmelbal in een bestaande holte) en invasieve aspergillose bij ernstig afweergestoorde patiënten, met invasie van bloedvaten. Diagnostiek met CT, galactomannan en kweek; behandeling met voriconazol.</p>","image_url":"","wiki_title":"Aspergillus fumigatus","match":"aspergillus fumigatis","option_only":true},"krentenbaard (impetigo)":{"title":"Impetigo","short":"Impetigo (krentenbaard) is een oppervlakkige, besmettelijke bacteriële huidinfectie met honinggele korsten.","definition":"<p><strong>Impetigo</strong> wordt veroorzaakt door <em>S. aureus</em> en/of groep A-streptokokken en komt vooral bij kinderen voor, vaak rond neus en mond. Er zijn blaasjes die openbreken tot korsten. Behandeling met hygiëne en zo nodig fusidinezuurcrème of orale antibiotica.</p>","image_url":"","wiki_title":"Impetigo","match":"krentenbaard (impetigo)","option_only":true},"impetigo (krentenbaard)":{"title":"Impetigo","short":"Impetigo (krentenbaard) is een oppervlakkige, besmettelijke bacteriële huidinfectie met honinggele korsten.","definition":"<p><strong>Impetigo</strong> wordt veroorzaakt door <em>S. aureus</em> en/of groep A-streptokokken en komt vooral bij kinderen voor, vaak rond neus en mond. Er zijn blaasjes die openbreken tot korsten. Behandeling met hygiëne en zo nodig fusidinezuurcrème of orale antibiotica.</p>","image_url":"","wiki_title":"Impetigo","match":"impetigo (krentenbaard)","option_only":true},"waterpokkenvirus":{"title":"Varicella-zostervirus (VZV)","short":"Het varicella-zostervirus veroorzaakt waterpokken en blijft daarna latent in sensibele ganglia, van waaruit het als gordelroos kan reactiveren.","definition":"<p>Het <strong>varicella-zostervirus</strong> (HHV-3) is zeer besmettelijk via aerosolen en blaasjesvocht. De primaire infectie, <em>waterpokken</em>, geeft koorts en jeukende blaasjes in verschillende stadia tegelijk. Het virus nestelt zich in sensibele ganglia; reactivatie geeft <em>herpes zoster</em>. Gevaarlijk is infectie bij zwangeren, pasgeborenen en afweergestoorden (pneumonie, encefalitis).</p>","image_url":"","wiki_title":"Varicella zoster virus","match":"waterpokkenvirus","option_only":true},"varicella zostervirusinfectie":{"title":"Varicella-zostervirus (VZV)","short":"Het varicella-zostervirus veroorzaakt waterpokken en blijft daarna latent in sensibele ganglia, van waaruit het als gordelroos kan reactiveren.","definition":"<p>Het <strong>varicella-zostervirus</strong> (HHV-3) is zeer besmettelijk via aerosolen en blaasjesvocht. De primaire infectie, <em>waterpokken</em>, geeft koorts en jeukende blaasjes in verschillende stadia tegelijk. Het virus nestelt zich in sensibele ganglia; reactivatie geeft <em>herpes zoster</em>. Gevaarlijk is infectie bij zwangeren, pasgeborenen en afweergestoorden (pneumonie, encefalitis).</p>","image_url":"","wiki_title":"Varicella zoster virus","match":"varicella zostervirusinfectie","option_only":true},"rodehondvirus":{"title":"Rode hond (rubella)","short":"Rode hond is een milde virale ziekte met huiduitslag en zwollen klieren, maar bij infectie in de vroege zwangerschap ontstaat het congenitaal rubellasyndroom.","definition":"<p><strong>Rode hond</strong> (rubella) wordt veroorzaakt door het rubellavirus, een omhuld RNA-virus. Bij kinderen verloopt het mild: lichte koorts, kleinvlekkige huiduitslag en gezwollen lymfeklieren (o.a. achter de oren en in de nek).</p><p>Gevaarlijk is infectie van een zwangere in het eerste trimester: het virus kan de foetus besmetten en het <em>congenitaal rubellasyndroom</em> veroorzaken (doofheid, cataract, hartafwijkingen). Vaccinatie gebeurt met het BMR-vaccin.</p>","image_url":"","wiki_title":"Rubella","match":"rodehondvirus","option_only":true},"denguevirus":{"title":"Dengue (knokkelkoorts)","short":"Dengue is een door Aedes-muggen overgebrachte virusinfectie met hoge koorts, hevige spier- en gewrichtspijn en huiduitslag.","definition":"<p><strong>Dengue</strong> wordt veroorzaakt door een flavivirus met vier serotypes. Na een paar dagen incubatie volgen hoge koorts, hoofdpijn achter de ogen, spier- en gewrichtspijn en een rash. Een tweede infectie met een ander serotype geeft een groter risico op ernstige dengue met plasmalekkage, bloedingen en shock (door antistof-afhankelijke versterking). Behandeling is ondersteunend; NSAID's worden vermeden.</p>","image_url":"","wiki_title":"Dengue fever","match":"denguevirus","option_only":true},"dengue virus":{"title":"Dengue (knokkelkoorts)","short":"Dengue is een door Aedes-muggen overgebrachte virusinfectie met hoge koorts, hevige spier- en gewrichtspijn en huiduitslag.","definition":"<p><strong>Dengue</strong> wordt veroorzaakt door een flavivirus met vier serotypes. Na een paar dagen incubatie volgen hoge koorts, hoofdpijn achter de ogen, spier- en gewrichtspijn en een rash. Een tweede infectie met een ander serotype geeft een groter risico op ernstige dengue met plasmalekkage, bloedingen en shock (door antistof-afhankelijke versterking). Behandeling is ondersteunend; NSAID's worden vermeden.</p>","image_url":"","wiki_title":"Dengue fever","match":"dengue virus","option_only":true},"neiseria meningitidis":{"title":"Neisseria meningitidis (meningokok)","short":"De meningokok is een gramnegatieve diplokok die meningitis en een snel fataal verlopende sepsis met petechiën kan veroorzaken.","definition":"<p><strong><em>Neisseria meningitidis</em></strong> koloniseert de nasofarynx en wordt via druppels overgedragen. Het kapsel en endotoxine (LOS) maken hem zeer virulent. Een invasieve infectie geeft meningitis en/of een fulminante sepsis met petechiën en purpura (soms met bijnierbloedingen). Er wordt gevaccineerd tegen serogroepen ACWY en B; contacten krijgen profylaxe.</p>","image_url":"","wiki_title":"Neisseria meningitidis","match":"neiseria meningitidis","option_only":true},"urinesediment":{"title":"Leukocyturie","short":"Leukocyturie is de aanwezigheid van witte bloedcellen in de urine, meestal bij een urineweginfectie.","definition":"<p><strong>Leukocyturie</strong> wordt aangetoond met een teststrook (leukocytenesterase) of microscopie. Meestal past het bij een bacteriële urineweginfectie, eventueel samen met positief nitriet. ‘Steriele’ leukocyturie zonder groei in de kweek komt voor bij o.a. chlamydia, urogenitale tuberculose, tubulo-interstitiële nefritis en na antibioticagebruik.</p>","image_url":"","wiki_title":"Pyuria","match":"urinesediment","option_only":true},"imipenem/cilastine":{"title":"Imipenem-cilastatine","short":"Imipenem is een carbapenem met een zeer breed spectrum; cilastatine voorkomt de afbraak ervan in de nier.","definition":"<p><strong>Imipenem</strong> werkt tegen grampositieve, gramnegatieve (incl. <em>Pseudomonas</em>) en anaerobe bacteriën en is stabiel tegen ESBL. Cilastatine remt een nierenzym (dehydropeptidase) dat imipenem anders zou afbreken. Bijwerking bij hoge doses: insulten.</p>","image_url":"","wiki_title":"Imipenem/cilastatin","match":"imipenem/cilastine","option_only":true},"fièvre boutonneusi":{"title":"Rickettsia conorii (boutonneuse koorts)","short":"Rickettsia conorii is een intracellulaire bacterie die door teken wordt overgebracht en boutonneuse koorts veroorzaakt, rond de Middellandse Zee.","definition":"<p><strong>Rickettsiosen</strong> geven koorts, hoofdpijn en een huiduitslag. Rickettsiae infecteren endotheelcellen. Behandeling met doxycycline.</p>","image_url":"","wiki_title":"Boutonneuse fever","match":"fièvre boutonneusi","option_only":true},"herpes simplex type 1":{"title":"Herpes simplexvirus (HSV)","short":"Het herpes simplexvirus veroorzaakt blaasjes op huid en slijmvliezen en blijft daarna latent in sensibele ganglia.","definition":"<p>Er zijn twee typen: <strong>HSV-1</strong> (vooral oraal, koortslip, gingivostomatitis) en <strong>HSV-2</strong> (vooral genitaal), al overlappen ze. Na de primaire infectie blijft het virus latent in sensibele ganglia en kan het reactiveren. Ernstige vormen zijn herpesencefalitis, keratitis, eczema herpeticum en neonatale herpes. Behandeling met (val)aciclovir.</p>","image_url":"","wiki_title":"Herpes simplex virus","match":"herpes simplex type 1","option_only":true},"herpes simplexvirusinfectie":{"title":"Herpes simplexvirus (HSV)","short":"Het herpes simplexvirus veroorzaakt blaasjes op huid en slijmvliezen en blijft daarna latent in sensibele ganglia.","definition":"<p>Er zijn twee typen: <strong>HSV-1</strong> (vooral oraal, koortslip, gingivostomatitis) en <strong>HSV-2</strong> (vooral genitaal), al overlappen ze. Na de primaire infectie blijft het virus latent in sensibele ganglia en kan het reactiveren. Ernstige vormen zijn herpesencefalitis, keratitis, eczema herpeticum en neonatale herpes. Behandeling met (val)aciclovir.</p>","image_url":"","wiki_title":"Herpes simplex virus","match":"herpes simplexvirusinfectie","option_only":true},"herpes zosterinfectie":{"title":"Herpes zoster (gordelroos)","short":"Herpes zoster is de reactivatie van het varicella-zostervirus uit een sensibel ganglion, met pijnlijke blaasjes in één dermatoom.","definition":"<p>Na waterpokken blijft het <strong>varicella-zostervirus</strong> latent aanwezig in sensibele ganglia (spinale ganglia of hersenzenuwganglia). Bij afnemende cellulaire afweer (ouderdom, immuunsuppressie) kan het reactiveren.</p><p>Dan ontstaan pijnlijke, gegroepeerde blaasjes op een rode ondergrond in één <em>dermatoom</em>, meestal eenzijdig. Complicaties zijn postherpetische neuralgie en, bij de n. ophthalmicus, oogbetrokkenheid (zoster ophthalmicus).</p>","image_url":"","wiki_title":"Shingles","match":"herpes zosterinfectie","option_only":true},"amoxocilline/clavulaanzuur":{"title":"Amoxicilline-clavulaanzuur","short":"Amoxicilline-clavulaanzuur combineert een penicilline met een bètalactamaseremmer, waardoor ook bètalactamasevormende bacteriën worden gedekt.","definition":"<p>Clavulaanzuur heeft zelf nauwelijks antibacteriële werking maar remt veel <em>bètalactamasen</em>, zodat amoxicilline niet wordt afgebroken. De combinatie werkt daardoor ook tegen o.a. <em>S. aureus</em> (geen MRSA), <em>H. influenzae</em>, <em>Moraxella</em>, veel <em>E. coli</em> en anaeroben zoals <em>Bacteroides</em>. Bijwerkingen: diarree en (zelden) cholestatische hepatitis.</p>","image_url":"","wiki_title":"Amoxicillin/clavulanic acid","match":"amoxocilline/clavulaanzuur","option_only":true},"tnf-alfablokker":{"title":"Infliximab","short":"Infliximab is een monoklonaal antilichaam tegen TNF-α, gebruikt bij o.a. de ziekte van Crohn, colitis ulcerosa en reumatoïde artritis.","definition":"<p><strong>TNF-α-remmers</strong> zoals infliximab, adalimumab en etanercept remmen een centraal pro-inflammatoir cytokine. Ze worden gebruikt bij IBD, reumatoïde artritis, spondyloartritis en psoriasis. Doordat ze de cellulaire afweer verzwakken, kan latente tuberculose reactiveren; daarom wordt vooraf gescreend. Ook het risico op andere infecties is verhoogd.</p>","image_url":"","wiki_title":"Infliximab","match":"tnf-alfablokker","option_only":true},"tnf-alfaremmers":{"title":"Infliximab","short":"Infliximab is een monoklonaal antilichaam tegen TNF-α, gebruikt bij o.a. de ziekte van Crohn, colitis ulcerosa en reumatoïde artritis.","definition":"<p><strong>TNF-α-remmers</strong> zoals infliximab, adalimumab en etanercept remmen een centraal pro-inflammatoir cytokine. Ze worden gebruikt bij IBD, reumatoïde artritis, spondyloartritis en psoriasis. Doordat ze de cellulaire afweer verzwakken, kan latente tuberculose reactiveren; daarom wordt vooraf gescreend. Ook het risico op andere infecties is verhoogd.</p>","image_url":"","wiki_title":"Infliximab","match":"tnf-alfaremmers","option_only":true},"tnf-alfaremmer":{"title":"Infliximab","short":"Infliximab is een monoklonaal antilichaam tegen TNF-α, gebruikt bij o.a. de ziekte van Crohn, colitis ulcerosa en reumatoïde artritis.","definition":"<p><strong>TNF-α-remmers</strong> zoals infliximab, adalimumab en etanercept remmen een centraal pro-inflammatoir cytokine. Ze worden gebruikt bij IBD, reumatoïde artritis, spondyloartritis en psoriasis. Doordat ze de cellulaire afweer verzwakken, kan latente tuberculose reactiveren; daarom wordt vooraf gescreend. Ook het risico op andere infecties is verhoogd.</p>","image_url":"","wiki_title":"Infliximab","match":"tnf-alfaremmer","option_only":true},"biologicals: tnf-remmers":{"title":"Infliximab","short":"Infliximab is een monoklonaal antilichaam tegen TNF-α, gebruikt bij o.a. de ziekte van Crohn, colitis ulcerosa en reumatoïde artritis.","definition":"<p><strong>TNF-α-remmers</strong> zoals infliximab, adalimumab en etanercept remmen een centraal pro-inflammatoir cytokine. Ze worden gebruikt bij IBD, reumatoïde artritis, spondyloartritis en psoriasis. Doordat ze de cellulaire afweer verzwakken, kan latente tuberculose reactiveren; daarom wordt vooraf gescreend. Ook het risico op andere infecties is verhoogd.</p>","image_url":"","wiki_title":"Infliximab","match":"biologicals: tnf-remmers","option_only":true},"groep a bètahemolytische streptokokken":{"title":"Streptococcus pyogenes (groep A-streptokok)","short":"Groep A-streptokok: grampositieve, bètahemolytische kok in ketens die o.a. keelontsteking, impetigo, erysipelas en roodvonk veroorzaakt.","definition":"<p><strong><em>Streptococcus pyogenes</em></strong> koloniseert keel en huid. Het M-eiwit beschermt tegen fagocytose; pyrogene exotoxinen veroorzaken roodvonk en het toxischeshocksyndroom. Invasieve infecties zijn o.a. cellulitis en necrotiserende fasciitis. Na een infectie kunnen immunologische complicaties optreden: acuut reuma en poststreptokokken-glomerulonefritis. Penicilline is eerste keus.</p>","image_url":"","wiki_title":"Streptococcus pyogenes","match":"groep a bètahemolytische streptokokken","option_only":true},"streptokokkenfaryngitis (gas)":{"title":"Faryngitis","short":"Faryngitis is een ontsteking van de keel, meestal viraal, soms door groep A-streptokokken.","definition":"<p>De meeste <strong>keelontstekingen</strong> zijn viraal en gaan vanzelf over. Bij een bacteriële oorzaak (Centor-criteria: koorts, beslag, gezwollen pijnlijke halsklieren, geen hoest) kunnen antibiotica worden overwogen, vooral bij ernstige klachten of risicofactoren.</p>","image_url":"","wiki_title":"Pharyngitis","match":"streptokokkenfaryngitis (gas)","option_only":true},"humaan herpesvirus(hhv)-6 en -7":{"title":"Zesde ziekte (exanthema subitum)","short":"De zesde ziekte is een infectie met humaan herpesvirus 6 bij jonge kinderen: eerst enkele dagen hoge koorts, daarna, als de koorts zakt, een vlekjesuitslag.","definition":"<p><strong>Exanthema subitum</strong> treft vooral kinderen van 6 maanden tot 2 jaar. Kenmerkend is dat de huiduitslag pas verschijnt nadat de koorts is verdwenen. Koortsconvulsies kunnen optreden. Het verloopt meestal onschuldig.</p>","image_url":"","wiki_title":"Roseola","match":"humaan herpesvirus(hhv)-6 en -7","option_only":true},"adenovirusinfectie":{"title":"Adenovirus","short":"Adenovirussen zijn niet-omhulde DNA-virussen die verkoudheid, keelontsteking, conjunctivitis en gastro-enteritis veroorzaken.","definition":"<p><strong>Adenovirussen</strong> zijn niet-omhulde, dubbelstrengs DNA-virussen. Omdat ze geen envelop hebben, zijn ze stabiel in de omgeving en lastig te inactiveren.</p><p>Ze veroorzaken vooral bij kinderen infecties van de bovenste luchtwegen (faryngitis), conjunctivitis (o.a. faryngoconjunctivale koorts), gastro-enteritis en soms pneumonie. Ze worden ook gebruikt als vector in vaccins en gentherapie.</p>","image_url":"","wiki_title":"Adenoviridae","match":"adenovirusinfectie","option_only":true},"azathioprine (purine-antagonist)":{"title":"Azathioprine","short":"Azathioprine is een immunosuppressivum dat de purinesynthese remt en zo de deling van lymfocyten onderdrukt.","definition":"<p><strong>Azathioprine</strong> wordt omgezet in 6-mercaptopurine en dan in thioguanine-nucleotiden die in het DNA worden ingebouwd. Het wordt gebruikt bij IBD, auto-immuunhepatitis, vasculitis en na transplantatie. Bijwerkingen zijn beenmergsuppressie, levertoxiciteit en pancreatitis. Bij een TPMT-deficiëntie is het risico op ernstige beenmergsuppressie groot; allopurinol versterkt de werking.</p>","image_url":"","wiki_title":"Azathioprine","match":"azathioprine (purine-antagonist)","option_only":true},"methotrexaat (foliumzuurantagonist)":{"title":"Methotrexaat","short":"Methotrexaat is een foliumzuurantagonist; in lage dosis een basismiddel bij reumatoïde artritis en psoriasis, in hoge dosis een cytostaticum.","definition":"<p><strong>Methotrexaat</strong> remt dihydrofolaatreductase. In lage, wekelijkse dosering werkt het ontstekingsremmend (o.a. via adenosine) en is het een hoeksteen bij reumatoïde artritis, psoriasis en IBD; foliumzuur vermindert bijwerkingen. Bijwerkingen: beenmergsuppressie, levertoxiciteit, mucositis en pneumonitis. Het is teratogeen en wordt via de nier uitgescheiden.</p>","image_url":"","wiki_title":"Methotrexate","match":"methotrexaat (foliumzuurantagonist)","option_only":true},"epstein-barrvirusinfectie (ebv)":{"title":"Epstein-Barrvirus (EBV)","short":"EBV is een herpesvirus dat B-cellen infecteert; het veroorzaakt de ziekte van Pfeiffer en is geassocieerd met enkele kankers.","definition":"<p>Het <strong>Epstein-Barrvirus</strong> wordt via speeksel overgedragen. Op jonge leeftijd verloopt infectie vaak ongemerkt; bij adolescenten geeft het vaak mononucleosis infectiosa. Het virus blijft levenslang latent in B-cellen. EBV is geassocieerd met o.a. het Burkittlymfoom, het nasofarynxcarcinoom, sommige Hodgkinlymfomen en posttransplantatie-lymfoproliferatieve ziekte.</p>","image_url":"","wiki_title":"Epstein–Barr virus","match":"epstein-barrvirusinfectie (ebv)","option_only":true},"para-influenzavirus 2":{"title":"Para-influenzavirus","short":"Para-influenzavirussen zijn RNA-virussen die luchtweginfecties geven; ze zijn de belangrijkste verwekker van pseudokroep bij jonge kinderen.","definition":"<p><strong>Para-influenzavirussen</strong> (paramyxovirussen, type 1–4) veroorzaken vooral bij kinderen van 6 maanden tot 3 jaar een laryngotracheitis (pseudokroep), met een blafhoest, heesheid en inspiratoire stridor, vaak ’s nachts. Behandeling bij ernstige vormen met dexamethason.</p>","image_url":"","wiki_title":"Human parainfluenza viruses","match":"para-influenzavirus 2","option_only":true},"parvovirus b19 infectie":{"title":"Erythema infectiosum (vijfde ziekte)","short":"Erythema infectiosum is een kinderziekte door parvovirus B19 met felrode ‘slapwangen’ en daarna een kantachtige uitslag.","definition":"<p>Parvovirus B19 infecteert erytroïde voorlopercellen. Bij mensen met chronische hemolyse kan het een aplastische crise geven, en in de zwangerschap foetale anemie en hydrops. Bij volwassenen geeft het vaak symmetrische gewrichtsklachten.</p>","image_url":"","wiki_title":"Erythema infectiosum","match":"parvovirus b19 infectie","option_only":true},"cryptokokkenmenigitis":{"title":"Cryptococcus neoformans","short":"Cryptococcus neoformans is een gist met een dik kapsel die vooral bij afweergestoorden (hiv) meningitis veroorzaakt.","definition":"<p><strong><em>Cryptococcus neoformans</em></strong> komt voor in duivenpoep en grond en wordt ingeademd. Bij patiënten met een sterk verminderde cellulaire afweer verspreidt hij zich naar het CZS en veroorzaakt een subacute meningitis met hoofdpijn en verhoogde liquordruk. Diagnose met antigeentest in serum of liquor (vroeger Oost-Indische-inktkleuring); behandeling met amfotericine B en flucytosine.</p>","image_url":"","wiki_title":"Cryptococcus neoformans","match":"cryptokokkenmenigitis","option_only":true},"buiktyphus":{"title":"Buiktyfus","short":"Buiktyfus is een systemische infectie met Salmonella typhi, met hoge koorts, buikpijn en algemeen ziek-zijn.","definition":"<p>Bij <strong>buiktyfus</strong> is er een geleidelijk stijgende koorts met relatieve bradycardie, roseolen en hepatosplenomegalie. Complicaties zijn darmbloedingen en perforatie. Diagnose met bloedkweken; behandeling met antibiotica (ceftriaxon, azitromycine). Er is een vaccin voor reizigers.</p>","image_url":"","wiki_title":"Typhoid fever","match":"buiktyphus","option_only":true},"pneumocystis jiroveci pneumonie":{"title":"Pneumocystis jirovecii","short":"Pneumocystis jirovecii is een gistachtige schimmel die bij een sterk verminderde cellulaire afweer een interstitiële longontsteking veroorzaakt.","definition":"<p><strong>Pneumocystis</strong> groeit niet in standaardkweek en wordt aangetoond met PCR of zilverkleuring op sputum of BAL. Risicogroepen: hiv met laag CD4-getal, transplantatiepatiënten, langdurig hoge dosis corticosteroïden. Behandeling en profylaxe met co-trimoxazol.</p>","image_url":"","wiki_title":"Pneumocystis jirovecii","match":"pneumocystis jiroveci pneumonie","option_only":true},"immuungemedieerde trombocytopenie":{"title":"Immuuntrombocytopenie (ITP)","short":"Bij ITP breken auto-antistoffen tegen bloedplaatjes deze af, met een geïsoleerde trombocytopenie.","definition":"<p>Bij <strong>immuuntrombocytopenie</strong> worden plaatjes met antistoffen beladen en in de milt afgebroken; ook de aanmaak wordt geremd. Bij kinderen volgt het vaak op een virale infectie en herstelt het meestal spontaan; bij volwassenen is het vaker chronisch. Het is een diagnose na uitsluiting van andere oorzaken. Behandeling bij bloedingen of zeer lage waarden: corticosteroïden, immunoglobulinen, TPO-agonisten.</p>","image_url":"","wiki_title":"Immune thrombocytopenic purpura","match":"immuungemedieerde trombocytopenie","option_only":true},"een artritis":{"title":"Artritis","short":"Artritis is een ontsteking van een gewricht, met pijn, zwelling, warmte en bewegingsbeperking.","definition":"<p><strong>Artritis</strong> wordt ingedeeld naar het aantal gewrichten (mono-, oligo-, polyartritis) en de oorzaak: infectieus (septische artritis), kristalgeïnduceerd (jicht, pseudojicht), auto-immuun (reumatoïde artritis, spondyloartritis, SLE) of reactief. Bij een acute monoartritis is een gewrichtspunctie belangrijk om infectie en kristallen aan te tonen.</p>","image_url":"","wiki_title":"Arthritis","match":"een artritis","option_only":true},"uveitis":{"title":"Uveïtis anterior","short":"Uveïtis anterior is een ontsteking van iris en corpus ciliare, met een pijnlijk rood oog, lichtschuwheid en wazig zien.","definition":"<p>Bij <strong>uveïtis anterior</strong> zijn er cellen en flare in de voorste oogkamer, ciliaire injectie en soms een nauwe of onregelmatige pupil (synechieën). Het kan samenhangen met HLA-B27-gerelateerde ziekten, sarcoïdose, JIA of infecties. Behandeling met corticosteroïd- en pupilverwijdende druppels.</p>","image_url":"","wiki_title":"Uveitis","match":"uveitis","option_only":true},"mupirocinecrème":{"title":"Mupirocine","short":"Mupirocine is een lokaal antibioticum tegen stafylokokken en streptokokken, o.a. gebruikt bij impetigo en om MRSA-dragerschap in de neus te behandelen.","definition":"<p><strong>Mupirocine</strong> remt de bacteriële eiwitsynthese. Neuszalf wordt gebruikt voor dekolonisatie van <em>S. aureus</em> vóór bepaalde operaties en bij MRSA-dragerschap. Bij langdurig gebruik ontstaat resistentie.</p>","image_url":"","wiki_title":"Mupirocin","match":"mupirocinecrème","option_only":true},"eczema seborroicum infantum":{"title":"Seborroïsch eczeem","short":"Seborroïsch eczeem is een chronisch terugkerend eczeem met roodheid en vettige schilfers in talgklierrijke gebieden.","definition":"<p><strong>Seborroïsch eczeem</strong> komt voor op het behaarde hoofd, in de wenkbrauwen, nasolabiale plooien, achter de oren en op de borst. De gist <em>Malassezia</em> speelt een rol. Bij zuigelingen kennen we het als berg. Het komt vaker voor bij de ziekte van Parkinson en hiv. Behandeling met antimycotische middelen, eventueel kort met een mild corticosteroïd.</p>","image_url":"","wiki_title":"Seborrhoeic dermatitis","match":"eczema seborroicum infantum","option_only":true},"eczema seborrhoïcum":{"title":"Seborroïsch eczeem","short":"Seborroïsch eczeem is een chronisch terugkerend eczeem met roodheid en vettige schilfers in talgklierrijke gebieden.","definition":"<p><strong>Seborroïsch eczeem</strong> komt voor op het behaarde hoofd, in de wenkbrauwen, nasolabiale plooien, achter de oren en op de borst. De gist <em>Malassezia</em> speelt een rol. Bij zuigelingen kennen we het als berg. Het komt vaker voor bij de ziekte van Parkinson en hiv. Behandeling met antimycotische middelen, eventueel kort met een mild corticosteroïd.</p>","image_url":"","wiki_title":"Seborrhoeic dermatitis","match":"eczema seborrhoïcum","option_only":true},"acute pyelonefritis":{"title":"Pyelonefritis","short":"Pyelonefritis is een bacteriële infectie van het nierbekken en de nier, met koorts, flankpijn en vaak klachten van een blaasontsteking.","definition":"<p><strong>Pyelonefritis</strong> is een opstijgende urineweginfectie die de nier en het nierbekken bereikt, meestal door <em>E. coli</em>.</p><p>Kenmerkend zijn koorts, koude rillingen, flankpijn en slagpijn in de nierloge, eventueel met mictieklachten. Het is een gecompliceerde urineweginfectie die behandeld wordt met antibiotica met goede weefselpenetratie (niet nitrofurantoïne).</p>","image_url":"","wiki_title":"Pyelonephritis","match":"acute pyelonefritis","option_only":true},"acute osteomyelitis":{"title":"Osteomyelitis","short":"Osteomyelitis is een infectie van het bot, meestal door Staphylococcus aureus.","definition":"<p><strong>Osteomyelitis</strong> ontstaat via de bloedbaan (vooral bij kinderen in de metafysen van lange pijpbeenderen), vanuit een nabijgelegen infectie (bijv. diabetische voet, decubitus) of na een open fractuur of operatie. Klachten: pijn, koorts, zwelling. Diagnose met MRI en kweek (bot of bloed). Chronische osteomyelitis met dood bot (sequester) vergt vaak chirurgie naast langdurige antibiotica.</p>","image_url":"","wiki_title":"Osteomyelitis","match":"acute osteomyelitis","option_only":true},"post-operatieve wondinfectie":{"title":"Wondinfectie","short":"Een wondinfectie is een infectie van een (operatie)wond, met roodheid, warmte, pijn, zwelling en eventueel pus.","definition":"<p>Postoperatieve <strong>wondinfecties</strong> worden vaak veroorzaakt door <em>S. aureus</em> of, bij darmchirurgie, door darmbacteriën. Risicofactoren zijn diabetes, obesitas, roken, lange operaties en contaminatie. Behandeling: openen en draineren, eventueel antibiotica.</p>","image_url":"","wiki_title":"Surgical site infection","match":"post-operatieve wondinfectie","option_only":true},"demodexfolliculitis":{"title":"Demodexfolliculitis","short":"Bij demodexfolliculitis veroorzaakt een overmaat aan haarzakjesmijten (Demodex) jeukende puistjes in het gezicht.","definition":"<p><strong>Demodex</strong>-mijten komen bij vrijwel iedereen voor. Een overgroei (bijv. bij langdurig gebruik van corticosteroïdcrème of verminderde afweer) geeft een rosacea-achtig beeld. Behandeling met ivermectine- of permetrinecrème.</p>","image_url":"","wiki_title":"Demodicosis","match":"demodexfolliculitis","option_only":true},"oog":{"title":"Het oor","short":"Het oor bestaat uit buiten-, midden- en binnenoor en verzorgt het gehoor en het evenwicht.","definition":"<p>Het <strong>oor</strong> is opgebouwd uit drie delen. Het <em>buitenoor</em> (oorschelp en gehoorgang) vangt geluid op; het <em>middenoor</em> (trommelvlies en gehoorbeentjes hamer, aambeeld en stijgbeugel) versterkt de trillingen; het <em>binnenoor</em> zet ze om in zenuwsignalen.</p><p>Het binnenoor bevat het slakkenhuis (cochlea) voor het gehoor en het vestibulaire systeem (halfcirkelvormige kanalen, utriculus en sacculus) voor evenwicht. Signalen lopen via de n. vestibulocochlearis (VIII) naar de hersenstam.</p>","image_url":"","wiki_title":"Ear","match":"oog","option_only":true},"coxsackievirus a":{"title":"Coxsackievirus A (hand-voet-mondziekte)","short":"Coxsackievirus A is een enterovirus dat bij jonge kinderen hand-voet-mondziekte en herpangina veroorzaakt.","definition":"<p>Bij <strong>hand-voet-mondziekte</strong> ontstaan blaasjes en zweertjes in de mond en blaasjes op handpalmen, voetzolen en billen. Het verloopt meestal mild. Overdracht via feces, speeksel en blaasjesvocht.</p>","image_url":"","wiki_title":"Hand, foot, and mouth disease","match":"coxsackievirus a|hand-voet-mondziekte|hand-mond-voetziekte|herpangina","option_only":true},"cellulaire immuniteit":{"title":"Cellulaire immuniteit","short":"Cellulaire immuniteit is het deel van de verworven afweer dat via T-cellen werkt, vooral tegen intracellulaire ziekteverwekkers.","definition":"<p>Bij <strong>cellulaire immuniteit</strong> doden cytotoxische CD8-T-cellen geïnfecteerde cellen en activeren CD4-Th1-cellen macrofagen. Stoornissen (bijv. hiv, transplantatiemedicatie) geven infecties met virussen, mycobacteriën, schimmels en <em>Pneumocystis</em>. Humorale immuniteit verloopt via antistoffen van B-cellen.</p>","image_url":"","wiki_title":"Cell-mediated immunity","match":"cellulaire immuniteit|celgemedieerde immuniteit","option_only":true},"hand-voet-mond ziekte":{"title":"Coxsackievirus A (hand-voet-mondziekte)","short":"Coxsackievirus A is een enterovirus dat bij jonge kinderen hand-voet-mondziekte en herpangina veroorzaakt.","definition":"<p>Bij <strong>hand-voet-mondziekte</strong> ontstaan blaasjes en zweertjes in de mond en blaasjes op handpalmen, voetzolen en billen. Het verloopt meestal mild. Overdracht via feces, speeksel en blaasjesvocht.</p>","image_url":"","wiki_title":"Hand, foot, and mouth disease","match":"hand-voet-mond ziekte","option_only":true},"sterk verhoogd c-reactief proteïne (crp)":{"title":"CRP","short":"C-reactief proteïne; ontstekingseiwit in het bloed dat helpt de kans op een gecompliceerde infectie in te schatten.","definition":"<p>Het CRP stijgt bij ontsteking of infectie; in de huisartsenpraktijk stuurt het het antibioticabeleid bij luchtweginfecties.</p>","image_url":"","wiki_title":"C-reactive_protein","match":"sterk verhoogd c-reactief proteïne (crp)","option_only":true},"erysipelas":{"title":"Erysipelas","short":"Wondroos: een scherp begrensde, oppervlakkige huidinfectie (dermis) meestal door streptokokken. Geeft een rode, warme, pijnlijke huid vaak met koorts.","definition":"<p><strong>Erysipelas</strong> (wondroos) is een acute infectie van de bovenste dermis en oppervlakkige lymfevaten, meestal door groep A-streptokokken. Kenmerkend zijn een scherp begrensde felrode zwelling, koorts en algemeen ziek-zijn; het is een belangrijke differentiaaldiagnose van DVT.</p>","image_url":"","wiki_title":"Erysipelas","match":"erysipelas","option_only":true},"encefalitis":{"title":"Encefalitis","short":"Ontsteking van het hersenweefsel zelf, meestal door een virus.","definition":"<p>Bij <b>encefalitis</b> is het hersenparenchym ontstoken. De meest bekende oorzaak in Nederland is het herpes simplexvirus (vaak temporaal); daarnaast o.a. andere virussen, auto-immuunencefalitis (zoals anti-NMDA-receptorencefalitis) en postinfectieuze vormen. Klachten: koorts, hoofdpijn, verwardheid, gedragsverandering, epileptische aanvallen en focale uitval. Behandeling bij verdenking: direct aciclovir.</p>","image_url":"","wiki_title":"Encephalitis","match":"encefalitis","option_only":true},"peesruptuur":{"title":"Peesruptuur","short":"Een peesruptuur is een (gedeeltelijke) scheur van een pees. Fluorochinolonen kunnen het risico hierop verhogen.","definition":"<p>Een <strong>peesruptuur</strong> is een scheur van een pees, klassiek de achillespees. <em>Fluorochinolonen</em> (ciprofloxacine, moxifloxacine) verhogen het risico, vooral bij ouderen en bij gelijktijdig corticosteroïdgebruik.</p>","image_url":"","wiki_title":"","match":"peesruptuur","option_only":true},"geneesmiddelreactie":{"title":"Geneesmiddelreactie (exantheem)","short":"Een geneesmiddelreactie is een huiduitslag door een medicijn, klassiek een maculopapuleus exantheem tijdens antibioticagebruik. Alarmsignalen zijn slijmvliesbetrokkenheid.","definition":"<p><b>Geneesmiddelexantheem</b> ontstaat vaak 1-2 weken na start van het middel. Betrokkenheid van slijmvliezen wijst op ernstige reacties (SJS/TEN).</p>","image_url":"","wiki_title":"Drug_eruption","match":"geneesmiddelreactie","option_only":true},"non-steroïdale anti-inflammatoire drugs (nsaids)":{"title":"NSAID","short":"Non-steroidal anti-inflammatory drug (aspirine, ibuprofen); remt COX-enzymen en daarmee ontsteking en plaatjesaggregatie.","definition":"<p><b>NSAID's</b> remmen cyclo-oxygenase: ontstekingsremmend en pijnstillend, maar met bloedingsrisico en maagslijmvliesschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"non-steroïdale anti-inflammatoire drugs (nsaids)","option_only":true},"streptococcus agalactiae (groep b streptokok)":{"title":"Groep B-streptokok (GBS)","short":"De groep B-streptokok (Streptococcus agalactiae) komt voor in darm en vagina en is een belangrijke verwekker van sepsis en meningitis bij pasgeborenen.","definition":"<p><strong>Groep B-streptokokken</strong> (<em>Streptococcus agalactiae</em>) zijn grampositieve, bètahemolytische ketenkokken. Ze komen bij een deel van de vrouwen voor in darm en vagina zonder klachten.</p><p>Tijdens de bevalling kan de baby besmet raken, met risico op neonatale sepsis, pneumonie en meningitis (vooral in de eerste levensdagen). Bij risicofactoren krijgt de moeder antibiotica tijdens de bevalling.</p>","image_url":"","wiki_title":"Group B streptococcal infection","match":"streptococcus agalactiae (groep b streptokok)","option_only":true},"lipoteichoïne zuur":{"title":"Teichoïnezuur","short":"Teichoïnezuren zijn polymeren in de dikke peptidoglycaanlaag van grampositieve bacteriën; ze dragen bij aan hechting en ontstekingsactivatie.","definition":"<p><strong>Teichoïnezuren</strong> zijn polymeren van glycerol- of ribitolfosfaat die verankerd zijn in de peptidoglycaanlaag (wandteichoïnezuur) of in de celmembraan (lipoteichoïnezuur) van <em>grampositieve</em> bacteriën.</p><p>Ze geven de celwand een negatieve lading, helpen bij hechting aan gastheercellen en worden door Toll-like receptoren (TLR2) herkend, waardoor ze een ontstekingsreactie uitlokken. Gramnegatieve bacteriën hebben ze niet.</p>","image_url":"","wiki_title":"Teichoic acid","match":"lipoteichoïne zuur","option_only":true},"eczeem":{"title":"Eczeem","short":"Eczeem is een oppervlakkige, jeukende ontsteking van de huid; acuut gekenmerkt door roodheid en vesikels, chronisch door lichenificatie en schilfering.","definition":"<p><strong>Eczeem</strong> (dermatitis) is een spongiotische huidontsteking. <em>Acuut</em>: erytheem, vesikels, nattend, jeuk — histologisch <em>spongiose</em> (intercellulair oedeem). <em>Chronisch</em>: lichenificatie, schilfering, hyperkeratose.</p><p>Vormen: constitutioneel (atopisch) eczeem, allergisch contacteczeem (type IV, plakproeven positief) en orthoergisch/irritatief contacteczeem (niet-immunologisch).</p>","image_url":"","wiki_title":"Dermatitis","match":"eczeem","option_only":true},"rna polymerase":{"title":"RNA-polymerase","short":"RNA-polymerase is het enzym dat tijdens transcriptie een RNA-streng synthetiseert op basis van een DNA-sjabloon.","definition":"<p><strong>RNA-polymerase</strong> leest de DNA-matrijs af en bouwt complementair RNA. Bij eukaryoten doet RNA-polymerase II het mRNA.</p>","image_url":"","wiki_title":"RNA polymerase","match":"rna polymerase","option_only":true},"compressietherapie (steunkousen/zwachtels)":{"title":"Compressietherapie","short":"Bij compressietherapie wordt met zwachtels of therapeutisch elastische kousen druk op het been uitgeoefend om de veneuze en lymfatische afvoer te verbeteren.","definition":"<p><strong>Compressie</strong> is de basis van de behandeling van chronische veneuze insufficiëntie, een ulcus cruris venosum, lymfoedeem en het posttrombotisch syndroom. Bij ernstig arterieel vaatlijden is het gecontra-indiceerd; daarom wordt eerst de enkel-armindex gemeten.</p>","image_url":"","wiki_title":"Compression therapy","match":"compressietherapie (steunkousen/zwachtels)","option_only":true},"aneurysma aortae":{"title":"Aneurysma aortae","short":"Blijvende, lokale verwijding van de aorta; op een thoraxfoto zichtbaar als een verbrede aortaschaduw.","definition":"<p>Een <b>aneurysma van de aorta</b> is een pathologische verwijding van de vaatwand. Ruptuur is levensbedreigend.</p>","image_url":"","wiki_title":"Aortic aneurysm","match":"aneurysma aortae","option_only":true},"herpes stomatitis (ontstoken mondslijmvlies)":{"title":"Gingivostomatitis herpetica","short":"Gingivostomatitis herpetica is de primaire infectie met HSV-1 bij jonge kinderen, met pijnlijke blaasjes en zweertjes in de mond en koorts.","definition":"<p>Bij <strong>gingivostomatitis herpetica</strong> zijn er pijnlijke aften op tong, gehemelte en tandvlees, met gezwollen tandvlees, kwijlen, koorts en weigeren te drinken. Het risico op uitdroging is de belangrijkste complicatie. Vroeg gestart aciclovir kan het beloop verkorten.</p>","image_url":"","wiki_title":"Herpetic gingivostomatitis","match":"herpes stomatitis (ontstoken mondslijmvlies)","option_only":true},"specifiek(e) ige":{"title":"Specifiek IgE (RAST)","short":"Met een RAST of specifiek-IgE-bepaling wordt in het bloed gemeten of iemand IgE-antistoffen tegen een bepaald allergeen heeft.","definition":"<p>De bepaling van <strong>specifiek IgE</strong> is een alternatief voor de huidpriktest, bijvoorbeeld bij uitgebreid eczeem of als antihistaminica niet gestopt kunnen worden. Ook hier geldt: sensibilisatie is niet hetzelfde als allergie.</p>","image_url":"","wiki_title":"Radioallergosorbent test","match":"specifiek(e) ige","option_only":true},"bepalen van urineretentie (bladderscan)":{"title":"Bladderscan","short":"Echografisch onderzoek om het urineresidu in de blaas na mictie te bepalen.","definition":"<p>Een bladderscan is een niet-invasieve echografische meting van het blaasvolume, gebruikt om urineretentie (residu na mictie) vast te stellen zonder katheterisatie.</p>","image_url":"","wiki_title":"","match":"bepalen van urineretentie (bladderscan)","option_only":true},"reverse transcriptase":{"title":"Reverse transcriptase","short":"Reverse transcriptase is een enzym van retrovirussen dat RNA omschrijft naar DNA — een karakteristieke eigenschap van bijv. hiv.","definition":"<p><strong>Reverse transcriptase</strong> is een RNA-afhankelijk DNA-polymerase. Het maakt van het virale RNA-genoom een DNA-kopie en is het aangrijpingspunt van meerdere antiretrovirale middelen.</p>","image_url":"","wiki_title":"Reverse transcriptase","match":"reverse transcriptase","option_only":true},"rna-polymerase":{"title":"RNA-polymerase","short":"RNA-polymerase is het enzym dat tijdens transcriptie een RNA-streng synthetiseert op basis van een DNA-sjabloon.","definition":"<p><strong>RNA-polymerase</strong> leest de DNA-matrijs af en bouwt complementair RNA. Bij eukaryoten doet RNA-polymerase II het mRNA.</p>","image_url":"","wiki_title":"RNA polymerase","match":"rna-polymerase","option_only":true},"pneumonitis":{"title":"Pneumonitis","short":"Ontsteking van het longweefsel; een typische immuun-gerelateerde bijwerking van immunotherapie.","definition":"<p><b>Pneumonitis</b> is een niet-infectieuze ontsteking van het longparenchym. Als immuun-gemedieerde bijwerking van checkpointremmers kan het ernstig zijn en behandeling met corticosteroïden vereisen.</p>","image_url":"","wiki_title":"Pneumonitis","match":"pneumonitis","option_only":true},"d-dimeer":{"title":"D-dimeer","short":"Afbraakproduct van fibrine; een normale waarde sluit bij lage verdenking een trombose/longembolie vrijwel uit.","definition":"<p>D-dimeer is een fibrinolyse-afbraakproduct. Een normale waarde bij lage klinische verdenking sluit een longembolie uit; een verhoogde waarde is aspecifiek en vereist beeldvorming.</p>","image_url":"","wiki_title":"","match":"d-dimeer","option_only":true},"iga protease":{"title":"IgA-protease","short":"IgA-protease is een bacteriële virulentiefactor die het mucosale antistof IgA afbreekt, waardoor kolonisatie van slijmvliezen wordt vergemakkelijkt.","definition":"<p><b>IgA-protease</b> wordt geproduceerd door o.a. Neisseria en pneumokokken en helpt de bacterie de mucosale afweer te omzeilen.</p>","image_url":"","wiki_title":"","match":"iga protease","option_only":true},"surmenage":{"title":"Surmenage","short":"Overbelasting door aanhoudende stress; nauw verwant aan overspanning en aanpassingsstoornis.","definition":"<p><b>Surmenage</b> is een toestand van overbelasting door langdurige of overmatige (psychische) inspanning en stress, waarbij lichamelijke en psychische klachten optreden. De term overlapt met overspanning en aanpassingsstoornis.</p>","image_url":"","wiki_title":"","match":"surmenage","option_only":true},"humaan metapneumovirus":{"title":"Humaan Metapneumovirus (HMPV)","short":"RSV-verwant virus dat bij jonge kinderen bronchiolitis en pneumonie kan geven, met een vergelijkbaar klinisch beeld als RSV.","definition":"<p><b>Humaan Metapneumovirus (HMPV)</b> is nauw verwant aan RSV en veroorzaakt luchtweginfecties bij jonge kinderen, variërend van verkoudheid tot bronchiolitis en pneumonie. Het beeld lijkt sterk op dat van RSV.</p>","image_url":"","wiki_title":"Human metapneumovirus","match":"humaan metapneumovirus","option_only":true},"iga-protease":{"title":"IgA-protease","short":"IgA-protease is een bacteriële virulentiefactor die het mucosale antistof IgA afbreekt, waardoor kolonisatie van slijmvliezen wordt vergemakkelijkt.","definition":"<p><b>IgA-protease</b> wordt geproduceerd door o.a. Neisseria en pneumokokken en helpt de bacterie de mucosale afweer te omzeilen.</p>","image_url":"","wiki_title":"","match":"iga-protease","option_only":true},"fimbriae":{"title":"Fimbriae (pili)","short":"Fimbriae zijn korte haarachtige uitsteeksels op bacteriën die dienen voor aanhechting aan gastheercellen, zoals E. coli aan het blaasepitheel bij urineweginfecties.","definition":"<p><strong>Fimbriae</strong> (pili) zijn dunne eiwit-uitsteeksels op het bacterieoppervlak die zorgen voor <em>adhesie</em> aan gastheerweefsel. Bij uropathogene <em>Escherichia coli</em> maken fimbriae (o.a. type-1 en P-pili) hechting aan het uro-epitheel mogelijk, een cruciale eerste stap bij urineweginfecties. Flagellen dienen daarentegen voor voortbeweging.</p>","image_url":"","wiki_title":"Fimbria (bacteriology)","match":"fimbriae","option_only":true},"saturatie":{"title":"Zuurstofsaturatie","short":"Percentage hemoglobine dat met zuurstof is verzadigd; maat voor de oxygenatie.","definition":"<p>De (perifere) zuurstofsaturatie (SpO2) geeft aan welk deel van het hemoglobine met O2 is verzadigd. Bij CO-vergiftiging kan de SpO2 vals-normaal zijn.</p>","image_url":"","wiki_title":"Oxygen saturation (medicine)","match":"saturatie","option_only":true},"dermatomyositis":{"title":"Dermatomyositis","short":"Dermatomyositis is een auto-immune ontsteking van spieren en huid, met proximale spierzwakte, een heliotrope rash rond de ogen en Gottron-papels op de vingers.","definition":"<p><strong>Dermatomyositis</strong> is een idiopathische inflammatoire myopathie. Kenmerkend zijn symmetrische proximale spierzwakte, verhoogde spierenzymen (CK, aldolase, LDH) en typische huidafwijkingen: <em>heliotrope rash</em> (paars-rood rond de ogen) en <em>Gottron-papels</em> op de knokkels.</p>","image_url":"","wiki_title":"Dermatomyositis","match":"dermatomyositis","option_only":true},"aanwezigheid van hla b27 antigeen":{"title":"HLA-B27","short":"HLA-B27 is een MHC klasse I-variant die sterk geassocieerd is met spondyloartritiden zoals de ziekte van Bechterew.","definition":"<p>Dragers van <strong>HLA-B27</strong> hebben een sterk verhoogd risico op axiale spondyloartritis, reactieve artritis, uveïtis anterior en artritis bij IBD of psoriasis. Toch krijgt de grote meerderheid van de dragers nooit een van deze ziekten, en een deel van de patiënten is HLA-B27-negatief: de test ondersteunt de diagnose, maar bewijst haar niet.</p>","image_url":"","wiki_title":"HLA-B27","match":"aanwezigheid van hla b27 antigeen","option_only":true},"s. epidermidis":{"title":"Staphylococcus epidermidis","short":"S. epidermidis is een coagulasenegatieve stafylokok van de normale huidflora; berucht om infecties van lijnen en prothesen.","definition":"<p><strong><em>Staphylococcus epidermidis</em></strong> is een grampositieve, <em>coagulase-negatieve</em> stafylokok die normaal op de huid leeft.</p><p>Hij is weinig virulent, maar kan een <em>biofilm</em> vormen op kunstmateriaal. Daardoor is hij een belangrijke verwekker van infecties van intravasculaire katheters, kunstkleppen en gewrichtsprothesen. In een bloedkweek is hij ook vaak een verontreiniging vanuit de huid.</p>","image_url":"","wiki_title":"Staphylococcus epidermidis","match":"s. epidermidis","option_only":true},"bursitis subacromialis":{"title":"Bursitis subacromialis","short":"Bursitis subacromialis is een ontsteking van de slijmbeurs onder het acromion in de schouder, met pijn bij bewegen.","definition":"<p><strong>Bursitis subacromialis</strong> is ontsteking van de subacromiale slijmbeurs. Na een corticosteroïdinjectie moet bij hernieuwde, koortsende pijn een septische artritis worden uitgesloten.</p>","image_url":"","wiki_title":"","match":"bursitis subacromialis","option_only":true},"humaan papilloma virus":{"title":"Humaan papillomavirus (HPV)","short":"HPV is een DNA-virus dat wratten veroorzaakt; hoog-risicotypes (o.a. 16 en 18) veroorzaken baarmoederhalskanker en andere kankers.","definition":"<p>Het <strong>humaan papillomavirus</strong> infecteert basale cellen van huid en slijmvlies. Laag-risicotypes (6, 11) geven wratten en condylomata acuminata. Hoog-risicotypes maken de eiwitten E6 en E7, die p53 en Rb uitschakelen; persisterende infectie kan leiden tot cervixcarcinoom en kankers van anus, vulva, penis en orofarynx. Er is een vaccin en een bevolkingsonderzoek met hrHPV-test.</p>","image_url":"","wiki_title":"Human papillomavirus infection","match":"humaan papilloma virus","option_only":true},"giardia":{"title":"Giardiasis","short":"Giardiasis is een darminfectie met de protozo Giardia lamblia, met langdurige diarree, opgeblazen gevoel en vetrijke ontlasting.","definition":"<p><strong><em>Giardia lamblia</em></strong> wordt via cysten in besmet water of voedsel opgelopen. De trofozoïeten hechten aan het dunnedarmepitheel zonder het te binnendringen. Klachten: waterige, vettige, stinkende ontlasting, buikkrampen, winderigheid en gewichtsverlies, soms wekenlang. Diagnose met PCR of microscopie van ontlasting; behandeling met metronidazol of tinidazol.</p>","image_url":"","wiki_title":"Giardiasis","match":"giardia","option_only":true},"bacteroides spp":{"title":"Bacteroides","short":"Bacteroides zijn gramnegatieve, anaerobe staven en de belangrijkste bacteriën in de dikke darm.","definition":"<p><strong><em>Bacteroides fragilis</em></strong> is een belangrijke verwekker van intra-abdominale abcessen en peritonitis, vaak samen met aerobe darmbacteriën. Effectieve middelen zijn metronidazol, amoxicilline/clavulaanzuur en carbapenems.</p>","image_url":"","wiki_title":"Bacteroides","match":"bacteroides spp|bacteroides|bacteroides fragilis","option_only":true},"virale conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies met een rood oog, waterig, slijmerig of etterig vocht, en een normale visus.","definition":"<p>Een <strong>virale conjunctivitis</strong> (vaak adenovirus) is zeer besmettelijk, met waterig vocht en een gezwollen klier voor het oor. Een bacteriële vorm geeft meer pus en dichtgeplakte ogen; een allergische vorm jeuk. Pijn, lichtschuwheid en verminderde visus wijzen op een ernstigere oorzaak.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"virale conjunctivitis|bacteriële conjunctivitis|allergische conjunctivitis","option_only":true},"bloedkweek":{"title":"Bloedkweek","short":"Een bloedkweek onderzoekt of er bacteriën of schimmels in het bloed zitten (bacteriëmie).","definition":"<p>Bij verdenking op sepsis of endocarditis worden minimaal twee sets <strong>bloedkweken</strong> afgenomen vóór het starten van antibiotica. Een kweek met huidbacteriën (bijv. coagulasenegatieve stafylokokken) in één fles is vaak een verontreiniging.</p>","image_url":"","wiki_title":"Blood culture","match":"bloedkweek|bloedkweken","option_only":true},"diverticulosis/itis":{"title":"Diverticulose en diverticulitis","short":"Bij diverticulose zijn er uitstulpingen van het slijmvlies door de wand van het colon; als zo'n divertikel ontsteekt, heet het diverticulitis.","definition":"<p><strong>Diverticulose</strong> komt in westerse landen vooral voor in het sigmoïd, bij ouderen en bij een vezelarm dieet. Diverticulitis geeft pijn linksonder en koorts; complicaties zijn een abces, perforatie en fistels. Divertikels kunnen ook pijnloos een forse bloeding geven.</p>","image_url":"","wiki_title":"Diverticular disease","match":"diverticulosis/itis|diverticulose|diverticulitis|divertikelbloeding in het colon","option_only":true},"parotitis":{"title":"Parotitis","short":"Parotitis is een ontsteking van de oorspeekselklier, viraal (bof) of bacterieel.","definition":"<p><strong>Bof</strong> (mumps) geeft een pijnlijke zwelling van de parotis aan een of beide kanten; complicaties zijn orchitis, meningitis en pancreatitis. Een bacteriële parotitis (vaak <em>S. aureus</em>) komt vooral voor bij uitgedroogde ouderen, met pus uit de afvoergang.</p>","image_url":"","wiki_title":"Parotitis","match":"parotitis|bof","option_only":true},"erythromycine":{"title":"Erytromycine (macroliden)","short":"Erytromycine is een macrolide-antibioticum dat de eiwitsynthese remt via het 50S-ribosoom.","definition":"<p><strong>Macroliden</strong> werken tegen streptokokken, atypische verwekkers (Mycoplasma, Chlamydia, Legionella) en kinkhoest. Erytromycine stimuleert ook de maaglediging (motilinereceptor). Bijwerkingen: maag-darmklachten, QT-verlenging en interacties via CYP3A4 (vooral erytromycine en claritromycine).</p>","image_url":"","wiki_title":"Erythromycin","match":"erythromycine|erytromycine|macroliden|azitromycine|claritromycine","option_only":true},"gentamicine":{"title":"Gentamicine (aminoglycosiden)","short":"Gentamicine is een aminoglycoside dat werkt tegen gramnegatieve bacteriën door de eiwitsynthese via het 30S-ribosoom te verstoren.","definition":"<p><strong>Aminoglycosiden</strong> werken concentratieafhankelijk en worden vaak eenmaal daags gegeven, met spiegelbepalingen. Bijwerkingen zijn nefrotoxiciteit en (blijvende) ototoxiciteit. Ze werken niet tegen anaeroben.</p>","image_url":"","wiki_title":"Gentamicin","match":"gentamicine|aminoglycosiden|tobramycine|amikacine","option_only":true},"levofloxacine":{"title":"Fluorochinolonen","short":"Levofloxacine en ciprofloxacine zijn fluorochinolonen, die bacterieel DNA-gyrase en topo-isomerase IV remmen.","definition":"<p><strong>Fluorochinolonen</strong> werken breed, ook bij gramnegatieve bacteriën en (levofloxacine, moxifloxacine) bij luchtwegpathogenen. Ze hebben ernstige bijwerkingen: peesrupturen, QT-verlenging, aneurysma's en neuropathie, en worden daarom terughoudend gebruikt.</p>","image_url":"","wiki_title":"Fluoroquinolone","match":"levofloxacine|ciprofloxacine|moxifloxacine|fluorochinolonen","option_only":true},"d-dimeer bepalen":{"title":"D-dimeer","short":"D-dimeer is een afbraakproduct van fibrine; een normale waarde maakt trombose of longembolie onwaarschijnlijk bij een laag klinisch risico.","definition":"<p><strong>D-dimeer</strong> is gevoelig maar niet specifiek: het is ook verhoogd na operaties, bij infecties, kanker, zwangerschap en ouderdom. Daarom wordt het alleen gebruikt in combinatie met een beslisregel (Wells, YEARS).</p>","image_url":"","wiki_title":"D-dimer","match":"d-dimeer bepalen|d-dimeer|d-dimeren","option_only":true},"groep- b- streptokok":{"title":"Groep B-streptokok (GBS)","short":"De groep B-streptokok (Streptococcus agalactiae) komt bij veel vrouwen in vagina en darm voor en kan bij pasgeborenen sepsis en meningitis veroorzaken.","definition":"<p>Bij risicofactoren (vroeggeboorte, langdurig gebroken vliezen, koorts tijdens de bevalling, een eerder kind met GBS-ziekte) krijgt de moeder antibiotica tijdens de bevalling. Bij volwassenen geeft <strong>GBS</strong> soms urineweginfecties en huidinfecties.</p>","image_url":"","wiki_title":"Streptococcus agalactiae","match":"groep- b- streptokok|groep b-streptokok|streptococcus agalactiae","option_only":true},"aspergillus spp":{"title":"Aspergillus fumigatus","short":"Aspergillus fumigatus is een schimmel waarvan de sporen overal in de lucht zijn; bij neutropenie kan hij een invasieve longinfectie geven.","definition":"<p><strong><em>Aspergillus</em></strong> kan verschillende ziektebeelden geven: allergische bronchopulmonale aspergillose (bij astma en CF), een aspergilloom (schimmelbal in een bestaande holte) en invasieve aspergillose bij ernstig afweergestoorde patiënten, met invasie van bloedvaten. Diagnostiek met CT, galactomannan en kweek; behandeling met voriconazol.</p>","image_url":"","wiki_title":"Aspergillus fumigatus","match":"aspergillus spp","option_only":true},"bloedkweken":{"title":"Bloedkweek","short":"Een bloedkweek onderzoekt of er bacteriën of schimmels in het bloed zitten (bacteriëmie).","definition":"<p>Bij verdenking op sepsis of endocarditis worden minimaal twee sets <strong>bloedkweken</strong> afgenomen vóór het starten van antibiotica. Een kweek met huidbacteriën (bijv. coagulasenegatieve stafylokokken) in één fles is vaak een verontreiniging.</p>","image_url":"","wiki_title":"Blood culture","match":"bloedkweken","option_only":true},"stafylokok":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"stafylokok","option_only":true},"amoxicilline met clavulaanzuur":{"title":"Amoxicilline-clavulaanzuur","short":"Amoxicilline-clavulaanzuur combineert een penicilline met een bètalactamaseremmer, waardoor ook bètalactamasevormende bacteriën worden gedekt.","definition":"<p>Clavulaanzuur heeft zelf nauwelijks antibacteriële werking maar remt veel <em>bètalactamasen</em>, zodat amoxicilline niet wordt afgebroken. De combinatie werkt daardoor ook tegen o.a. <em>S. aureus</em> (geen MRSA), <em>H. influenzae</em>, <em>Moraxella</em>, veel <em>E. coli</em> en anaeroben zoals <em>Bacteroides</em>. Bijwerkingen: diarree en (zelden) cholestatische hepatitis.</p>","image_url":"","wiki_title":"Amoxicillin/clavulanic acid","match":"amoxicilline met clavulaanzuur","option_only":true},"gastro-enteritis, mogelijk het norovirus":{"title":"Norovirus","short":"Norovirus is een zeer besmettelijk RNA-virus dat acute gastro-enteritis veroorzaakt met plotseling braken en diarree, vaak in uitbraken.","definition":"<p>Het <strong>norovirus</strong> is een niet-omhuld RNA-virus (calicivirus). Er zijn maar weinig deeltjes nodig voor infectie en het overleeft lang in de omgeving.</p><p>Het veroorzaakt acute gastro-enteritis met plotseling braken, waterige diarree en buikkrampen, die 1 à 3 dagen duurt. Uitbraken komen vooral voor in verpleeghuizen, ziekenhuizen en op cruiseschepen; handhygiëne is de belangrijkste maatregel.</p>","image_url":"","wiki_title":"Norovirus","match":"gastro-enteritis, mogelijk het norovirus","option_only":true},"colorectaal carcinoom":{"title":"Colorectaal carcinoom","short":"Het colorectaal carcinoom is een adenocarcinoom van de dikke darm, meestal ontstaan uit een adenoom.","definition":"<p>Een tumor <strong>links</strong> geeft vaak een veranderd ontlastingspatroon en bloed bij de ontlasting; een tumor <strong>rechts</strong> vaker een ijzergebreksanemie. Risicofactoren: leeftijd, familie, IBD, Lynch-syndroom en FAP. In Nederland is er een bevolkingsonderzoek met een FIT-test.</p>","image_url":"","wiki_title":"Colorectal cancer","match":"colorectaal carcinoom|darmkanker|coloncarcinoom|rectumcarcinoom","option_only":true}};
